      {
        id: "destination_location",
        header: "Lokasi Tujuan",
        cell: ({ row }) => (
          <span className="text-foreground">
            {row.original.destination_location?.location_name ?? "—"}
          </span>
        ),
      },
      {
        id: "items_count",
        header: "Jumlah Item",
        cell: ({ row }) => (
          <span className="tabular-nums text-foreground">
            {row.original.items?.length ?? 0} item
          </span>
        ),
      },
      {
        id: "actions",
