      <div className="grid grid-cols-3 gap-3 lg:grid-cols-1">
        <div className="rounded-xl border border-border/60 bg-muted/30 px-3 py-3">
          <div className="text-xs text-muted-foreground">Total Diterima</div>
          <div className="mt-1 text-2xl font-semibold tabular-nums md:text-3xl lg:text-4xl">
            {totals.received}
          </div>
        </div>
        <div className="rounded-xl border border-border/60 bg-muted/30 px-3 py-3">
          <div className="text-xs text-muted-foreground">Total Diharapkan</div>
          <div className="mt-1 text-lg font-medium tabular-nums md:text-xl">
            {totals.expected}
          </div>
        </div>
        <div
          className={cn(
            "rounded-xl border px-3 py-3",
            hasDiscrepancy
              ? "border-destructive/30 bg-destructive/5"
              : "border-border/60 bg-muted/30",
          )}
        >
          <div className="text-xs text-muted-foreground">Total Selisih</div>
          <div
            className={cn(
              "mt-1 text-lg font-medium tabular-nums md:text-xl",
              hasDiscrepancy && "text-destructive",
            )}
          >
            {totals.discrepancy > 0 ? "+" : ""}
            {totals.discrepancy}
          </div>
        </div>
      </div>
    </div>
  );
}

export function PenerimaanDetailView({ id }: { id: string }) {
  const { data: inbound, isLoading } = useInboundDetail(id);
  const batchMutation = useSetReceivedQtyBatch(id);

  const [page, setPage] = React.useState(1);
  const [perPage, setPerPage] = React.useState(20);
  const [search, setSearch] = React.useState("");
  const [debouncedSearch, setDebouncedSearch] = React.useState("");
  const [sort, setSort] = React.useState<string | undefined>(undefined);

  const [dirty, setDirty] = React.useState<Record<string, number>>({});
  const [confirmOpen, setConfirmOpen] = React.useState(false);
  const saving = batchMutation.isPending;

  React.useEffect(() => {
    const t = setTimeout(() => {
      setDebouncedSearch(search.trim());
      setPage(1);
    }, 300);
    return () => clearTimeout(t);
  }, [search]);

  const { data: itemsRes, isFetching: isFetchingItems } = useInboundItems(id, {
    page,
    perPage,
    search: debouncedSearch || undefined,
    sort,
  });
  const items: InboundItem[] = itemsRes?.data ?? [];
  const itemsMeta = itemsRes?.meta;

  const handleSort = (next: string | undefined) => {
    setSort(next);
    setPage(1);
  };

  const canEdit = !!inbound && inbound.status !== "CANCELLED";

  const setDirtyFor = React.useCallback((itemId: string, qty: number | null) => {
    setDirty((prev) => {
      const next = { ...prev };
      if (qty === null) {
        delete next[itemId];
      } else {
        next[itemId] = qty;
      }
      return next;
    });
  }, []);

  const dirtyEntries = React.useMemo(
    () => Object.entries(dirty),
    [dirty],
  );
  const hasChanges = dirtyEntries.length > 0;

  const totals = React.useMemo(
    () => computeTotals(inbound?.items ?? [], dirty),
    [inbound?.items, dirty],
  );

  const deltaSum = React.useMemo(() => {
    if (!inbound) return 0;
    const byId = new Map(inbound.items.map((it) => [it.id, it]));
    let d = 0;
    for (const [itemId, qty] of dirtyEntries) {
      const orig = byId.get(itemId)?.received_qty ?? 0;
      d += qty - orig;
    }
    return d;
  }, [dirtyEntries, inbound]);

  React.useEffect(() => {
    if (!hasChanges) return;
    const handler = (e: BeforeUnloadEvent) => {
      e.preventDefault();
      e.returnValue = "";
    };
    window.addEventListener("beforeunload", handler);
    return () => window.removeEventListener("beforeunload", handler);
  }, [hasChanges]);

  const resetDirty = () => setDirty({});

  const handleSaveAll = async () => {
    if (!inbound || dirtyEntries.length === 0) return;
    const payload = dirtyEntries.map(([itemId, qty]) => ({ itemId, qty }));
    const results = await batchMutation.mutateAsync(payload);

    const okIds = new Set(results.filter((r) => r.ok).map((r) => r.itemId));
    const failed = results.filter((r) => !r.ok);

    if (failed.length === 0) {
      toast.success(`Berhasil menyimpan ${okIds.size} item`);
      setDirty({});
      setConfirmOpen(false);
      return;
    }
    if (okIds.size === 0) {
      toast.error(failed[0].error || "Gagal menyimpan perubahan");
      return;
    }
    toast.warning(
      `Berhasil ${okIds.size}, gagal ${failed.length} — item gagal tetap ditandai belum tersimpan`,
    );
    setDirty((prev) => {
      const next = { ...prev };
      for (const id of okIds) delete next[id];
      return next;
    });
    setConfirmOpen(false);
  };

  const diffRows = React.useMemo(() => {
    if (!inbound) return [] as Array<{
      id: string;
      sku: string;
      name: string;
      from: number;
      to: number;
    }>;
    const byId = new Map(inbound.items.map((it) => [it.id, it]));
    return dirtyEntries.map(([itemId, qty]) => {
      const it = byId.get(itemId);
      return {
        id: itemId,
        sku: it?.variant?.sku ?? "",
        name:
          it?.variant?.product?.name ??
          it?.variant?.item_name ??
          it?.variant?.name ??
          "—",
        from: it?.received_qty ?? 0,
        to: qty,
      };
    });
  }, [dirtyEntries, inbound]);

  return (
    <div className="flex flex-col gap-6">
      <PageTitle
        title="Detail Penerimaan"
        description={inbound ? inbound.transaction_number : "Memuat..."}
        backHref="/dashboard/barang-masuk/penerimaan"
        breadcrumb={[
          { label: "Dashboard", href: "/dashboard" },
          { label: "Barang Masuk", href: "/dashboard/barang-masuk/penerimaan" },
          { label: "Detail Penerimaan" },
        ]}
      />

      {isLoading ? (
        <LiquidGlass
          radius={20}
          intensity="subtle"
          className="bg-white/30 p-6 dark:bg-white/[0.04]"
        >
          <div className="flex flex-col gap-4">
            <Skeleton className="h-6 w-48" />
            <Skeleton className="h-40 w-full" />
          </div>
        </LiquidGlass>
      ) : !inbound ? (
        <LiquidGlass
          radius={20}
          intensity="subtle"
          className="bg-white/30 p-6 dark:bg-white/[0.04]"
        >
          <div className="flex flex-col items-center gap-3 py-12 text-muted-foreground">
            <p className="text-sm font-medium">Penerimaan tidak ditemukan</p>
            <Link href="/dashboard/barang-masuk/penerimaan">
              <Button variant="outline" size="sm">
                <ArrowLeftIcon className="mr-1.5 size-4" />
                Kembali
              </Button>
            </Link>
          </div>
        </LiquidGlass>
      ) : (
        <div className="flex flex-col gap-4 print:gap-2">
          <div className="flex items-center justify-end gap-2 print:hidden">
            <Button
              variant="outline"
              size="sm"
              onClick={() =>
                window.open(
                  `/dashboard/document-preview/inbound-receipt/${inbound.id}`,
                  "_blank",
                  "noopener,noreferrer",
                )
              }
            >
              <PrinterIcon className="mr-1.5 size-4" />
              Cetak
            </Button>
            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <Button
                  variant="outline"
                  size="sm"
                  aria-label="Aksi lain"
                  className="px-2"
                >
                  <MoreHorizontalIcon className="size-4" />
                </Button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="end">
                <DropdownMenuItem
                  onSelect={() =>
                    window.open(
                      `/dashboard/document-preview/inbound-barcodes/${inbound.id}`,
                      "_blank",
                      "noopener,noreferrer",
                    )
                  }
                >
                  <QrCodeIcon className="mr-2 size-4" />
                  Cetak Barcode
                </DropdownMenuItem>
                <DropdownMenuItem onSelect={() => handleExportCsv(inbound)}>
                  <DownloadIcon className="mr-2 size-4" />
                  Export CSV
                </DropdownMenuItem>
              </DropdownMenuContent>
            </DropdownMenu>
          </div>

          <div className="grid grid-cols-1 gap-4 lg:grid-cols-3 print:grid-cols-1">
            <LiquidGlass
              radius={20}
              intensity="subtle"
              className="self-start bg-white/30 lg:col-start-3 lg:sticky lg:top-6 dark:bg-white/[0.04] print:col-start-auto print:border print:border-border print:shadow-none"
            >
              <SummaryRail totals={totals} />
            </LiquidGlass>

            <div className="flex min-w-0 flex-col gap-4 lg:col-span-2 lg:col-start-1 lg:row-start-1 print:col-start-auto print:row-start-auto">
              <LiquidGlass
                radius={20}
                intensity="subtle"
                className="bg-white/30 dark:bg-white/[0.04] print:border print:border-border print:shadow-none"
              >
                <div className="px-5 py-4">
                  <h3 className="mb-3 text-sm font-semibold print:text-base">
                    Informasi Penerimaan
                  </h3>
                  <div className="grid grid-cols-1 gap-x-6 gap-y-3 md:grid-cols-2">
                    <InfoField
                      orientation="horizontal"
                      label="No. Penerimaan"
                      value={inbound.transaction_number}
                    />
                    <InfoField
                      orientation="horizontal"
                      label="No. Referensi"
                      value={inbound.reference_number}
                    />
                    <InfoField
                      orientation="horizontal"
                      label="Sumber"
                      value={TYPE_LABEL[inbound.type] ?? inbound.type}
                    />
                    <InfoField
                      orientation="horizontal"
                      label="Status"
                      value={
                        <StatusBadge
                          domain="inbound"
                          status={inbound.status}
                          className="text-2xs"
                        />
                      }
                    />
                    <InfoField
                      orientation="horizontal"
                      label="Lokasi"
                      value={inbound.location?.location_name}
                    />
                    <InfoField
                      orientation="horizontal"
                      label="Tgl. Diharapkan"
                      value={
                        inbound.expected_date
                          ? formatDate(inbound.expected_date)
                          : undefined
                      }
                    />
                    <InfoField
                      orientation="horizontal"
                      label="Dibuat Oleh"
                      value={inbound.created_by}
                    />
                    <InfoField
                      orientation="horizontal"
                      label="Dibuat"
                      value={formatDateTime(inbound.created_at)}
                    />
                  </div>
                </div>
              </LiquidGlass>

              <LiquidGlass
                radius={20}
                intensity="subtle"
                className="bg-white/30 dark:bg-white/[0.04] print:border print:border-border print:shadow-none"
              >
                <div className="px-5 py-4">
                  <div className="mb-3 flex flex-col gap-2 print:hidden">
                    <h3 className="text-sm font-semibold">Daftar Item</h3>
                    <div className="relative w-full">
                      <SearchIcon className="pointer-events-none absolute left-2.5 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" />
                      <Input
                        value={search}
                        onChange={(e) => setSearch(e.target.value)}
                        placeholder="Cari SKU atau nama produk..."
                        className="pl-8"
                      />
                    </div>
                  </div>
                  <h3 className="mb-3 hidden text-sm font-semibold print:block print:text-base">
                    Daftar Item
                  </h3>

                  <Table containerClassName="rounded-xl border border-border/40">
                    <TableHeader>
                      <TableRow className="border-b border-border/60 bg-muted/30">
                        <TableHead className="px-3 py-2.5 text-xs font-medium uppercase tracking-wider text-muted-foreground">
                          <SortableHeader
                            label="Produk"
                            field="sku"
                            currentSort={sort}
                            onSort={handleSort}
                          />
                        </TableHead>
                        <TableHead className="px-3 py-2.5 text-right text-xs font-medium uppercase tracking-wider text-muted-foreground">
                          <SortableHeader
                            label="Qty Diharapkan"
                            field="expected_qty"
                            currentSort={sort}
                            onSort={handleSort}
                            align="right"
                            className="w-full"
                          />
                        </TableHead>
                        <TableHead className="px-3 py-2.5 text-right text-xs font-medium uppercase tracking-wider text-muted-foreground">
                          <SortableHeader
                            label="Qty Diterima"
                            field="received_qty"
                            currentSort={sort}
                            onSort={handleSort}
                            align="right"
                            className="w-full"
                          />
                        </TableHead>
                        <TableHead className="px-3 py-2.5 text-right text-xs font-medium uppercase tracking-wider text-muted-foreground">
                          <SortableHeader
                            label="Qty Putaway"
                            field="putaway_qty"
                            currentSort={sort}
                            onSort={handleSort}
                            align="right"
                            className="w-full"
                          />
                        </TableHead>
                        <TableHead className="px-3 py-2.5 text-right text-xs font-medium uppercase tracking-wider text-muted-foreground">
                          Selisih
                        </TableHead>
                        <TableHead className="px-3 py-2.5 text-xs font-medium uppercase tracking-wider text-muted-foreground">
                          Catatan
                        </TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {items.length === 0 && !isFetchingItems && (
                        <TableRow>
                          <TableCell
                            colSpan={6}
                            className="py-8 text-center text-sm text-muted-foreground"
                          >
                            {debouncedSearch
                              ? `Tidak ada item cocok "${debouncedSearch}".`
                              : "Belum ada item."}
                          </TableCell>
                        </TableRow>
                      )}
                      {items.map((item: InboundItem) => {
                        const variantOptions = item.variant?.options
                          ?.map((o) => o.value)
                          .filter(Boolean)
                          .join(", ");
                        const productName =
                          item.variant?.product?.name ??
                          item.variant?.item_name ??
                          item.variant?.name ??
                          "—";
                        const imageUrl =
                          item.variant?.media?.[0]?.url ??
                          item.variant?.product?.media?.[0]?.url;
                        const isDirty = dirty[item.id] !== undefined;
                        const effectiveQty =
                          dirty[item.id] ?? item.received_qty;
                        const effectiveDiscrepancy =
                          effectiveQty - item.expected_qty;
                        const rejectedQty = item.rejected_qty ?? 0;
                        return (
                          <TableRow
                            key={item.id}
                            className={cn(
                              "border-b border-border/20 last:border-0",
                              isDirty &&
                                "border-l-2 border-l-warning bg-warning/5",
                            )}
                          >
                            <TableCell className="px-3 py-2.5">
                              <div className="flex items-start gap-3">
                                <div className="size-10 shrink-0 overflow-hidden rounded-xl border bg-muted/50">
                                  {imageUrl ? (
                                    <img
                                      src={imageUrl}
                                      alt={productName}
                                      className="h-full w-full object-cover"
                                    />
                                  ) : (
                                    <div className="flex h-full w-full items-center justify-center bg-muted text-muted-foreground">
                                      <ImageIcon className="size-4 opacity-50" />
                                    </div>
                                  )}
                                </div>
                                <div
                                  className="flex min-w-0 flex-col gap-0.5"
                                  style={{ maxWidth: 320 }}
                                >
                                  <span className="font-medium whitespace-normal break-words text-foreground">
                                    {productName}
                                  </span>
                                  {variantOptions && (
                                    <span className="whitespace-normal break-words text-xs text-foreground">
                                      {variantOptions}
                                    </span>
                                  )}
                                  {item.variant?.sku && (
                                    <CopySku sku={item.variant.sku} />
                                  )}
                                  {isDirty && (
                                    <Badge
                                      variant="outline"
                                      className="mt-1 w-fit border-warning/40 text-2xs text-warning"
                                    >
                                      Belum disimpan
                                    </Badge>
                                  )}
                                </div>
                              </div>
                            </TableCell>
                            <TableCell className="px-3 py-2.5 text-right tabular-nums text-foreground">
                              {item.expected_qty}
                            </TableCell>
                            <TableCell className="px-3 py-2.5 text-right tabular-nums text-foreground">
                              <div className="flex flex-col items-end gap-0.5">
                                {canEdit ? (
                                  <EditableReceivedQty
                                    key={`recv-${item.id}-${item.received_qty}-${isDirty ? "d" : "c"}`}
                                    item={item}
                                    value={effectiveQty}
                                    disabled={saving}
                                    onChange={(qty) =>
                                      setDirtyFor(item.id, qty)
                                    }
                                  />
                                ) : (
                                  <span>{item.received_qty}</span>
                                )}
                                {rejectedQty > 0 && (
                                  <span
                                    className="text-2xs text-destructive"
                                    title={item.rejection_note ?? undefined}
                                  >
                                    {rejectedQty} ditolak
                                  </span>
                                )}
                              </div>
                            </TableCell>
                            <TableCell className="px-3 py-2.5 text-right tabular-nums text-foreground">
                              {item.putaway_qty}
                            </TableCell>
                            <TableCell className="px-3 py-2.5 text-right tabular-nums">
                              {effectiveDiscrepancy !== 0 ? (
                                <Badge
                                  variant="outline"
                                  className="border-destructive/30 text-2xs text-destructive"
                                >
                                  {effectiveDiscrepancy > 0 ? "+" : ""}
                                  {effectiveDiscrepancy}
                                </Badge>
                              ) : (
                                <span className="text-foreground">0</span>
                              )}
                            </TableCell>
                            <TableCell className="max-w-[200px] truncate whitespace-normal px-3 py-2.5 text-xs text-foreground">
                              {item.discrepancy_note ?? "—"}
                            </TableCell>
                          </TableRow>
                        );
                      })}
                    </TableBody>
                  </Table>
                  {itemsMeta && (
                    <div className="mt-3 print:hidden">
                      <SimplePagination
                        page={itemsMeta.current_page}
                        lastPage={itemsMeta.last_page}
                        onPageChange={setPage}
                        perPage={perPage}
                        onPerPageChange={setPerPage}
                        isFetching={isFetchingItems}
                        total={itemsMeta.total}
                        label="item"
                      />
                    </div>
                  )}
                </div>
              </LiquidGlass>
            </div>
          </div>

          {canEdit && hasChanges && (
            <FormFooter className="print:hidden">
              <div className="mr-auto flex items-center gap-2 text-xs text-muted-foreground">
                <span className="font-medium text-foreground">
                  {dirtyEntries.length} item diubah
                </span>
                <span>
                  · Δ {deltaSum > 0 ? "+" : ""}
                  {deltaSum} qty
                </span>
              </div>
              <Button
                variant="outline"
                size="sm"
                onClick={resetDirty}
                disabled={saving}
              >
                Batalkan
              </Button>
              <Button
                variant="primary"
                size="sm"
                onClick={() => setConfirmOpen(true)}
                disabled={saving}
              >
                {saving ? (
                  <Loader2Icon className="mr-1.5 size-4 animate-spin" />
                ) : (
                  <SaveIcon className="mr-1.5 size-4" />
                )}
                Simpan Perubahan
              </Button>
            </FormFooter>
          )}

          {inbound.assignments && inbound.assignments.length > 0 && (
            <LiquidGlass
              radius={20}
              intensity="subtle"
              className="bg-white/30 dark:bg-white/[0.04] print:border print:border-border print:shadow-none"
            >
              <div className="px-5 py-4">
                <h3 className="mb-3 text-sm font-semibold print:text-base">
                  Riwayat Assignment
                </h3>
                <Table containerClassName="rounded-lg border border-border/40">
                  <TableHeader>
                    <TableRow className="border-b border-border/60 bg-muted/30">
                      {[
                        "Petugas",
                        "Ditugaskan Oleh",
                        "Status",
                        "Mulai",
                        "Selesai",
                        "Catatan",
                      ].map((h) => (
                        <TableHead
                          key={h}
                          className="px-3 py-2.5 text-xs font-medium uppercase tracking-wider text-muted-foreground"
                        >
                          {h}
                        </TableHead>
                      ))}
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {inbound.assignments.map((a) => (
                      <TableRow
                        key={a.id}
                        className="border-b border-border/20 last:border-0"
                      >
                        <TableCell className="px-3 py-2.5">
                          {a.worker?.name ?? a.assigned_to}
                        </TableCell>
                        <TableCell className="px-3 py-2.5 text-muted-foreground">
                          {a.assigner?.name ?? a.assigned_by}
                        </TableCell>
                        <TableCell className="px-3 py-2.5">
                          <Badge
                            variant="outline"
                            className={cn("text-2xs", {
                              "border-border text-muted-foreground":
                                a.status === "PENDING",
                              "border-warning/30 text-warning":
                                a.status === "IN_PROGRESS",
                              "border-success/30 text-success":
                                a.status === "COMPLETED",
                            })}
                          >
                            {a.status === "PENDING"
                              ? "Menunggu"
                              : a.status === "IN_PROGRESS"
                                ? "Dikerjakan"
                                : "Selesai"}
                          </Badge>
                        </TableCell>
                        <TableCell className="px-3 py-2.5 text-muted-foreground">
                          {a.started_at ? formatDateTime(a.started_at) : "—"}
                        </TableCell>
                        <TableCell className="px-3 py-2.5 text-muted-foreground">
                          {a.completed_at ? formatDateTime(a.completed_at) : "—"}
                        </TableCell>
                        <TableCell className="max-w-[200px] truncate whitespace-normal px-3 py-2.5 text-xs text-muted-foreground">
                          {a.notes ?? ""}
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </div>
            </LiquidGlass>
          )}
        </div>
      )}

      <ConfirmDialog
        open={confirmOpen}
        onOpenChange={setConfirmOpen}
        title="Simpan perubahan qty diterima?"
        description={`${diffRows.length} item akan diperbarui. Perubahan mempengaruhi stok bin inbound.`}
        confirmLabel="Simpan"
        cancelLabel="Batal"
        loading={saving}
        onConfirm={handleSaveAll}
      >
        {diffRows.length > 0 && (
          <div className="max-h-64 overflow-y-auto rounded-xl border border-border/60">
            <Table>
              <TableHeader>
                <TableRow className="bg-muted/30">
                  <TableHead className="px-3 py-2 text-xs font-medium uppercase tracking-wider text-muted-foreground">
                    Produk
                  </TableHead>
                  <TableHead className="px-3 py-2 text-right text-xs font-medium uppercase tracking-wider text-muted-foreground">
                    Sebelum
                  </TableHead>
                  <TableHead className="px-3 py-2 text-right text-xs font-medium uppercase tracking-wider text-muted-foreground">
                    Sesudah
                  </TableHead>
                  <TableHead className="px-3 py-2 text-right text-xs font-medium uppercase tracking-wider text-muted-foreground">
                    Δ
                  </TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {diffRows.map((r) => {
                  const delta = r.to - r.from;
                  return (
                    <TableRow key={r.id} className="border-b border-border/20 last:border-0">
                      <TableCell className="px-3 py-2 text-xs">
                        <div className="flex flex-col">
                          <span className="text-foreground">{r.name}</span>
                          {r.sku && (
                            <span className="text-muted-foreground">{r.sku}</span>
                          )}
                        </div>
                      </TableCell>
                      <TableCell className="px-3 py-2 text-right text-xs tabular-nums text-muted-foreground">
                        {r.from}
                      </TableCell>
                      <TableCell className="px-3 py-2 text-right text-xs tabular-nums text-foreground">
                        {r.to}
                      </TableCell>
                      <TableCell
                        className={cn(
                          "px-3 py-2 text-right text-xs tabular-nums",
                          delta === 0 && "text-muted-foreground",
                          delta > 0 && "text-success",
                          delta < 0 && "text-destructive",
                        )}
                      >
                        {delta > 0 ? "+" : ""}
                        {delta}
                      </TableCell>
                    </TableRow>
                  );
                })}
              </TableBody>
            </Table>
          </div>
        )}
      </ConfirmDialog>
    </div>
  );
}

"use client";

import { useState, useCallback, useMemo, useEffect, useRef } from "react";
import {
  ArrowLeftIcon,
  Loader2Icon,
  ScanLineIcon,
  QrCodeIcon,
  PackageIcon,
  Trash2Icon,
  CheckCircle2Icon,
  ChevronDownIcon,
  ChevronRightIcon,
  AlertTriangleIcon,
} from "lucide-react";
import Image from "next/image";
import Link from "next/link";
import { useRouter } from "next/navigation";


import { QRCodeSVG } from "qrcode.react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Checkbox } from "@/components/ui/checkbox";
import { Progress } from "@/components/ui/progress";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Combobox } from "@/components/ui/combobox";
import { LiquidGlass } from "@/components/ui/liquid-glass";
import { Skeleton } from "@/components/ui/skeleton";
import { PageTitle } from "@/components/dashboard/page-title";
import {
  ScanAutoflowBar,
  type ScanAutoflowLine,
} from "@/components/dashboard/shared/scan-autoflow-bar";
import { QtyConfirmInput } from "@/components/ui/qty-confirm-input";
import {
  usePutawayDetail,
  usePutawayItems,
  useProcessPutawayItem,
  useDeletePutawayPlacement,
  useCompleteDiscrepancy,
  usePutawayBins,
  type BinListItem,
  type CompleteDiscrepancyResult,
} from "@/hooks/barang-masuk/use-putaway-actions";
import type { PutawayItem } from "@/types/barang-masuk/putaway";

interface PutawayProcessViewProps {
  id: string;
}

interface PlacementEntry {
  id: string;
  initialSavedQty: number;
  initialBinCode: string;
  initialBinQty: number;
  maxQty: number;
  /** Set when this row is a committed placement (from API) that can be deleted to correct a mis-scan. */
  committedPlacementId?: string;
}

export function PutawayProcessView({ id }: PutawayProcessViewProps) {
  const router = useRouter();
  const {
    data: putaway,
    isLoading,
    refetch: refetchDetail,
  } = usePutawayDetail(id);
  const { data: items, refetch: refetchItems } = usePutawayItems(id);

  const [activeRack, setActiveRack] = useState<BinListItem | null>(null);

  const [notes, setNotes] = useState("");
  const [scanError, setScanError] = useState("");
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [scannedItemIds, setScannedItemIds] = useState<Set<string>>(new Set());

  const [itemPlacements, setItemPlacements] = useState<
    Record<string, PlacementEntry[]>
  >({});
  const [expandedItems, setExpandedItems] = useState<Set<string>>(new Set());
  const [focusPlacementId, setFocusPlacementId] = useState<string | null>(null);
  const [scanFocusKey, setScanFocusKey] = useState(0);
  const refocusScan = useCallback(() => setScanFocusKey((k) => k + 1), []);

  const locationId = putaway?.location_id ?? "";

  const [prevNotes, setPrevNotes] = useState(putaway?.notes);
  if (putaway?.notes !== prevNotes) {
    setPrevNotes(putaway?.notes);
    if (putaway?.notes != null) setNotes(putaway.notes);
  }

  const isNotStarted = putaway?.status === "NOT_STARTED";
  const isInProgress = putaway?.status === "IN_PROGRESS";
  const isCompleted = putaway?.status === "COMPLETED";
  const canEdit = isNotStarted || isInProgress;

  const allItems = useMemo<PutawayItem[]>(() => items ?? [], [items]);

  const visibleList = useMemo<PutawayItem[]>(
    () =>
      isCompleted
        ? allItems
        : // Item yang sudah tuntas ditempatkan hilang dari daftar kerja;
          allItems.filter(
            (it) =>
              it.qty - it.putaway_qty > 0 &&
              (scannedItemIds.has(it.id) || it.putaway_qty > 0),
          ),
    [allItems, scannedItemIds, isCompleted],
  );

  const { totalQty, placedQty } = useMemo(() => {
    return allItems.reduce(
      (acc, it) => {
        acc.totalQty += it.qty;
        acc.placedQty += it.putaway_qty;
        return acc;
      },
      { totalQty: 0, placedQty: 0 },
    );
  }, [allItems]);
  const progressPct =
    totalQty > 0 ? Math.round((placedQty / totalQty) * 100) : 0;

  const incompleteItems = useMemo(
    () => allItems.filter((it) => it.qty - it.putaway_qty > 0),
    [allItems],
  );

  const completeDiscrepancyMutation = useCompleteDiscrepancy();
  const [confirmDiscrepancyOpen, setConfirmDiscrepancyOpen] = useState(false);
  const [discrepancyResult, setDiscrepancyResult] =
    useState<CompleteDiscrepancyResult | null>(null);

  const handleCompleteDiscrepancy = useCallback(() => {
    completeDiscrepancyMutation.mutate(id, {
      onSuccess: (res) => {
        setConfirmDiscrepancyOpen(false);
        if (res) setDiscrepancyResult(res);
        refetchItems();
        refetchDetail();
      },
    });
  }, [completeDiscrepancyMutation, id, refetchItems, refetchDetail]);

  const goToStockAdjustment = useCallback(() => {
    if (!discrepancyResult) return;
    const items = discrepancyResult.discrepancy_items
      .map((d) => {
        const src = allItems.find((it) => it.id === d.putaway_item_id);
        const sku = src?.variant?.sku ?? src?.product?.sku;
        return sku ? { sku, qty: d.qty, binId: d.bin_id } : null;
      })
      .filter((v): v is { sku: string; qty: number; binId: string } => !!v);

    const qs = new URLSearchParams({
      location_id: locationId,
      items: JSON.stringify(items),
    });
    setDiscrepancyResult(null);
    router.push(`/dashboard/transaksi-stok/penyesuaian/buat?${qs.toString()}`);
  }, [discrepancyResult, allItems, locationId, router]);

  const { data: availableBins = [] } = usePutawayBins(locationId);

  const binOptions = useMemo(
    () =>
      availableBins.map((b) => ({
        value: b.id,
        label: b.bin_final_code,
      })),
    [availableBins],
  );

  const handleSelectRack = useCallback(
    (binId: string | null) => {
      const bin = binId
        ? (availableBins.find((b) => b.id === binId) ?? null)
        : null;
      setActiveRack(bin);
      if (bin) refocusScan();
    },
    [availableBins, refocusScan],
  );

  const addPlacementForItem = useCallback((match: PutawayItem) => {
    setScanError("");
    setScannedItemIds((prev) => new Set(prev).add(match.id));

    const newId = `${match.id}-p-${Date.now()}`;
    const newEntry: PlacementEntry = {
      id: newId,
      initialSavedQty: 0,
      initialBinCode: "",
      initialBinQty: 0,
      maxQty: match.qty - match.putaway_qty,
    };

    setItemPlacements((prev) => {
      const existing = prev[match.id];
      if (existing) {
        return { ...prev, [match.id]: [...existing, newEntry] };
      }
      const entries: PlacementEntry[] = [];
      const apiPlacements = match.placements ?? [];
      if (apiPlacements.length > 0) {
        for (const p of apiPlacements) {
          entries.push({
            id: `${match.id}-existing-${p.bin_id}`,
            initialSavedQty: p.qty,
            initialBinCode: p.bin?.bin_final_code ?? "",
            initialBinQty: p.qty,
            maxQty: match.qty,
          });
        }
      } else if (match.putaway_qty > 0 && match.destination_bin) {
        entries.push({
          id: `${match.id}-existing`,
          initialSavedQty: match.putaway_qty,
          initialBinCode: match.destination_bin.bin_final_code,
          initialBinQty: match.putaway_qty,
          maxQty: match.qty,
        });
      }
      entries.push(newEntry);
      return { ...prev, [match.id]: entries };
    });

    setExpandedItems((prev) => new Set(prev).add(match.id));
    setFocusPlacementId(newId);
  }, []);

  const scanLines = useMemo<ScanAutoflowLine[]>(
    () =>
      allItems
        .filter((it) => isCompleted || it.qty - it.putaway_qty > 0)
        .map((it) => {
        const sku = it.variant?.sku ?? it.product?.sku ?? "—";
        const opts =
          it.product?.options?.map((o) => o.value).join(" / ") ??
          it.variant?.variation_values?.map((v) => v.value).join(" / ");
        return {
          id: it.id,
          primary:
            it.product?.product?.name ?? (opts ? `${sku} — ${opts}` : sku),
          secondary: opts ? `${sku} · ${opts}` : sku,
          imageUrl: it.product?.media?.[0]?.url,
          codes: [
            it.variant?.sku,
            it.product?.sku,
            it.serial_no,
            it.batch_no,
          ].filter(Boolean) as string[],
          done: it.qty - it.putaway_qty <= 0,
        };
      }),
    [allItems, isCompleted],
  );

  const handleResolve = useCallback(
    (line: ScanAutoflowLine) => {
      const match = allItems.find((it) => it.id === line.id);
      if (!match) return;
      if (match.qty - match.putaway_qty <= 0) {
        setScanError("Item ini sudah selesai ditempatkan.");
        return;
      }
      addPlacementForItem(match);
    },
    [allItems, addPlacementForItem],
  );

  const [completedDialogDismissed, setCompletedDialogDismissed] =
    useState(false);
  const completedDialogOpen =
    isCompleted && !completedDialogDismissed && !discrepancyResult;

  const onProcessed = useCallback(() => {
    refetchItems();
    refetchDetail();
    setTimeout(() => refetchDetail(), 1500);
  }, [refetchItems, refetchDetail]);

  const handleScanSaved = useCallback(() => {
    refocusScan();
  }, [refocusScan]);

  const toggleExpand = useCallback((itemId: string) => {
    setExpandedItems((prev) => {
      const next = new Set(prev);
      if (next.has(itemId)) next.delete(itemId);
      else next.add(itemId);
      return next;
    });
  }, []);

  const removePlacement = useCallback((itemId: string, placementId: string) => {
    setItemPlacements((prev) => {
      const list = prev[itemId]?.filter((p) => p.id !== placementId);
      if (!list || list.length === 0) {
        const { [itemId]: _, ...rest } = prev;
        return rest;
      }
      return { ...prev, [itemId]: list };
    });
  }, []);

  const allSelectable = useMemo(
    () => visibleList.map((it) => it.id),
    [visibleList],
  );
  const allChecked =
    allSelectable.length > 0 && allSelectable.every((i) => selectedIds.has(i));
  const someChecked = allSelectable.some((i) => selectedIds.has(i));

  const toggleAll = useCallback(() => {
    setSelectedIds(allChecked ? new Set() : new Set(allSelectable));
  }, [allChecked, allSelectable]);

  const toggleOne = useCallback((itemId: string) => {
    setSelectedIds((prev) => {
      const next = new Set(prev);
      if (next.has(itemId)) next.delete(itemId);
      else next.add(itemId);
      return next;
    });
  }, []);

  const statusLabel = isNotStarted
    ? "Belum Mulai"
    : isInProgress
      ? "Sedang Diproses"
      : isCompleted
        ? "Selesai"
        : (putaway?.status ?? "");

  return (
    <div className="flex flex-col gap-6">
      <PageTitle
        title={
          putaway ? `Penempatan - ${putaway.putaway_no}` : "Penempatan Barang"
        }
        backHref="/dashboard/barang-masuk/penempatan"
        breadcrumb={[
          { label: "Gudang", href: "/dashboard" },
          { label: "Barang Masuk", href: "/dashboard/barang-masuk" },
          {
            label: "Penempatan Barang",
            href: "/dashboard/barang-masuk/penempatan",
          },
          ...(statusLabel ? [{ label: statusLabel }] : []),
          {
            label: putaway ? `Penempatan - ${putaway.putaway_no}` : "Memuat...",
          },
        ]}
      />

      {isLoading ? (
        <LiquidGlass
          radius={20}
          intensity="subtle"
          className="bg-white/30 p-6 dark:bg-white/[0.04]"
        >
          <div className="flex flex-col gap-4">
            <Skeleton className="h-6 w-48" />
            <Skeleton className="h-10 w-full" />
            <Skeleton className="h-40 w-full" />
          </div>
        </LiquidGlass>
      ) : !putaway ? (
        <LiquidGlass
          radius={20}
          intensity="subtle"
          className="bg-white/30 p-6 dark:bg-white/[0.04]"
        >
          <div className="flex flex-col items-center gap-3 py-12 text-muted-foreground">
            <p className="text-sm font-medium">Putaway tidak ditemukan</p>
            <Link href="/dashboard/barang-masuk/penempatan">
              <Button variant="outline" size="sm">
                <ArrowLeftIcon className="mr-1.5 size-4" />
                Kembali
              </Button>
            </Link>
          </div>
        </LiquidGlass>
      ) : (
        <div className="flex flex-col gap-4 lg:flex-row lg:items-start">
          {}
          <aside className="flex w-full flex-col gap-5 lg:sticky lg:top-4 lg:w-64 lg:shrink-0">
            <div>
              <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
                Kode Rak
              </p>
              <p className="mt-1.5 text-lg font-bold text-foreground">
                {activeRack ? activeRack.bin_final_code : "Belum dipilih"}
              </p>
            </div>

            <div className="rounded-lg border border-border bg-card p-4">
              <div className="flex items-center gap-2">
                <ScanLineIcon className="size-4 text-muted-foreground" />
                <div className="text-sm font-medium">Pilih Rak</div>
              </div>
              <p className="mt-1 text-xs text-muted-foreground">
                Pilih rak tujuan penempatan berikutnya.
              </p>
              <div className="mt-3 flex items-center justify-center rounded-xl border border-dashed border-border bg-muted/30 p-3">
                {activeRack ? (
                  <QRCodeSVG value={activeRack.bin_final_code} size={72} />
                ) : (
                  <QrCodeIcon
                    className="h-8 w-8 text-muted-foreground/60"
                    strokeWidth={1.2}
                  />
                )}
              </div>
              <Combobox
                options={binOptions}
                value={activeRack?.id ?? null}
                onChange={handleSelectRack}
                placeholder="Pilih rak…"
                searchPlaceholder="Cari kode rak…"
                emptyText="Tidak ada rak tersedia."
                disabled={!canEdit}
                className="mt-3 rounded-xl"
              />
            </div>

            <div>
              <Label
                htmlFor="putaway-notes"
                className="text-xs font-semibold uppercase tracking-wider text-muted-foreground"
              >
                Keterangan
              </Label>
              <Textarea
                id="putaway-notes"
                placeholder="Masukkan keterangan"
                value={notes}
                onChange={(e) => setNotes(e.target.value)}
                disabled={isCompleted}
                className="mt-1.5 min-h-28 rounded-lg text-sm"
              />
            </div>
          </aside>

          {}
          <div className="flex min-w-0 flex-1 flex-col gap-4">
            <LiquidGlass
              radius={20}
              intensity="subtle"
              className="bg-white/30 dark:bg-white/[0.04]"
            >
              <div className="flex flex-col gap-4 px-5 py-4">
                <div className="flex flex-col gap-4 lg:flex-row lg:items-start">
                  <ScanAutoflowBar
                    lines={scanLines}
                    onResolve={handleResolve}
                    interceptCode={(code) => {
                      const n = code.trim().toLowerCase().replace(/\s+/g, "");
                      const rack = availableBins.find(
                        (b) =>
                          b.bin_final_code
                            .trim()
                            .toLowerCase()
                            .replace(/\s+/g, "") === n,
                      );
                      if (rack) {
                        handleSelectRack(rack.id);
                        return true;
                      }
                      return false;
                    }}
                    disabled={!canEdit}
                    refocusKey={scanFocusKey}
                    hint="Scan rak tujuan → scan SKU/serial/batch → isi qty (keyboard hanya qty)."
                    className="flex-1"
                  />
                  <div className="flex min-w-44 flex-col gap-1.5 lg:w-56">
                    <span className="text-sm font-semibold tabular-nums">
                      {placedQty} / {totalQty} Qty
                    </span>
                    <Progress
                      value={progressPct}
                      className={cn(
                        "h-2.5",
                        progressPct >= 100 &&
                          "[&_[data-slot=progress-indicator]]:bg-success",
                      )}
                    />
                  </div>
                </div>
                {scanError && (
                  <p className="-mt-1 text-xs text-destructive">{scanError}</p>
                )}
                {isInProgress && incompleteItems.length > 0 && (
                  <div className="flex items-center justify-between gap-3 rounded-xl border border-warning/30 bg-warning/10 px-3.5 py-2.5">
                    <div className="flex items-start gap-2">
                      <AlertTriangleIcon className="mt-0.5 size-4 shrink-0 text-warning" />
                      <p className="text-xs text-foreground">
                        {incompleteItems.length} item masih ada selisih (fisik
                        kurang dari data). Kalau memang tidak ada fisiknya
                        lagi, selesaikan dengan selisih.
                      </p>
                    </div>
                    <Button
                      type="button"
                      variant="outline"
                      size="sm"
                      onClick={() => setConfirmDiscrepancyOpen(true)}
                      className="shrink-0"
                    >
                      Selesaikan Selisih
                    </Button>
                  </div>
                )}
              </div>
            </LiquidGlass>

            <LiquidGlass
              radius={20}
              intensity="subtle"
              className="bg-white/30 dark:bg-white/[0.04]"
            >
              <Table>
                <TableHeader>
                  <TableRow className="hover:bg-transparent">
                    <TableHead className="w-10 pl-5">
                      <Checkbox
                        checked={
                          allChecked
                            ? true
                            : someChecked
                              ? "indeterminate"
                              : false
                        }
                        onCheckedChange={toggleAll}
                        disabled={!canEdit || allSelectable.length === 0}
                        aria-label="Pilih semua"
                      />
                    </TableHead>
                    <TableHead className="text-xs font-medium uppercase tracking-wider text-muted-foreground">
                      Produk
                    </TableHead>
                    <TableHead className="text-xs font-medium uppercase tracking-wider text-muted-foreground">
                      Sumber
                    </TableHead>
                    <TableHead className="text-xs font-medium uppercase tracking-wider text-muted-foreground">
                      Qty
                    </TableHead>
                    <TableHead className="w-12 pr-5" />
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {visibleList.length === 0 ? (
                    <TableRow className="hover:bg-transparent">
                      <TableCell colSpan={5} className="py-16 text-center">
                        <p className="text-sm text-muted-foreground">
                          Scan kode rak terlebih dahulu, lalu scan SKU produk.
                        </p>
                      </TableCell>
                    </TableRow>
                  ) : (
                    visibleList.map((item) => (
                      <PutawayItemRow
                        key={item.id}
                        item={item}
                        putawayId={id}
                        locationId={locationId}
                        editable={canEdit}
                        correctable={isInProgress || isCompleted}
                        defaultRack={activeRack}
                        binOptions={binOptions}
                        availableBins={availableBins}
                        selected={selectedIds.has(item.id)}
                        onToggleSelect={() => toggleOne(item.id)}
                        onProcessed={onProcessed}
                        sourceRef={
                          putaway?.inbound?.reference_number ??
                          putaway?.inbound?.transaction_number ??
                          "—"
                        }
                        placements={itemPlacements[item.id] ?? []}
                        expanded={expandedItems.has(item.id)}
                        onToggleExpand={() => toggleExpand(item.id)}
                        focusPlacementId={focusPlacementId}
                        onRemovePlacement={(pid) =>
                          removePlacement(item.id, pid)
                        }
                        onSaved={handleScanSaved}
                      />
                    ))
                  )}
                </TableBody>
              </Table>
            </LiquidGlass>
          </div>
        </div>
      )}

      <Dialog
        open={confirmDiscrepancyOpen}
        onOpenChange={setConfirmDiscrepancyOpen}
      >
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle>Selesaikan dengan Selisih?</DialogTitle>
            <DialogDescription>
              {incompleteItems.length} item masih memiliki sisa qty yang
              belum ditempatkan (fisik tidak mencukupi). Sisa akan
              dialokasikan ke rak default lokasi ini, lalu dokumen ditutup.
              Setelah ini kamu perlu membuat Penyesuaian Stok minus agar
              catatan stok akurat. Lanjutkan?
            </DialogDescription>
          </DialogHeader>
          <DialogFooter className="gap-2 sm:gap-0">
            <Button
              variant="ghost"
              onClick={() => setConfirmDiscrepancyOpen(false)}
              disabled={completeDiscrepancyMutation.isPending}
            >
              Batal
            </Button>
            <Button
              onClick={handleCompleteDiscrepancy}
              disabled={completeDiscrepancyMutation.isPending}
            >
              {completeDiscrepancyMutation.isPending && (
                <Loader2Icon className="mr-2 size-4 animate-spin" />
              )}
              Ya, Selesaikan
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <Dialog
        open={!!discrepancyResult}
        onOpenChange={(open) => {
          if (!open) setDiscrepancyResult(null);
        }}
      >
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle>Penempatan Diselesaikan dengan Selisih</DialogTitle>
            <DialogDescription>
              {discrepancyResult?.discrepancy_items.length ?? 0} item
              dialokasikan ke rak default. Buat Penyesuaian Stok sekarang
              agar stok tidak tercatat berlebih.
            </DialogDescription>
          </DialogHeader>
          {discrepancyResult && discrepancyResult.discrepancy_items.length > 0 && (
            <div className="flex max-h-56 flex-col gap-1.5 overflow-y-auto rounded-lg border border-border bg-muted/20 p-3">
              {discrepancyResult.discrepancy_items.map((d) => {
                const src = allItems.find(
                  (it) => it.id === d.putaway_item_id,
                );
                const name =
                  src?.product?.product?.name ?? src?.variant?.item_name ?? "—";
                const sku = src?.variant?.sku ?? src?.product?.sku ?? "—";
                return (
                  <div
                    key={d.putaway_item_id}
                    className="flex items-center justify-between gap-2 text-xs"
                  >
                    <span className="truncate text-foreground" title={name}>
                      {name}{" "}
                      <span className="font-mono text-muted-foreground">
                        ({sku})
                      </span>
                    </span>
                    <span className="shrink-0 font-mono font-semibold tabular-nums">
                      {d.qty} qty
                    </span>
                  </div>
                );
              })}
            </div>
          )}
          <DialogFooter className="gap-2 sm:gap-0">
            <Button variant="ghost" onClick={() => setDiscrepancyResult(null)}>
              Nanti Saja
            </Button>
            <Button onClick={goToStockAdjustment}>
              Buat Penyesuaian Stok
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <Dialog
        open={completedDialogOpen}
        onOpenChange={(open) => {
          if (!open) setCompletedDialogDismissed(true);
        }}
      >
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle>Penempatan Selesai</DialogTitle>
            <DialogDescription>
              Semua item pada {putaway?.putaway_no ?? "penempatan"} sudah
              ditempatkan. Kembali ke daftar penempatan?
            </DialogDescription>
          </DialogHeader>
          <DialogFooter className="gap-2 sm:gap-0">
            <Button
              variant="ghost"
              onClick={() => setCompletedDialogDismissed(true)}
            >
              Tetap di Halaman
            </Button>
            <Button
              onClick={() =>
                router.push("/dashboard/barang-masuk/penempatan")
              }
            >
              Kembali ke Daftar
            </Button>
