      <ConfirmDialog
        open={!!deleteTarget}
        onOpenChange={(v) => !v && setDeleteTarget(null)}
        title={`Hapus ${label}`}
        description={`Apakah Anda yakin ingin menghapus ${label.toLowerCase()} "${deleteTarget?.name}"?`}
        onConfirm={handleDelete}
        loading={deleteMut.isPending}
        variant="destructive"
      />
    </>
  );
