function ChannelMappingCell({
  channelCode,
  channelName,
  attributeId,
  categoryId,
  mapped,
  type,
}: {
  channelCode: string;
  channelName: string;
  attributeId: number;
  categoryId: number;
  mapped: boolean;
  type: "spec" | "sales";
}) {
