      <ScrollArea className="flex-1">
        {nodes.length === 0 ? (
          <p className="px-3 py-6 text-center text-xs text-muted-foreground">
            —
          </p>
        ) : (
          <ul className="flex flex-col gap-0.5 p-1.5 pt-0">
            {nodes.map((n) => (
              <li key={n.id}>
                <div
                  className={cn(
                    "flex items-center justify-between gap-2 rounded-xl px-3 py-2 text-sm",
                    n.id === activeId
                      ? "bg-primary/10 font-medium text-primary"
                      : "text-muted-foreground",
                  )}
                >
                  <span className="truncate">{n.name}</span>
                  {n.children?.length ? (
                    <ChevronRightIcon className="size-4 shrink-0 opacity-50" />
                  ) : null}
                </div>
              </li>
            ))}
          </ul>
        )}
      </ScrollArea>
    </div>
  );
}

interface EditKategoriDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  categoryId: number | null;
  currentName: string;
  fullPath: string;
}

export function EditKategoriDialog({
  open,
  onOpenChange,
  categoryId,
  currentName,
  fullPath,
}: EditKategoriDialogProps) {
  const [name, setName] = React.useState(currentName);
  const updateMut = useUpdateKategori();
  const { data: tree } = useEnabledCategories();

  const [prevOpen, setPrevOpen] = React.useState(open);
  const [prevCurrentName, setPrevCurrentName] = React.useState(currentName);
  if (open !== prevOpen || currentName !== prevCurrentName) {
    setPrevOpen(open);
    setPrevCurrentName(currentName);
    if (open) setName(currentName);
  }

  const pathIds = React.useMemo(() => {
    if (!tree || !categoryId) return [];
    return buildPathIds(tree, categoryId);
  }, [tree, categoryId]);

  const resolved = React.useMemo(() => {
    if (!tree) return [];
    return pathIds
      .map((id) => findNode(tree, id))
      .filter((n): n is KategoriItem => n !== undefined);
  }, [tree, pathIds]);

  const columns: KategoriItem[][] = [
    tree ?? [],
    resolved[0]?.children ?? [],
    resolved[1]?.children ?? [],
  ];

  const parentSegments = resolved.slice(0, -1);
  const parentLabel = parentSegments.map((p) => p.name).join(" / ");

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const trimmed = name.trim();
    if (!trimmed || !categoryId) return;
    if (trimmed === currentName) {
      onOpenChange(false);
      return;
    }
    updateMut.mutate(
      { id: categoryId, name: trimmed },
      { onSuccess: () => onOpenChange(false) },
    );
  };

  return (
    <Dialog
      open={open}
      onOpenChange={updateMut.isPending ? undefined : onOpenChange}
    >
      <DialogContent
        showCloseButton={false}
        className="border-0 bg-transparent p-0 shadow-none ring-0 sm:max-w-2xl"
      >
        <LiquidGlass
          radius={28}
          intensity="strong"
          className="bg-white/85 dark:bg-neutral-900/85"
        >
          {}
          <div className="flex items-center justify-between border-b border-border/60 px-5 py-4 sm:px-6">
            <div>
              <DialogTitle className="text-lg">Edit Kategori</DialogTitle>
              <DialogDescription className="text-sm text-muted-foreground">
                Ubah nama kategori.
              </DialogDescription>
            </div>
            <DialogClose asChild>
              <Button variant="ghost" size="icon-sm" aria-label="Tutup">
                <XIcon className="size-4" />
              </Button>
            </DialogClose>
          </div>

          <form onSubmit={handleSubmit}>
            <div className="space-y-4 px-5 py-4 sm:px-6">
              {}
              <div className="space-y-2">
                <Label>Lokasi</Label>
                <div className="grid grid-cols-1 divide-y divide-border/60 overflow-hidden rounded-2xl border border-border/60 lg:grid-cols-3 lg:divide-x lg:divide-y-0">
                  <ReadOnlyColumn
                    label="Level 1"
                    nodes={columns[0]}
                    activeId={pathIds[0]}
                  />
                  <ReadOnlyColumn
                    label="Level 2"
                    nodes={columns[1]}
                    activeId={pathIds[1]}
                  />
                  <ReadOnlyColumn
                    label="Level 3"
                    nodes={columns[2]}
                    activeId={pathIds[2]}
                  />
                </div>
              </div>

              {}
              <div className="space-y-2">
                <Label htmlFor="edit-kategori-name">Nama Kategori</Label>
                <div className="flex items-center gap-0 rounded-xl border border-border/60 bg-background/50 focus-within:ring-2 focus-within:ring-primary/30">
                  {parentLabel && (
                    <span className="shrink-0 pl-3 text-sm text-primary">
                      {parentLabel}
                      {" / "}
                    </span>
                  )}
                  <Input id="edit-kategori-name" type="text" value={name} onChange={(e) => setName(e.target.value)} placeholder="Nama kategori" autoFocus className="min-w-0 flex-1 border-0 bg-transparent px-3 py-2.5 text-sm outline-none shadow-none focus-visible:ring-0 placeholder:text-muted-foreground" />
                </div>
              </div>
            </div>

            {}
            <div className="flex items-center justify-end gap-3 border-t border-border/60 px-5 py-4 sm:px-6">
              <Button
                type="button"
                variant="outline"
                onClick={() => onOpenChange(false)}
                disabled={updateMut.isPending}
              >
                Batal
              </Button>
              <Button
                type="submit"
                variant="primary"
                disabled={!name.trim() || updateMut.isPending}
              >
                {updateMut.isPending && (
                  <Loader2Icon className="animate-spin" />
                )}
                Simpan
              </Button>
            </div>
          </form>
        </LiquidGlass>
      </DialogContent>
    </Dialog>
  );
}

"use client";
import { EmptyState } from "@/components/ui/empty-state";

import { useState, useMemo, useCallback } from "react";
import Link from "next/link";
import { PlusIcon,
  PencilIcon,
  Trash2Icon,
  LockIcon,
  UsersIcon,
  DownloadIcon,
  ArrowLeftRightIcon, Loader2Icon } from "lucide-react";

import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Button } from "@/components/ui/button";
import { Combobox } from "@/components/ui/combobox";
import { LiquidGlass } from "@/components/ui/liquid-glass";
import type { ColumnDef } from "@tanstack/react-table";
import { DataTable } from "@/components/ui/data-table/data-table";
import { ConfirmDialog } from "@/components/ui/confirm-dialog";
import { FilterToolbar } from "@/components/dashboard/master-produk/filter-toolbar";
import { useListState } from "@/hooks/use-list-state";
import { useUrlTab } from "@/hooks/use-url-tab";
import {
  useContacts,
  useContactCategories,
  useDeleteContact,
} from "@/hooks/kontak-pemasok/use-contacts";
import { exportCsv } from "@/lib/export-csv";
import type {
  ContactItem,
  ContactListParams,
} from "@/types/kontak-pemasok/contact";

type TypeFilter = "CUSTOMER" | "BOTH";

const TYPE_TABS: { key: TypeFilter; label: string; icon: typeof UsersIcon }[] =
  [
    { key: "CUSTOMER", label: "Pelanggan", icon: UsersIcon },
    { key: "BOTH", label: "Pemasok dan Pelanggan", icon: ArrowLeftRightIcon },
  ];

const TYPE_VALUES: readonly TypeFilter[] = ["CUSTOMER", "BOTH"];

interface FilterState {
  category_id: string;
  status: string;
}

const EMPTY_FILTERS: FilterState = { category_id: "", status: "" };

export function PelangganTab() {
  const list = useListState<FilterState>(EMPTY_FILTERS, {
    perPage: 20,
    debounceMs: 300,
    namespace: "pelanggan",
  });
  const {
    search,
    setSearch,
    debouncedSearch,
    page,
    perPage,
    filters,
    setFilters,
    resetPage,
    pagination,
    onPaginationChange,
  } = list;
  const [typeFilter, setTypeFilter] = useUrlTab<TypeFilter>(
    "pelanggan_type",
    "CUSTOMER",
    { validValues: TYPE_VALUES },
  );
  const [deleteTarget, setDeleteTarget] = useState<ContactItem | null>(null);

  const handleTypeFilter = useCallback(
    (t: TypeFilter) => {
      setTypeFilter(t);
      resetPage();
    },
    [setTypeFilter, resetPage],
  );

  const params = useMemo<ContactListParams>(
    () => ({
      search: debouncedSearch || undefined,
      page,
      per_page: perPage,
      "filter[type]": typeFilter,
      "filter[category_id]": filters.category_id || undefined,
      "filter[status]": filters.status || undefined,
    }),
    [debouncedSearch, page, perPage, typeFilter, filters],
  );

  const { data, isLoading, isFetching } = useContacts(params);
  const { data: categories = [] } = useContactCategories();
  const deleteMut = useDeleteContact();

  const items = data?.items ?? [];
  const meta = data?.meta ?? {
    current_page: 1,
    last_page: 1,
    per_page: perPage,
    total: 0,
  };

  const columns = useMemo<ColumnDef<ContactItem>[]>(
    () => [
      {
        accessorKey: "code",
        header: "Kode",
        cell: ({ row }) => (
          <span className="font-mono text-xs text-muted-foreground">
            {row.original.code}
          </span>
        ),
      },
      {
        accessorKey: "name",
        header: "Nama",
        cell: ({ row }) => (
          <span className="font-medium">
            <Link
              href={`/dashboard/kontak-pelanggan/${row.original.id}`}
              className="inline-flex items-center gap-1.5 hover:text-primary hover:underline"
            >
              {row.original.is_system && (
                <LockIcon className="size-3 text-warning" />
              )}
              {row.original.name}
            </Link>
          </span>
        ),
      },
      {
        id: "category",
        header: "Kategori",
        cell: ({ row }) => {
          const cat = row.original.category;
          return (
            <span className="text-foreground">
              {cat ? (cat.code ? `${cat.code} - ${cat.name}` : cat.name) : "—"}
            </span>
          );
        },
      },
      {
        id: "phone",
        header: "Telepon",
        cell: ({ row }) => (
          <span className="text-foreground">
            {row.original.phone || row.original.mobile || "—"}
          </span>
        ),
      },
      {
        accessorKey: "email",
        header: "Email",
        cell: ({ row }) => (
          <span className="text-foreground">{row.original.email || "—"}</span>
        ),
      },
      {
        id: "actions",
        header: () => <div className="text-right">Aksi</div>,
        cell: ({ row }) => {
          const item = row.original;
          return (
            <div
              className="flex items-center justify-end gap-1"
              onClick={(e) => e.stopPropagation()}
            >
              <Button variant="ghost" size="icon-sm" asChild>
                <Link
                  href={`/dashboard/kontak-pelanggan/${item.id}/edit`}
                  aria-label="Edit"
                >
                  <PencilIcon className="size-3.5" />
                </Link>
              </Button>
              {!item.is_system && (
                <Button
                  variant="ghost"
                  size="icon-sm"
                  onClick={() => setDeleteTarget(item)}
                  aria-label="Hapus"
                  className="text-destructive hover:text-destructive"
                >
                  <Trash2Icon className="size-3.5" />
                </Button>
              )}
            </div>
          );
        },
      },
    ],
    [],
  );

  const categoryOptions = useMemo(
    () => [
      { value: "", label: "Semua Kategori" },
      ...categories
        .filter((c) => !c.type || c.type === "CUSTOMER" || c.type === "BOTH")
        .map((c) => ({
          value: c.id,
          label: c.code ? `${c.code} - ${c.name}` : c.name,
        })),
    ],
    [categories],
  );

  const statusOptions = [
    { value: "", label: "Semua Status" },
    { value: "active", label: "Aktif" },
    { value: "inactive", label: "Nonaktif" },
  ];

  const hasActiveFilter = Object.values(filters).some(Boolean);
  const activeCount = [filters.category_id, filters.status].filter(
    Boolean,
  ).length;

  function handleDelete() {
    if (!deleteTarget) return;
    deleteMut.mutate(deleteTarget.id, {
      onSuccess: () => setDeleteTarget(null),
    });
  }

  const filterTabs = (
    <Tabs
      value={typeFilter || ""}
      onValueChange={(val) => handleTypeFilter(val as TypeFilter)}
    >
      <TabsList variant="line" className="h-auto">
        {TYPE_TABS.map(({ key, label, icon: Icon }) => (
          <TabsTrigger key={key} value={key}>
            <Icon />
            {label}
          </TabsTrigger>
        ))}
      </TabsList>
    </Tabs>
  );

  const handleExport = useCallback(() => {
    if (items.length === 0) return;
    exportCsv(
      "kontak-pelanggan.csv",
      [
        "Kode",
        "Nama",
        "Kategori",
        "Telepon",
        "Email",
        "Kota",
        "Provinsi",
        "Status",
      ],
      items.map((item: ContactItem) => [
        item.code,
        item.name,
        item.category?.name ?? "",
        item.phone ?? item.mobile ?? "",
        item.email ?? "",
        item.city ?? "",
        item.province ?? "",
        item.status,
      ]),
    );
  }, [items]);

  return (
    <div className="flex flex-col gap-4">
      <LiquidGlass
        radius={20}
        intensity="subtle"
        className="bg-white/30 dark:bg-white/[0.04]"
      >
        <div className="flex flex-wrap items-center justify-between gap-2 px-5 pt-4">
          {filterTabs}
        </div>

        <FilterToolbar
          search={search}
          onSearchChange={setSearch}
          searchPlaceholder="Cari nama, perusahaan, email..."
          align="end"
          onReset={
            hasActiveFilter
              ? () => setFilters(EMPTY_FILTERS)
              : undefined
          }
          hasFilter={hasActiveFilter}
          activeCount={activeCount}
          gridCols={2}
          leading={
            <Button
              variant="outline"
              size="sm"
              className="h-9 rounded-full"
              onClick={handleExport}
              disabled={items.length === 0}
            >
              <DownloadIcon className="mr-1.5 size-4" />
              Export CSV
            </Button>
          }
          trailing={
            <Button variant="primary" asChild>
              <Link href="/dashboard/kontak-pelanggan/tambah">
                <PlusIcon className="size-4" />
                Buat Pelanggan
              </Link>
            </Button>
          }
        >
          <Combobox
            options={categoryOptions}
            value={filters.category_id}
            onChange={(v) =>
              setFilters({ ...filters, category_id: v ?? "" })
            }
            placeholder="Kategori"
            searchPlaceholder="Cari kategori"
            className="h-9 bg-background"
          />
          <Combobox
            options={statusOptions}
            value={filters.status}
            onChange={(v) =>
              setFilters({ ...filters, status: v ?? "" })
            }
            placeholder="Status"
            searchPlaceholder="Cari status"
            className="h-9 bg-background"
          />
        </FilterToolbar>

        {isFetching && !isLoading && (
          <div className="flex justify-center py-1">
            <Loader2Icon className="size-4 animate-spin text-primary" />
          </div>
        )}

        <div className="px-5 py-5 sm:px-6">
          <DataTable
            columns={columns}
            data={items}
            isLoading={isLoading}
            hideToolbar
            manualPagination
            pagination={pagination}
            rowCount={meta.total}
            onPaginationChange={onPaginationChange}
            tableContainerClassName="border-0 bg-transparent backdrop-blur-none [&_[data-slot=table-header]]:bg-transparent"
            emptyState={
              <EmptyState icon={UsersIcon} title="Belum ada kontak pelanggan" description="Buat pelanggan baru untuk mulai mengelola kontak." />
            }
          />
        </div>
      </LiquidGlass>

      <ConfirmDialog
        open={!!deleteTarget}
        onOpenChange={(v) => !v && setDeleteTarget(null)}
        title="Hapus Pelanggan"
        description={`Apakah Anda yakin ingin menghapus kontak "${deleteTarget?.name}"? Tindakan ini tidak dapat dibatalkan.`}
        confirmLabel="Hapus"
        variant="destructive"
        loading={deleteMut.isPending}
        onConfirm={handleDelete}
      />
    </div>
  );
}

"use client";
import { EmptyState } from "@/components/ui/empty-state";

import { useState, useMemo, useCallback } from "react";
