"use client";

import * as React from "react";
import Link from "next/link";
import {
  ArchiveIcon,
  ImageIcon,
  Loader2Icon,
  RotateCcwIcon,
} from "lucide-react";

import { Button } from "@/components/ui/button";
import { LiquidGlass } from "@/components/ui/liquid-glass";
import {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import type { ColumnDef } from "@tanstack/react-table";
import { DataTable } from "@/components/ui/data-table/data-table";
import {
  useArchivedProducts,
  useRestoreProduct,
} from "@/hooks/master-produk/use-archived-products";
import { useListState } from "@/hooks/use-list-state";
import type { ArchivedProduct } from "@/types/master-produk";
import { FilterToolbar } from "../filter-toolbar";
import { CopySku } from "@/components/dashboard/shared/copy-sku";

const fmtDate = (iso: string | null) =>
  iso
    ? new Intl.DateTimeFormat("id-ID", { dateStyle: "medium" }).format(
        new Date(iso),
      )
    : "—";

function RestoreButton({
  item,
  pending,
  onRestore,
}: {
  item: ArchivedProduct;
  pending: boolean;
  onRestore: (item: ArchivedProduct) => void;
}) {
  return (
    <Dialog>
      <DialogTrigger asChild>
        <Button variant="outline" size="sm" disabled={pending}>
          {pending ? (
            <Loader2Icon className="animate-spin motion-reduce:animate-none" />
          ) : (
            <RotateCcwIcon className="mr-1.5 size-4" />
          )}
          Pulihkan
        </Button>
      </DialogTrigger>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>Pulihkan produk?</DialogTitle>
          <DialogDescription>
            {item.itemName} akan dikembalikan ke status Master dan tampil
            kembali di katalog aktif.
          </DialogDescription>
        </DialogHeader>
        <DialogFooter>
          <DialogClose asChild>
            <Button variant="outline">Batal</Button>
          </DialogClose>
          <DialogClose asChild>
            <Button variant="primary" onClick={() => onRestore(item)}>
              Pulihkan
            </Button>
          </DialogClose>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

export function ArchiveView() {
