interface GalleryItem {
  url: string;
  type: "image" | "video";
}

function Gallery({
  media,
  images,
  fallback,
  name,
}: {
  media: DetailMedia[];
  images: { url: string; isPrimary: boolean }[];
  fallback: string | null;
  name: string;
}) {
  const items: GalleryItem[] = React.useMemo(() => {
    if (media.length > 0) {
      return media
        .filter((m) => m.url)
        .sort((a, b) => a.sortOrder - b.sortOrder)
        .map((m) => ({ url: m.url, type: m.mediaType }));
    }
    if (images.length > 0)
      return images.map((i) => ({ url: i.url, type: "image" as const }));
    if (fallback) return [{ url: fallback, type: "image" as const }];
    return [];
  }, [media, images, fallback]);

  const [idx, setIdx] = React.useState(0);
  const current = items[Math.min(idx, items.length - 1)];

  return (
    <div className="space-y-2">
      <div className="grid aspect-square w-full place-items-center overflow-hidden rounded-xl border border-border bg-muted/30">
        {!current ? (
          <ImageIcon className="size-10 text-muted-foreground" />
        ) : current.type === "video" ? (
          <VideoPlayer src={current.url} className="size-full" />
        ) : (
          <img
            src={current.url}
            alt={name}
            className="size-full object-contain"
          />
        )}
      </div>
      {items.length > 1 && (
        <ScrollArea className="w-full">
          <div className="flex gap-2 pb-3">
            {items.map((item, i) => (
              <button
                key={`${item.url}-${i}`}
                type="button"
                onClick={() => setIdx(i)}
                aria-label={item.type === "video" ? "Video" : `Gambar ${i + 1}`}
                className={cn(
                  "relative size-14 shrink-0 overflow-hidden rounded-xl border transition",
                  i === idx
                    ? "border-primary ring-2 ring-primary/30"
                    : "border-border hover:border-primary/50",
                )}
              >
                {item.type === "video" ? (
                  <div className="relative size-full bg-muted/60">
                    { }
                    <video
                      src={item.url}
                      muted
                      playsInline
                      preload="metadata"
                      className="size-full object-cover"
                      onLoadedData={(e) => {
                        e.currentTarget.currentTime = 0.5;
                      }}
                    />
                    <div className="absolute inset-0 flex items-center justify-center bg-black/10">
                      <PlayIcon className="size-4 fill-current text-white drop-shadow" />
                    </div>
                  </div>
                ) : (
                  <img
                    src={item.url}
                    alt={`${name} ${i + 1}`}
                    className="size-full object-cover"
                  />
                )}
              </button>
            ))}
          </div>
          <ScrollBar orientation="horizontal" />
        </ScrollArea>
      )}
    </div>
  );
}

function InfoRow({ label, value }: { label: string; value: React.ReactNode }) {
  return (
