      <div className="overflow-x-auto rounded-lg border border-border/60 bg-card">
        <DataTable
          columns={React.useMemo<ColumnDef<ChannelListingRow>[]>(
            () => [
              {
                accessorKey: "sku",
                header: "SKU",
                cell: ({ row }) => (
                  <span className="font-mono text-xs text-primary">
                    {row.original.sku}
