                </Button>
              )}
            </div>
          );
        },
      },
    ],
    [reupload.isPending],
  );

  const onReupload = (id: string) => {
    reupload.mutate(id, {
      onSuccess: () => toast.success("Produk diantrekan untuk upload ulang"),
      onError: () => toast.error("Gagal mengantrekan upload ulang"),
    });
