"use client";

import * as React from "react";
import type { PaginationState } from "@tanstack/react-table";
import {
  AlertTriangleIcon,
  Loader2Icon,
  PlusIcon,
  RocketIcon,
  SearchXIcon,
} from "lucide-react";

import { Button } from "@/components/ui/button";
import { LiquidGlass } from "@/components/ui/liquid-glass";
import { DataTable } from "@/components/ui/data-table";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { ConfirmDialog } from "@/components/ui/confirm-dialog";
import { ChannelLogo } from "@/components/dashboard/integrasi-channel/channel-logo";
import {
  useNaikkanDetail,
  useNaikkanHistory,
  useUpdateNaikkanProduct,
  useRemoveNaikkanProduct,
  useExecuteRaise,
  useAddNaikkanProduct,
} from "@/hooks/master-produk/use-naikkan";
import type { RaiseProductDetail } from "@/hooks/master-produk/use-naikkan";
import type { ChannelCode } from "@/types/channel";
import { buildProdukColumns } from "./naikkan-produk-columns";
import { aktivitasColumns } from "./naikkan-aktivitas-columns";
import { NaikkanProdukPickerDialog } from "./naikkan-produk-picker-dialog";

type TabValue = "produk" | "aktivitas";

export function NaikkanDetailView({ id }: { id: string }) {
  const [tab, setTab] = React.useState<TabValue>("produk");
  const [produkPagination, setProdukPagination] =
    React.useState<PaginationState>({
      pageIndex: 0,
      pageSize: 20,
    });
  const [historyPagination, setHistoryPagination] =
    React.useState<PaginationState>({
      pageIndex: 0,
      pageSize: 20,
    });

  const detailQuery = useNaikkanDetail(id, {
    page: produkPagination.pageIndex + 1,
    perPage: produkPagination.pageSize,
  });

  const historyQuery = useNaikkanHistory(id, {
    page: historyPagination.pageIndex + 1,
    perPage: historyPagination.pageSize,
  });

  const store = detailQuery.data?.store;
  const details = detailQuery.data?.details ?? [];
  const detailMeta = detailQuery.data?.meta;
  const historyItems = historyQuery.data?.items ?? [];
  const historyMeta = historyQuery.data?.meta;

  const updateMut = useUpdateNaikkanProduct(id);
  const removeMut = useRemoveNaikkanProduct(id);
  const raiseMut = useExecuteRaise(id);
  const addMut = useAddNaikkanProduct(id);

  const [removeTarget, setRemoveTarget] =
    React.useState<RaiseProductDetail | null>(null);
  const [showPicker, setShowPicker] = React.useState(false);
  const [showRaiseConfirm, setShowRaiseConfirm] = React.useState(false);

  const existingMappingIds = React.useMemo(
    () => new Set(details.map((d) => d.raiseproductDetailId)),
    [details],
  );

  const produkColumns = React.useMemo(
    () =>
      buildProdukColumns({
        onToggleRepeatable: (detail, value) =>
          updateMut.mutate({
            detailId: detail.raiseproductDetailId,
            data: { is_repeatable: value },
          }),
        onRemove: (detail) => setRemoveTarget(detail),
      }),
    [],
  );

  if (detailQuery.isLoading) {
    return (
      <LiquidGlass
        radius={24}
        intensity="default"
        className="bg-white/40 dark:bg-white/[0.06]"
      >
        <div className="flex items-center justify-center py-20">
          <Loader2Icon className="size-6 animate-spin text-muted-foreground" />
        </div>
      </LiquidGlass>
    );
  }

  if (detailQuery.isError || !store) {
    return (
      <LiquidGlass
        radius={24}
        intensity="default"
        className="bg-white/40 dark:bg-white/[0.06]"
      >
        <div className="flex flex-col items-center gap-3 py-12 text-center">
          <AlertTriangleIcon className="size-8 text-destructive" />
          <p className="font-medium">Gagal memuat data</p>
          <Button
            variant="outline"
            size="sm"
            onClick={() => detailQuery.refetch()}
            disabled={detailQuery.isFetching}
          >
            Coba lagi
          </Button>
        </div>
      </LiquidGlass>
    );
  }

  return (
    <LiquidGlass
      radius={24}
      intensity="default"
      className="bg-white/40 dark:bg-white/[0.06]"
    >
      {}
      <div className="flex flex-wrap items-center justify-between gap-3 border-b border-border/60 px-4 py-3 sm:px-5">
        <div className="flex items-center gap-3">
          {store.channelCode && (
            <ChannelLogo
              code={store.channelCode as ChannelCode}
              name={store.channelName ?? store.channelCode}
              className="size-9 rounded-lg text-2xs"
            />
          )}
          <div>
            <h2 className="font-semibold">{store.storeName ?? "—"}</h2>
            <p className="text-xs text-muted-foreground">
              {store.channelName ?? store.channelCode} · {store.productActive}{" "}
              produk aktif
            </p>
          </div>
        </div>

        <div className="flex items-center gap-2">
          <Button
            variant="outline"
            size="sm"
            className="h-9 gap-1.5"
            onClick={() => setShowPicker(true)}
          >
            <PlusIcon className="size-4" />
            Tambah Produk
          </Button>
          <Button
            variant="primary"
            size="sm"
            className="h-9 gap-1.5"
            disabled={details.length === 0 || raiseMut.isPending}
            onClick={() => setShowRaiseConfirm(true)}
          >
            {raiseMut.isPending ? (
              <Loader2Icon className="size-4 animate-spin" />
            ) : (
              <RocketIcon className="size-4" />
            )}
            Naikkan Produk
          </Button>
        </div>
      </div>

      {}
      <div className="border-b border-border/60 px-4 pt-1 sm:px-5">
        <Tabs value={tab} onValueChange={(v) => setTab(v as TabValue)}>
          <TabsList variant="line">
            <TabsTrigger value="produk">Produk</TabsTrigger>
            <TabsTrigger value="aktivitas">Aktivitas</TabsTrigger>
          </TabsList>
        </Tabs>
      </div>

      {}
      <div className="px-4 py-5 sm:px-5">
        {tab === "produk" ? (
          <DataTable
            columns={produkColumns}
            data={details}
            isLoading={detailQuery.isFetching && !detailQuery.data}
            getRowId={(d) => d.raiseproductDetailId}
            hideToolbar
            manualPagination
            rowCount={detailMeta?.total ?? 0}
            pagination={produkPagination}
            onPaginationChange={setProdukPagination}
            tableContainerClassName="border-0 bg-transparent backdrop-blur-none [&_[data-slot=table-header]]:bg-transparent"
            emptyState={
              <div className="flex flex-col items-center gap-2 py-6">
                <SearchXIcon className="size-8 text-muted-foreground" />
                <p className="font-medium">Belum ada produk</p>
                <p className="text-sm text-muted-foreground">
                  Klik &ldquo;Tambah Produk&rdquo; untuk menambahkan produk
                  channel.
                </p>
              </div>
            }
          />
        ) : (
          <DataTable
            columns={aktivitasColumns}
            data={historyItems}
            isLoading={historyQuery.isLoading}
            getRowId={(d) => `${d.raiseproductDetailId}-${d.endTime}`}
            hideToolbar
            manualPagination
            rowCount={historyMeta?.total ?? 0}
            pagination={historyPagination}
            onPaginationChange={setHistoryPagination}
            tableContainerClassName="border-0 bg-transparent backdrop-blur-none [&_[data-slot=table-header]]:bg-transparent"
            emptyState={
              <div className="flex flex-col items-center gap-2 py-6">
                <SearchXIcon className="size-8 text-muted-foreground" />
                <p className="font-medium">Belum ada aktivitas</p>
                <p className="text-sm text-muted-foreground">
                  Riwayat naikkan produk akan tampil di sini.
                </p>
              </div>
            }
          />
        )}
      </div>

      {}
      <NaikkanProdukPickerDialog
        open={showPicker}
        onOpenChange={setShowPicker}
        shopId={store.storeId}
        existingMappingIds={existingMappingIds}
        onAdd={(mappingId) => {
          addMut.mutate(mappingId, {
            onSuccess: () => {},
          });
        }}
        addingId={addMut.isPending ? (addMut.variables as string) : null}
      />

      {}
      <ConfirmDialog
        open={!!removeTarget}
        onOpenChange={(open) => !open && setRemoveTarget(null)}
        title="Hapus Produk dari Naikkan?"
        description={`Produk "${removeTarget?.itemGroupName}" akan dilepas dari daftar naikkan.`}
        confirmLabel="Hapus"
        variant="destructive"
        loading={removeMut.isPending}
        onConfirm={() => {
          if (!removeTarget) return;
          removeMut.mutate(removeTarget.raiseproductDetailId, {
            onSuccess: () => setRemoveTarget(null),
          });
        }}
      />

      {}
      <ConfirmDialog
        open={showRaiseConfirm}
        onOpenChange={setShowRaiseConfirm}
        title="Naikkan Semua Produk?"
        description="Semua produk aktif akan diantrekan untuk dinaikkan di Shopee. Proses berjalan di background."
        confirmLabel="Naikkan"
        loading={raiseMut.isPending}
        onConfirm={() => {
          raiseMut.mutate(undefined, {
            onSuccess: () => setShowRaiseConfirm(false),
          });
        }}
      />
    </LiquidGlass>
  );
}

"use client";

import type { ColumnDef } from "@tanstack/react-table";
import { ExternalLinkIcon, ImageIcon, Trash2Icon } from "lucide-react";

import { Button } from "@/components/ui/button";
import { Switch } from "@/components/ui/switch";
import { StatusBadge } from "@/components/dashboard/shared/status-badge";
import type { RaiseProductDetail } from "@/hooks/master-produk/use-naikkan";
import { CountdownTimer } from "./countdown-timer";

function statusBadge(isActive: boolean) {
  return (
    <StatusBadge 
      domain="product-boost" 
      status={isActive ? "ACTIVE" : "INACTIVE"} 
    />
  );
}

function resultBadge(isSuccess: boolean | null) {
  if (isSuccess === null)
    return <span className="text-muted-foreground">—</span>;
  return (
    <StatusBadge 
      domain="product-boost-activity" 
      status={isSuccess ? "SUCCESS" : "FAILED"} 
    />
  );
}

export function buildProdukColumns(opts: {
  onToggleRepeatable: (detail: RaiseProductDetail, value: boolean) => void;
  onRemove: (detail: RaiseProductDetail) => void;
}): ColumnDef<RaiseProductDetail>[] {
  return [
    {
      id: "product",
      header: "Produk",
      cell: ({ row }) => {
        const d = row.original;
        const thumb = d.thumbnails.find(Boolean) ?? null;
        const skuDisplay =
          d.itemCodes.length <= 2
            ? d.itemCodes.join(", ")
            : `${d.itemCodes.slice(0, 2).join(", ")} + ${d.itemCodes.length - 2} SKU lainnya`;

        return (
          <div className="flex items-center gap-3">
            <div className="flex size-10 shrink-0 items-center justify-center overflow-hidden rounded-xl border border-border bg-muted/40">
              {thumb ? (
                <img
                  src={thumb}
                  alt={d.itemGroupName ?? ""}
                  className="size-full object-cover"
                />
              ) : (
                <ImageIcon className="size-4 text-muted-foreground" />
              )}
            </div>
            <div className="min-w-0">
              <p className="line-clamp-1 font-medium">
                {d.itemGroupName ?? "—"}
              </p>
              <p className="line-clamp-1 font-mono text-xs text-muted-foreground">
                {skuDisplay || "—"}
              </p>
            </div>
          </div>
        );
      },
    },
    {
      id: "channel_url",
      header: "URL",
      cell: ({ row }) => {
        const url = row.original.channelUrl;
        if (!url) return <span className="text-muted-foreground">—</span>;
        return (
          <a
            href={url}
            target="_blank"
            rel="noopener noreferrer"
            className="inline-flex items-center gap-1 text-sm text-primary hover:underline"
          >
            <ExternalLinkIcon className="size-3.5" />
            Lihat
          </a>
        );
      },
    },
    {
      id: "status",
      header: "Status",
      cell: ({ row }) => statusBadge(row.original.isActive),
    },
    {
      id: "countdown",
      header: "Sisa Waktu",
      cell: ({ row }) => (
        <CountdownTimer
          startTime={row.original.startTime}
          endTime={row.original.endTime}
        />
      ),
    },
    {
      id: "repeatable",
      header: "Otomatis",
      cell: ({ row }) => {
        const d = row.original;
        return (
          <Switch
            checked={d.isRepeatable}
            onCheckedChange={(checked) => opts.onToggleRepeatable(d, checked)}
          />
        );
      },
    },
    {
      id: "result",
      header: "Hasil",
      cell: ({ row }) => resultBadge(row.original.isSuccess),
    },
    {
      id: "actions",
      header: "",
      cell: ({ row }) => (
        <Button
          variant="ghost"
          size="sm"
          className="h-8 text-destructive hover:text-destructive"
          onClick={() => opts.onRemove(row.original)}
        >
          <Trash2Icon className="size-4" />
        </Button>
      ),
    },
  ];
}

"use client";

import * as React from "react";
import {
  CheckIcon,
  ImageIcon,
  Loader2Icon,
  PlusIcon,
  SearchIcon,
} from "lucide-react";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { useNaikkanProductPicker } from "@/hooks/master-produk/use-naikkan";

interface Props {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  shopId: string | null;
  existingMappingIds: Set<string>;
  onAdd: (mappingId: string) => void;
  addingId: string | null;
}

export function NaikkanProdukPickerDialog({
  open,
  onOpenChange,
  shopId,
  existingMappingIds,
  onAdd,
  addingId,
}: Props) {
  const [search, setSearch] = React.useState("");
  const [appliedSearch, setAppliedSearch] = React.useState("");
  const [page, setPage] = React.useState(1);

  const [prevOpen, setPrevOpen] = React.useState(open);
  if (open !== prevOpen) {
    setPrevOpen(open);
    if (!open) {
      setSearch("");
      setAppliedSearch("");
      setPage(1);
    }
  }

  const query = useNaikkanProductPicker(shopId, appliedSearch, page, open);

  const items = query.data?.items ?? [];
  const total = query.data?.meta?.total ?? 0;
  const lastPage = query.data?.meta?.last_page ?? 1;

  const applySearch = () => {
    setAppliedSearch(search);
    setPage(1);
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-lg">
        <DialogHeader>
          <DialogTitle>Tambah Produk</DialogTitle>
          <DialogDescription>
            Pilih produk channel untuk ditambahkan ke daftar naikkan.
          </DialogDescription>
        </DialogHeader>

        <div className="flex items-center gap-2">
          <div className="relative flex-1">
            <SearchIcon className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" />
            <Input
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === "Enter") applySearch();
              }}
              placeholder="Cari produk..."
              className="h-9 pl-9"
            />
          </div>
          <Button
            variant="outline"
            size="sm"
            className="h-9"
            onClick={applySearch}
          >
            Cari
          </Button>
        </div>

        <div className="max-h-80 overflow-y-auto">
          {query.isLoading ? (
            <div className="flex items-center justify-center py-8">
              <Loader2Icon className="size-6 animate-spin text-muted-foreground" />
            </div>
          ) : items.length === 0 ? (
            <p className="py-8 text-center text-sm text-muted-foreground">
              Tidak ada produk ditemukan.
            </p>
          ) : (
            <div className="divide-y">
              {items.map((item) => {
                const isAdded = item.mappingId
                  ? existingMappingIds.has(item.mappingId)
                  : false;
                const isAdding = item.mappingId === addingId;

                return (
                  <div
                    key={item.mappingId ?? item.channelGroupId}
                    className="flex items-center gap-3 px-1 py-2.5"
                  >
                    <div className="flex size-10 shrink-0 items-center justify-center overflow-hidden rounded-xl border border-border bg-muted/40">
                      {item.thumbnail ? (
                        <img
                          src={item.thumbnail}
                          alt={item.itemGroupName ?? ""}
                          className="size-full object-cover"
                        />
                      ) : (
                        <ImageIcon className="size-4 text-muted-foreground" />
                      )}
                    </div>
                    <div className="min-w-0 flex-1">
                      <p className="line-clamp-1 text-sm font-medium">
                        {item.itemGroupName ?? "—"}
                      </p>
                      <p className="line-clamp-1 font-mono text-xs text-muted-foreground">
                        {item.variants
                          .map((v) => v.masterSku ?? v.channelSku)
                          .filter(Boolean)
                          .join(", ") || "—"}
                      </p>
                    </div>

                    {isAdded ? (
                      <span className="flex items-center gap-1 text-xs text-muted-foreground">
                        <CheckIcon className="size-3.5" />
                        Ditambahkan
                      </span>
                    ) : (
                      <Button
                        variant="outline"
                        size="sm"
                        className="h-7 gap-1 text-xs"
                        disabled={!item.mappingId || isAdding}
                        onClick={() => item.mappingId && onAdd(item.mappingId)}
                      >
                        {isAdding ? (
                          <Loader2Icon className="size-3 animate-spin" />
                        ) : (
                          <PlusIcon className="size-3" />
                        )}
                        Tambah
                      </Button>
                    )}
                  </div>
                );
              })}
            </div>
          )}
        </div>

        {lastPage > 1 && (
          <div className="flex items-center justify-between border-t pt-3">
            <span className="text-xs text-muted-foreground">
              {total} produk ditemukan
            </span>
            <div className="flex items-center gap-1">
              <Button
                variant="outline"
                size="sm"
                className="h-7 text-xs"
                disabled={page <= 1}
                onClick={() => setPage((p) => p - 1)}
              >
                Sebelumnya
              </Button>
              <span className="px-2 text-xs tabular-nums text-muted-foreground">
                {page}/{lastPage}
              </span>
              <Button
                variant="outline"
                size="sm"
                className="h-7 text-xs"
                disabled={page >= lastPage}
                onClick={() => setPage((p) => p + 1)}
              >
                Berikutnya
              </Button>
            </div>
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}

