type MatchState = {
  matched: boolean;
  message: string;
  rulesSummary: RulesSummary | null;
};

function aggregateMatches(rows: MatchRow[]): Map<string, MatchState> {
  const byStore = new Map<string, MatchRow[]>();
  for (const r of rows) {
    const list = byStore.get(r.storeId) ?? [];
    list.push(r);
    byStore.set(r.storeId, list);
  }

  const result = new Map<string, MatchState>();
  for (const [storeId, list] of byStore) {
    const allMatched = list.every((r) => r.matched);
    const firstFail = list.find((r) => !r.matched);
    result.set(storeId, {
      matched: allMatched,
      message: allMatched
        ? "Sesuai sama master"
        : (firstFail?.message ?? "Tidak cocok"),
      rulesSummary: list[0]?.rulesSummary ?? null,
    });
  }
  return result;
}

export function DestinationTable({
  productId,
  productName,
  isUploaded,
  search,
  channel,
}: {
  productId: string;
  productName: string;
  isUploaded: boolean;
  search?: string;
  channel?: string;
}) {
  const router = useRouter();
  const [pagination, setPagination] = React.useState({
    pageIndex: 0,
    pageSize: 20,
  });

  const filterKey = `${search}|${channel ?? ""}`;
  const [prevFilterKey, setPrevFilterKey] = React.useState(filterKey);
  if (prevFilterKey !== filterKey) {
    setPrevFilterKey(filterKey);
    if (pagination.pageIndex !== 0)
      setPagination((p) => ({ ...p, pageIndex: 0 }));
  }

  const listing = useUploadListing(productId, {
    isUploaded,
    search,
    channel,
    page: pagination.pageIndex + 1,
    perPage: pagination.pageSize,
  });

  const notifyUploaded = React.useCallback((uploaded: number) => {
    if (uploaded > 0) {
      toast.success(`${uploaded} toko berhasil diantrekan`);
    }
  }, []);

  const match = useMatchListing(productId);
  const upload = useUploadToStores(productId);
  const uploadWithAttrs = useUploadWithAttributes(productId);

  const [attrDialog, setAttrDialog] = React.useState<{
    shopIds: string[];
    shopId: string;
    resetSelection?: () => void;
  } | null>(null);

  const rows = React.useMemo(() => listing.data?.items ?? [], [listing.data]);
  const total = listing.data?.meta?.total ?? 0;

  const [matchMap, setMatchMap] = React.useState<Map<string, MatchState>>(
    new Map(),
  );
  const [matching, setMatching] = React.useState<Set<string>>(new Set());

  const mergeMatches = React.useCallback((next: Map<string, MatchState>) => {
    setMatchMap((prev) => {
      const merged = new Map(prev);
      for (const [k, v] of next) merged.set(k, v);
      return merged;
    });
  }, []);

  const runMatch = React.useCallback(
    (storeIds: string[]) => {
      const ids = Array.from(new Set(storeIds)).filter(Boolean);
      if (ids.length === 0) return;
      setMatching((prev) => {
        const next = new Set(prev);
        ids.forEach((id) => next.add(id));
        return next;
      });
      match.mutate(ids, {
        onSuccess: (res) => mergeMatches(aggregateMatches(res)),
        onSettled: () => {
          setMatching((prev) => {
            const next = new Set(prev);
            ids.forEach((id) => next.delete(id));
            return next;
          });
        },
      });
    },
    [match, mergeMatches],
  );

  const requestedKey = React.useRef<string>("");
  React.useEffect(() => {
    const storeIds = Array.from(
      new Set(rows.map((r) => r.storeId).filter(Boolean)),
    );
    const key = storeIds.join("|");
    if (!key || key === requestedKey.current) return;
    requestedKey.current = key;
    runMatch(storeIds);
  }, [rows]);

  const columns = React.useMemo<ColumnDef<UploadDestination>[]>(
    () => [
      {
        id: "select",
        header: ({ table }) => (
          <Checkbox
            checked={
              table.getIsAllPageRowsSelected() ||
              (table.getIsSomePageRowsSelected() && "indeterminate")
            }
            onCheckedChange={(value) =>
              table.toggleAllPageRowsSelected(!!value)
            }
            aria-label="Pilih semua"
          />
        ),
        cell: ({ row }) => (
          <Checkbox
            checked={row.getIsSelected()}
            onCheckedChange={(value) => row.toggleSelected(!!value)}
            onClick={(e) => e.stopPropagation()}
            aria-label="Pilih baris"
          />
        ),
        enableSorting: false,
        enableHiding: false,
        size: 36,
      },
      {
        id: "channel",
        header: "Channel",
        enableSorting: false,
        cell: ({ row }) => {
          const d = row.original;
          return (
            <div className="flex items-center gap-3">
              <ChannelLogo
                code={(d.channelCode ?? "") as ChannelCode}
                name={d.channelName ?? "—"}
                className="size-9"
              />
              <span className="font-medium">{d.channelName ?? "—"}</span>
            </div>
          );
        },
      },
      {
        id: "toko",
        header: "Toko",
        enableSorting: false,
        cell: ({ row }) => {
          const d = row.original;
          return (
            <div className="flex flex-col gap-0.5">
              <span className="truncate">{d.storeName ?? "—"}</span>
              {isUploaded && (
                <div className="flex items-center gap-1.5 text-xs text-muted-foreground">
                  {d.channelGroupId && (
                    <span className="font-mono tabular-nums">
                      {d.channelGroupId}
                    </span>
                  )}
                  <SyncStatusBadge status={d.syncStatus} />
                </div>
              )}
            </div>
          );
        },
      },
      {
        id: "keterangan",
        header: "Keterangan",
        enableSorting: false,
        cell: () => <span className="text-muted-foreground">—</span>,
      },
      {
        id: "kecocokan",
        header: "Kecocokan Data Master dengan Channel",
        enableSorting: false,
        cell: ({ row }) => {
          const storeId = row.original.storeId;
          const state = matchMap.get(storeId);
          const isMatching = matching.has(storeId);

          if (!state && isMatching) {
            return (
              <span className="inline-flex items-center gap-1.5 text-sm text-muted-foreground">
                <Loader2Icon className="size-4 animate-spin motion-reduce:animate-none" />
                memeriksa…
              </span>
            );
          }
          if (!state) {
            return <span className="text-sm text-muted-foreground">—</span>;
          }
          if (state.matched) {
            return (
              <div className="flex flex-col gap-0.5">
                <span className="inline-flex items-center gap-1.5 text-sm text-success">
                  <CheckCircleIcon className="size-4" />
                  Cocok
                </span>
                {state.rulesSummary?.hasSpecialRequirements && (
                  <span className="ml-[22px] inline-flex items-center gap-1 text-xs text-info">
                    <AlertTriangleIcon className="size-3 shrink-0" />
                    {state.rulesSummary.requiredCertsCount > 0
                      ? `${state.rulesSummary.requiredCertsCount} sertifikasi diperlukan`
                      : "Persyaratan khusus"}
                  </span>
                )}
              </div>
            );
          }
          return (
            <div className="flex flex-col gap-0.5">
              <span className="inline-flex items-center gap-1.5 text-sm text-warning">
                <AlertTriangleIcon className="size-4 shrink-0" />
                <span className="truncate" title={state.message}>
                  {state.message}
                </span>
              </span>
              <Link
                href={`/dashboard/produk/${productId}/edit`}

                onClick={(e) => e.stopPropagation()}
                className="ml-[22px] text-xs font-medium text-primary hover:underline"
              >
                Perbaiki &rarr;
              </Link>
            </div>
          );
        },
      },
      {
        id: "actions",
        header: () => <span className="sr-only">Aksi</span>,
        enableSorting: false,
        enableHiding: false,
        cell: ({ row }) => {
          const d = row.original;
          const isMatching = matching.has(d.storeId);
          const state = matchMap.get(d.storeId);
          const isBlocked = state?.matched === false;
          return (
            <div className="flex items-center justify-end gap-1">
              <Button
                variant="ghost"
                size="icon-sm"
                disabled={isMatching}
                onClick={(e) => {
                  e.stopPropagation();
                  runMatch([d.storeId]);
                }}
                title="Cocokkan data dengan master"
                aria-label="Cocokkan"
              >
                {isMatching ? (
                  <Loader2Icon className="animate-spin motion-reduce:animate-none" />
                ) : (
                  <RotateCwIcon />
                )}
              </Button>
              <Button
                variant="ghost"
                size="icon-sm"
                disabled
                title="Segera"
                aria-label="Edit"
              >
                <PencilIcon />
              </Button>
              <Button
                variant="ghost"
                size="icon-sm"
                disabled={
                  !d.shopId ||
                  upload.isPending ||
                  uploadWithAttrs.isPending ||
                  isBlocked
                }
                onClick={(e) => {
                  e.stopPropagation();
                  if (!d.shopId || isBlocked) return;
                  if (d.channelCode === "tiktok") {
                    setAttrDialog({ shopIds: [d.shopId], shopId: d.shopId });
                  } else {
                    upload.mutate([d.shopId], {
                      onSuccess: (res) => notifyUploaded(res.uploaded),
                    });
                  }
                }}
                title={
                  !d.shopId
                    ? "Toko tidak punya shop id"
                    : isBlocked
                      ? (state?.message ??
                        "Data belum cocok dengan master — perbaiki dulu")
                      : "Upload ke channel"
                }
                aria-label="Upload"
              >
                <UploadCloudIcon />
              </Button>
            </div>
          );
        },
        size: 132,
      },
    ],
    [
      isUploaded,
      matchMap,
      matching,
      notifyUploaded,
      runMatch,
      upload,
      uploadWithAttrs,
    ],
  );

  const [confirmRows, setConfirmRows] = React.useState<
    UploadDestination[] | null
  >(null);

  const blockedEntries = React.useMemo(
    () => [...matchMap.values()].filter((s) => !s.matched),
    [matchMap],
  );

  return (
    <>
      {blockedEntries.length > 0 && (
        <div className="flex items-start gap-2 rounded-lg border border-warning/30 bg-warning/10 px-3 py-2.5 text-sm text-warning">
          <AlertTriangleIcon className="mt-0.5 size-4 shrink-0" />
          <div className="min-w-0">
            <p className="font-medium">
              {blockedEntries.length} toko tidak bisa diupload
            </p>
            <p className="mt-0.5 text-warning/80">
              {blockedEntries[0].message}
            </p>
            <Link
              href={`/dashboard/produk/${productId}/edit`}

              className="mt-1 inline-block font-medium underline underline-offset-2 hover:text-warning/80"
            >
              Edit Produk
            </Link>
          </div>
        </div>
      )}

      <DataTable<UploadDestination, unknown>
        columns={columns}
        data={rows}
        getRowId={(row) => row.storeId}
        isLoading={listing.isLoading}
        hideToolbar
        enableRowSelection
        manualPagination
        rowCount={total}
        pagination={pagination}
        onPaginationChange={setPagination}
        tableContainerClassName="rounded-2xl"
        emptyState={
          <span className="text-muted-foreground">
            {isUploaded
              ? "Produk belum diupload ke toko mana pun."
              : "Semua toko sudah terdaftar untuk produk ini."}
          </span>
        }
        bulkActions={(selected, table) => (
          <>
            <Button
              variant="outline"
              size="sm"
              className="gap-2"
              onClick={() => runMatch(selected.map((r) => r.storeId))}
            >
              <RotateCwIcon className="size-4" />
              Cocokan data dengan master
            </Button>
            <Button
              variant="primary"
              size="sm"
              className="gap-2"
              disabled={upload.isPending}
              onClick={() => setConfirmRows(selected)}
            >
              <UploadCloudIcon className="size-4" />
              Upload
            </Button>
            {confirmRows && (
              <Dialog
                open={!!confirmRows}
                onOpenChange={(o) => {
                  if (!o) setConfirmRows(null);
                }}
              >
                <DialogContent>
                  {(() => {
                    const blockedCount = confirmRows.filter(
                      (r) => matchMap.get(r.storeId)?.matched === false,
                    ).length;
                    const eligibleCount = confirmRows.filter(
                      (r) =>
                        r.shopId && matchMap.get(r.storeId)?.matched !== false,
                    ).length;
                    return (
                      <DialogHeader>
                        <DialogTitle>Upload ke channel</DialogTitle>
                        <DialogDescription>
                          Upload{" "}
                          <span className="font-medium">{productName}</span> ke{" "}
                          {eligibleCount} toko{" "}
                          {isUploaded
                            ? "(upload ulang)"
                            : "yang belum terdaftar"}
                          ?
                          {blockedCount > 0 && (
                            <span className="mt-1 block text-warning">
                              {blockedCount} toko dilewati karena data belum
                              cocok dengan master.
                            </span>
                          )}
                        </DialogDescription>
                      </DialogHeader>
                    );
                  })()}
                  <DialogFooter>
                    <DialogClose asChild>
                      <Button variant="outline">Batal</Button>
                    </DialogClose>
                    <DialogClose asChild>
                      <Button
                        variant="primary"
                        onClick={() => {
                          const eligible = confirmRows.filter(
                            (r) =>
                              r.shopId &&
                              matchMap.get(r.storeId)?.matched !== false,
                          );
                          const nonTiktok = eligible
                            .filter((r) => r.channelCode !== "tiktok")
                            .map((r) => r.shopId!);
                          const tiktok = eligible.filter(
                            (r) => r.channelCode === "tiktok",
                          );

                          if (nonTiktok.length > 0) {
                            upload.mutate(nonTiktok, {
                              onSuccess: (res) => notifyUploaded(res.uploaded),
                            });
                          }

                          if (tiktok.length > 0) {
                            const tiktokShopIds = tiktok.map((r) => r.shopId!);
                            setAttrDialog({
                              shopIds: tiktokShopIds,
                              shopId: tiktokShopIds[0],
                              resetSelection: () => table.resetRowSelection(),
                            });
                          } else {
                            table.resetRowSelection();
                          }

                          setConfirmRows(null);
                        }}
                      >
                        Upload
                      </Button>
                    </DialogClose>
                  </DialogFooter>
                </DialogContent>
              </Dialog>
            )}
          </>
        )}
      />

      {listing.isError && (
        <p className={cn("mt-3 text-sm text-destructive")}>
          Gagal memuat daftar toko.{" "}
          <button
            type="button"
            className="underline underline-offset-2"
            onClick={() => listing.refetch()}
          >
            Coba lagi
          </button>
        </p>
      )}

      {attrDialog && (
        <AttributeSelectionDialog
          open={!!attrDialog}
          onOpenChange={(o) => {
            if (!o) setAttrDialog(null);
          }}
          productId={productId}
          shopId={attrDialog.shopId}
          isUploading={uploadWithAttrs.isPending}
          onConfirm={(mapping) => {
            uploadWithAttrs.mutate(
              {
                shopIds: attrDialog.shopIds,
                attributeMapping:
                  Object.keys(mapping).length > 0 ? mapping : null,
              },
              {
                onSuccess: (res) => notifyUploaded(res.uploaded),
                onSettled: () => {
                  attrDialog.resetSelection?.();
                  setAttrDialog(null);
                },
              },
            );
          }}
        />
      )}
    </>
  );
}

"use client";

import * as React from "react";
import type { ColumnDef, PaginationState } from "@tanstack/react-table";
import { ImageIcon, Loader2Icon, Trash2Icon, UploadIcon } from "lucide-react";

import { Button } from "@/components/ui/button";
import { LiquidGlass } from "@/components/ui/liquid-glass";
import { DataTable } from "@/components/ui/data-table";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  useChannelDrafts,
  useDeleteDraft,
  useUploadDraft,
} from "@/hooks/master-produk/use-upload";
import type { DraftRow, DraftStatus } from "@/hooks/master-produk/use-upload";
import type { ChannelCode } from "@/types/channel";
import { ChannelLogo } from "@/components/dashboard/integrasi-channel/channel-logo";
import { FilterToolbar } from "../filter-toolbar";
import { SyncStatusBadge } from "../detail/tab-pagination";

const STATUS_OPTIONS = [
  { value: "all", label: "Semua" },
  { value: "draft", label: "Draft" },
  { value: "ready", label: "Siap" },
  { value: "cancelled", label: "Dibatalkan" },
];

type DeletePending = { productId: string; draftId: string; name: string };

export function DraftTab({
  tabBar,
  actionButton,
}: {
  tabBar?: React.ReactNode;
  actionButton?: React.ReactNode;
}) {
  const [searchInput, setSearchInput] = React.useState("");
  const [search, setSearch] = React.useState("");
  const [status, setStatus] = React.useState("all");
  const [pagination, setPagination] = React.useState<PaginationState>({
    pageIndex: 0,
    pageSize: 20,
  });
  const [deletePending, setDeletePending] =
    React.useState<DeletePending | null>(null);

  React.useEffect(() => {
    const t = setTimeout(() => {
      setSearch(searchInput);
      setPagination((p) => ({ ...p, pageIndex: 0 }));
    }, 350);
    return () => clearTimeout(t);
  }, [searchInput]);

  const { data, isLoading } = useChannelDrafts({
    search: search || undefined,
    status: (status === "all" ? undefined : status) as DraftStatus | undefined,
    page: pagination.pageIndex + 1,
    perPage: pagination.pageSize,
  });

  const items = data?.items ?? [];
  const total = data?.meta?.total ?? 0;

  const uploadDraft = useUploadDraft();
  const deleteDraft = useDeleteDraft();

  const confirmDelete = () => {
    if (!deletePending) return;
    deleteDraft.mutate(
      { productId: deletePending.productId, draftId: deletePending.draftId },
      { onSuccess: () => setDeletePending(null) },
    );
  };

  const columns = React.useMemo<ColumnDef<DraftRow>[]>(
    () => [
      {
        accessorKey: "itemGroupName",
        header: "Produk",
        cell: ({ row }) => {
          const d = row.original;
          return (
            <div className="flex items-center gap-3">
              <div className="flex size-10 shrink-0 items-center justify-center overflow-hidden rounded-lg border border-border bg-muted/40">
                {d.thumbnail ? (
                  <img
                    src={d.thumbnail}
                    alt={d.itemGroupName ?? ""}
                    className="size-full object-cover"
                  />
                ) : (
                  <ImageIcon className="size-4 text-muted-foreground" />
                )}
              </div>
              <div className="min-w-0">
                <div className="truncate font-medium">
                  {d.itemGroupName ?? "—"}
                </div>
                {d.storeName && (
                  <div className="truncate text-xs text-muted-foreground">
                    {d.storeName}
                  </div>
                )}
              </div>
            </div>
          );
        },
      },
      {
        id: "store",
        header: "Store",
        enableSorting: false,
        cell: ({ row }) => {
          const d = row.original;
          return (
            <div className="flex items-center gap-2">
              <ChannelLogo
                code={(d.channelCode ?? "") as ChannelCode}
                name={d.channelName ?? "—"}
                className="size-7 rounded-lg"
              />
              <div className="min-w-0">
                <div className="truncate text-sm font-medium">
                  {d.channelName ?? "—"}
                </div>
                {d.storeName && (
                  <div className="truncate text-xs text-muted-foreground">
                    {d.storeName}
                  </div>
                )}
              </div>
            </div>
          );
        },
      },
      {
        accessorKey: "status",
        header: "Status",
        cell: ({ row }) => <SyncStatusBadge status={row.original.status} />,
      },
      {
        id: "actions",
        header: () => <div className="text-right">Aksi</div>,
        enableSorting: false,
        cell: ({ row }) => {
          const d = row.original;
          return (
            <div className="flex items-center justify-end gap-1">
              <Button
                variant="outline"
                size="sm"
                disabled={!d.canUpload || uploadDraft.isPending}
                onClick={() => uploadDraft.mutate(d.id)}
              >
                <UploadIcon className="size-3.5" />
                Upload
              </Button>
              <Button
                variant="ghost"
                size="icon"
                className="size-8 text-destructive hover:bg-destructive/10 hover:text-destructive"
                aria-label="Hapus draft"
                onClick={() =>
                  setDeletePending({
                    productId: d.itemGroupId,
                    draftId: d.id,
                    name: d.itemGroupName ?? "draft ini",
                  })
                }
              >
                <Trash2Icon className="size-4" />
              </Button>
            </div>
          );
        },
        size: 48,
      },
    ],
    [uploadDraft],
  );

  const hasFilter = !!searchInput || status !== "all";
  const onReset = () => {
    setSearchInput("");
    setSearch("");
    setStatus("all");
    setPagination((p) => ({ ...p, pageIndex: 0 }));
  };

  return (
    <>
      <LiquidGlass
        radius={24}
        intensity="default"
        className="bg-white/40 dark:bg-white/[0.06]"
      >
        <div className="flex flex-wrap items-center justify-between gap-3 border-b border-border/60 px-4 pt-3 sm:px-5">
          <div className="overflow-x-auto">{tabBar}</div>
          <div className="flex items-center gap-3 pb-2">
            {actionButton}
            <span className="text-sm text-muted-foreground">
              Total{" "}
              <span className="font-medium text-foreground tabular-nums">
                {total}
              </span>
            </span>
          </div>
        </div>
        <FilterToolbar
          search={searchInput}
          onSearchChange={setSearchInput}
          searchPlaceholder="Cari produk…"
          onReset={hasFilter ? onReset : undefined}
          hasFilter={hasFilter}
          activeCount={[status !== "all"].filter(Boolean).length}
        >
          <Select
            value={status}
            onValueChange={(v) => {
              setStatus(v);
              setPagination((p) => ({ ...p, pageIndex: 0 }));
            }}
          >
            <SelectTrigger className="h-9 w-auto min-w-[140px] rounded-full bg-background">
              <SelectValue placeholder="Semua status" />
            </SelectTrigger>
            <SelectContent>
              {STATUS_OPTIONS.map((o) => (
                <SelectItem key={o.value} value={o.value}>
                  {o.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </FilterToolbar>
        <div className="px-5 py-5 sm:px-6">
          <DataTable
            columns={columns}
            data={items}
            getRowId={(d) => d.id}
            isLoading={isLoading}
            hideToolbar
            manualPagination
            rowCount={total}
            pagination={pagination}
            onPaginationChange={setPagination}
            tableContainerClassName="border-0 bg-transparent backdrop-blur-none [&_[data-slot=table-header]]:bg-transparent"
            emptyState={
              <span className="text-muted-foreground">
                Belum ada draft upload
              </span>
            }
          />
        </div>
      </LiquidGlass>

      <Dialog
        open={!!deletePending}
        onOpenChange={(o) => {
          if (!o && !deleteDraft.isPending) setDeletePending(null);
        }}
      >
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Hapus draft?</DialogTitle>
            <DialogDescription>
              Draft untuk{" "}
              <span className="font-medium text-foreground">
                {deletePending?.name}
              </span>{" "}
              akan dihapus permanen.
            </DialogDescription>
          </DialogHeader>
          <DialogFooter>
            <DialogClose asChild>
              <Button variant="outline" disabled={deleteDraft.isPending}>
                Batal
              </Button>
            </DialogClose>
            <Button
              variant="destructive"
              onClick={confirmDelete}
              disabled={deleteDraft.isPending}
            >
              {deleteDraft.isPending ? (
                <Loader2Icon className="animate-spin motion-reduce:animate-none" />
              ) : (
                <Trash2Icon />
              )}
              Hapus
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

"use client";

