import { formatDateTime } from "@/lib/format";
import type { ColumnDef, PaginationState } from "@tanstack/react-table";
import {
  CheckCircle2Icon,
  ExternalLinkIcon,
  ImageIcon,
  InfoIcon,
  RotateCcwIcon,
} from "lucide-react";

import { format, parseISO } from "date-fns";

import { Button } from "@/components/ui/button";
import { Combobox } from "@/components/ui/combobox";
import { DatePicker } from "@/components/ui/date-picker";
import { Checkbox } from "@/components/ui/checkbox";
import { LiquidGlass } from "@/components/ui/liquid-glass";
import { DataTable } from "@/components/ui/data-table";
import { EmptyState } from "@/components/ui/empty-state";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  useBulkDeleteHistories,
  useReuploadHistory,
  useUploadHistories,
} from "@/hooks/master-produk/use-upload";
import { useConnectedStores } from "@/hooks/channel/use-connected-stores";
import type { HistoryRow } from "@/hooks/master-produk/use-upload";
import type { ChannelCode } from "@/types/channel";
import { ChannelLogo } from "@/components/dashboard/integrasi-channel/channel-logo";
import { FilterToolbar } from "../filter-toolbar";

const STATUS_OPTIONS = [
  { value: "all", label: "Semua" },
  { value: "success", label: "Berhasil" },
  { value: "failed", label: "Gagal" },
  { value: "pending", label: "Diproses" },
];

function HistoryStatus({ row }: { row: HistoryRow }) {
  if (row.success) {
    return (
      <span
        className="inline-flex items-center gap-1 rounded px-1.5 py-0.5 text-2xs font-medium text-success bg-success/10"
        title={row.statusMessage ?? undefined}
      >
        <CheckCircle2Icon className="size-3.5" />
        Sukses
      </span>
    );
  }
  return (
    <div className="flex flex-col items-start gap-1">
      <span
        className={
          "rounded px-1.5 py-0.5 text-2xs font-medium " +
          (row.canReupload
            ? "bg-destructive/10 text-destructive"
            : "bg-warning/10 text-warning")
        }
      >
        {row.canReupload ? "Gagal" : "Diproses"}
      </span>
      {row.statusMessage && (
        <span
          className="line-clamp-2 max-w-[18rem] break-words text-2xs leading-snug text-destructive/90"
          title={row.statusMessage}
        >
          {row.statusMessage}
        </span>
      )}
    </div>
  );
}

export function HasilTab({
  tabBar,
  actionButton,
}: {
  tabBar?: React.ReactNode;
  actionButton?: React.ReactNode;
}) {
  const [searchInput, setSearchInput] = React.useState("");
  const [search, setSearch] = React.useState("");
  const [shopId, setShopId] = React.useState<string | null>(null);
  const [status, setStatus] = React.useState("all");
  const [dateFrom, setDateFrom] = React.useState("");
  const [dateTo, setDateTo] = React.useState("");
  const [pagination, setPagination] = React.useState<PaginationState>({
    pageIndex: 0,
    pageSize: 20,
  });

  React.useEffect(() => {
    const t = setTimeout(() => {
      setSearch(searchInput);
      setPagination((p) => ({ ...p, pageIndex: 0 }));
    }, 350);
    return () => clearTimeout(t);
  }, [searchInput]);

  const resetPage = () => setPagination((p) => ({ ...p, pageIndex: 0 }));

  const { data: stores = [] } = useConnectedStores();
  const storeOptions = React.useMemo(
    () =>
      stores.map((s) => ({
        value: s.shop_id,
        label: s.shop_name,
        hint: s.channel?.name ?? undefined,
      })),
    [stores],
  );

  const { data, isLoading } = useUploadHistories({
    search: search || undefined,
    status: status === "all" ? undefined : status,
    shopId: shopId || undefined,
    dateFrom: dateFrom || undefined,
    dateTo: dateTo || undefined,
    page: pagination.pageIndex + 1,
    perPage: pagination.pageSize,
  });

  const items = data?.items ?? [];
  const total = data?.meta?.total ?? 0;

  const reupload = useReuploadHistory();
  const bulkDelete = useBulkDeleteHistories();

  const hasFilter =
    !!search || status !== "all" || !!shopId || !!dateFrom || !!dateTo;

  const onReset = () => {
    setSearchInput("");
    setSearch("");
    setShopId(null);
    setStatus("all");
    setDateFrom("");
    setDateTo("");
    resetPage();
  };

  const columns = React.useMemo<ColumnDef<HistoryRow>[]>(
    () => [
      {
        id: "select",
        header: ({ table }) => (
          <Checkbox
            checked={
              table.getIsAllPageRowsSelected() ||
              (table.getIsSomePageRowsSelected() && "indeterminate")
            }
            onCheckedChange={(value) =>
              table.toggleAllPageRowsSelected(!!value)
            }
            aria-label="Pilih semua"
          />
        ),
        cell: ({ row }) => (
          <Checkbox
            checked={row.getIsSelected()}
            onCheckedChange={(value) => row.toggleSelected(!!value)}
            aria-label="Pilih baris"
          />
        ),
        enableSorting: false,
        enableHiding: false,
        size: 36,
      },
      {
        accessorKey: "itemGroupName",
        header: "Produk",
        cell: ({ row }) => {
          const h = row.original;
          return (
            <div className="flex items-center gap-3">
              <div className="flex size-10 shrink-0 items-center justify-center overflow-hidden rounded-xl border border-border bg-muted/40">
                {h.thumbnail ? (
                  <img
                    src={h.thumbnail}
                    alt={h.itemGroupName ?? ""}
                    className="size-full object-cover"
                  />
                ) : (
                  <ImageIcon className="size-4 text-muted-foreground" />
                )}
              </div>
              <div className="min-w-0 truncate font-medium">
                {h.itemGroupName ?? "—"}
              </div>
            </div>
          );
        },
      },
      {
        id: "store",
        header: "Store",
        enableSorting: false,
        cell: ({ row }) => {
          const h = row.original;
          return (
            <div className="flex items-center gap-2">
              <ChannelLogo
                code={(h.channelCode ?? "") as ChannelCode}
                name={h.channelName ?? "—"}
                className="size-7 rounded-xl"
              />
              <div className="min-w-0">
                <div className="truncate text-sm font-medium">
                  {h.channelName ?? "—"}
                </div>
                {h.storeName && (
                  <div className="truncate text-xs text-muted-foreground">
                    {h.storeName}
                  </div>
                )}
              </div>
            </div>
          );
        },
      },
      {
        accessorKey: "uploadDate",
        header: "Tgl. Upload",
        cell: ({ row }) => (
          <span className="whitespace-nowrap tabular-nums text-sm text-muted-foreground">
            {formatDateTime(row.original.uploadDate)}
          </span>
        ),
      },
      {
        accessorKey: "success",
        header: "Status",
        cell: ({ row }) => <HistoryStatus row={row.original} />,
      },
      {
        id: "actions",
        header: () => <div className="text-right">Tindakan</div>,
        enableSorting: false,
        cell: ({ row }) => {
          const h = row.original;
          return (
            <div className="flex items-center justify-end gap-1">
              {h.channelUrl && (
                <Button variant="ghost" size="icon" className="size-8" asChild>
                  <a
                    href={h.channelUrl}
                    target="_blank"
                    rel="noopener noreferrer"
                    title="Buka di channel"
                  >
                    <ExternalLinkIcon className="size-4" />
                  </a>
                </Button>
              )}
              <Button
                variant="outline"
                size="sm"
                disabled={!h.canReupload || reupload.isPending}
                onClick={() => reupload.mutate(h.id)}
              >
                <RotateCcwIcon className="size-3.5" />
                Re-upload
              </Button>
            </div>
          );
        },
        size: 48,
      },
    ],
    [reupload],
  );

  return (
    <div className="flex flex-col gap-4">
      <div className="flex items-start gap-2 rounded-2xl border border-border/60 bg-muted/40 px-4 py-3 text-sm text-muted-foreground">
        <InfoIcon className="mt-0.5 size-4 shrink-0" />
        <p>
          Produk yang berhasil di-upload ke channel lebih dari 30 hari akan
          otomatis terhapus dari halaman ini.
        </p>
      </div>

      <LiquidGlass
        radius={24}
        intensity="default"
        className="bg-white/40 dark:bg-white/[0.06]"
      >
        <div className="flex flex-wrap items-center justify-between gap-3 border-b border-border/60 px-4 pt-3 sm:px-5">
          <div className="overflow-x-auto">{tabBar}</div>
          <div className="flex items-center gap-3 pb-2">
            {actionButton}
            <span className="text-sm text-muted-foreground">
              Total{" "}
              <span className="font-medium text-foreground tabular-nums">
                {total}
              </span>
            </span>
          </div>
        </div>
        <FilterToolbar
          search={searchInput}
          onSearchChange={setSearchInput}
          searchPlaceholder="Cari produk…"
          onReset={hasFilter ? onReset : undefined}
          hasFilter={hasFilter}
          activeCount={
            [
              shopId !== null,
              status !== "all",
              dateFrom !== "",
              dateTo !== "",
            ].filter(Boolean).length
          }
        >
          <Combobox
            options={storeOptions}
            value={shopId}
            onChange={(v) => {
              setShopId(v);
              resetPage();
            }}
            placeholder="Pilih toko"
            searchPlaceholder="Cari toko"
            className="h-9 bg-background"
          />
          <Select
            value={status}
            onValueChange={(v) => {
              setStatus(v);
              resetPage();
            }}
          >
            <SelectTrigger className="h-9 w-auto min-w-[140px] rounded-full bg-background">
              <SelectValue placeholder="Semua status" />
            </SelectTrigger>
            <SelectContent>
              {STATUS_OPTIONS.map((o) => (
                <SelectItem key={o.value} value={o.value}>
                  {o.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <DatePicker
            value={dateFrom ? parseISO(dateFrom) : undefined}
            onChange={(d) => {
              setDateFrom(d ? format(d, "yyyy-MM-dd") : "");
              resetPage();
            }}
            placeholder="Dari tanggal"
            className="bg-background"
          />
          <DatePicker
            value={dateTo ? parseISO(dateTo) : undefined}
            onChange={(d) => {
              setDateTo(d ? format(d, "yyyy-MM-dd") : "");
              resetPage();
            }}
            placeholder="Sampai tanggal"
            className="bg-background"
          />
        </FilterToolbar>
        <div className="px-5 py-5 sm:px-6">
          <DataTable
            columns={columns}
            data={items}
            getRowId={(h) => h.id}
            isLoading={isLoading}
            hideToolbar
            manualPagination
            rowCount={total}
            pagination={pagination}
            onPaginationChange={setPagination}
            enableRowSelection
            tableContainerClassName="border-0 bg-transparent backdrop-blur-none [&_[data-slot=table-header]]:bg-transparent"
            bulkActions={(selected, table) => (
              <Button
                variant="destructive"
                size="sm"
                disabled={bulkDelete.isPending}
                onClick={() =>
                  bulkDelete.mutate(
                    selected.map((h) => h.id),
                    { onSuccess: () => table.resetRowSelection() },
                  )
                }
              >
                Hapus
              </Button>
            )}
            emptyState={<EmptyState title="Belum ada riwayat upload" />}
          />
        </div>
      </LiquidGlass>
    </div>
  );
}

"use client";

import * as React from "react";
import { useRouter } from "next/navigation";
import { ImageIcon, Loader2Icon, SearchIcon, SearchXIcon } from "lucide-react";

import { cn } from "@/lib/utils";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { useMasterProducts } from "@/hooks/master-produk/use-master-products";
import type { Product } from "@/types/master-produk";

export function ProductPickerDialog({
  open,
  onOpenChange,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
}) {
  const router = useRouter();
  const [searchInput, setSearchInput] = React.useState("");
  const [search, setSearch] = React.useState("");

  React.useEffect(() => {
    const t = setTimeout(() => setSearch(searchInput), 350);
    return () => clearTimeout(t);
  }, [searchInput]);

  const handleOpenChange = (next: boolean) => {
    if (!next) {
      setSearchInput("");
      setSearch("");
    }
    onOpenChange(next);
  };

  const { data, isLoading } = useMasterProducts({
    search: search || undefined,
    perPage: 20,
  });
  const items = data?.items ?? [];

  const onPick = (product: Product) => {
    router.push(`/dashboard/produk/${product.itemGroupId}/upload-to-channel`);
    handleOpenChange(false);
  };

  return (
    <Dialog open={open} onOpenChange={handleOpenChange}>
      <DialogContent className="max-w-lg">
        <DialogHeader>
          <DialogTitle>Pilih produk</DialogTitle>
          <DialogDescription>
            Pilih produk master untuk diupload ke channel.
          </DialogDescription>
        </DialogHeader>

        <div className="relative">
          <SearchIcon className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" />
          <Input
            autoFocus
            value={searchInput}
            onChange={(e) => setSearchInput(e.target.value)}
            placeholder="Cari nama / SKU…"
            className="h-9 rounded-full border-border bg-background pl-9"
          />
        </div>

        <div className="max-h-80 overflow-y-auto overscroll-contain">
          {isLoading ? (
            <div className="flex items-center justify-center gap-2 py-12 text-sm text-muted-foreground">
              <Loader2Icon className="size-4 animate-spin motion-reduce:animate-none" /></div>
          ) : items.length === 0 ? (
            <div className="flex flex-col items-center gap-2 py-12 text-center">
              <SearchXIcon className="size-7 text-muted-foreground" />
              <p className="text-sm text-muted-foreground">
                Produk tidak ditemukan
              </p>
            </div>
          ) : (
            <ul className="flex flex-col gap-1">
              {items.map((p) => (
                <li key={p.itemGroupId}>
                  <button
                    type="button"
                    onClick={() => onPick(p)}
                    className={cn(
                      "flex w-full items-center gap-3 rounded-xl px-2.5 py-2 text-left transition-colors hover:bg-muted/60",
                    )}
                  >
                    <div className="flex size-10 shrink-0 items-center justify-center overflow-hidden rounded-xl border border-border bg-muted/40">
                      {p.thumbnail ? (
                        <img
                          src={p.thumbnail}
                          alt={p.itemName}
                          className="size-full object-cover"
                        />
                      ) : (
                        <ImageIcon className="size-4 text-muted-foreground" />
                      )}
                    </div>
                    <div className="min-w-0 flex-1">
                      <div className="flex items-center gap-1.5">
                        <span className="truncate font-medium">
                          {p.itemName}
                        </span>
                        {p.isBundle && (
                          <Badge
                            variant="secondary"
                            className="px-1.5 py-0 text-2xs"
                          >
                            Bundle
                          </Badge>
                        )}
                      </div>
                      <div className="truncate font-mono text-xs text-muted-foreground">
                        {p.sku ?? "—"}
                      </div>
                    </div>
                  </button>
                </li>
              ))}
            </ul>
          )}
        </div>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import * as React from "react";
import { PackageOpenIcon } from "lucide-react";

import { formatDate } from "@/lib/format";
import { Badge } from "@/components/ui/badge";
import { EmptyState } from "@/components/ui/empty-state";
import type { ColumnDef } from "@tanstack/react-table";
import { DataTable } from "@/components/ui/data-table/data-table";
import type { MonitorAnalyticsRow } from "@/types/monitor-stok/monitor";

interface PageMeta {
  current_page: number;
  last_page: number;
  per_page: number;
  total: number;
}

export type AnalyticsKind = "tidak-laku" | "paling-laku" | "perkiraan-habis";

interface MonitorAnalyticsTableProps {
  kind: AnalyticsKind;
  rows: MonitorAnalyticsRow[];
  meta: PageMeta;
  isLoading: boolean;
  isFetching: boolean;
  emptyText?: string;
  onPageChange: (page: number) => void;
  onPerPageChange: (size: number) => void;
}

const EXTRA_COLS: Record<AnalyticsKind, string[]> = {
  "tidak-laku": ["Terjual Terakhir", "Idle (hari)"],
  "paling-laku": ["Terjual", "Rata-rata/hari"],
  "perkiraan-habis": ["Rata-rata/hari", "Estimasi Hari", "Perkiraan Habis"],
};


function Thumb({ url, alt }: { url: string | null; alt: string }) {
  return (
    <div
      className="h-9 w-9 shrink-0 rounded-xl border border-border/40 bg-muted/40 bg-cover bg-center"
      role="img"
      aria-label={alt}
      style={url ? { backgroundImage: `url(${url})` } : undefined}
    />
  );
}

export function MonitorAnalyticsTable({
  kind,
  rows,
  meta,
  isLoading,
  isFetching,
  emptyText = "Tidak ada produk pada kategori ini.",
  onPageChange,
  onPerPageChange,
}: MonitorAnalyticsTableProps) {
  const columns = React.useMemo<ColumnDef<MonitorAnalyticsRow>[]>(() => {
    const baseCols: ColumnDef<MonitorAnalyticsRow>[] = [
      {
        accessorKey: "product_name",
        header: "Produk",
        cell: ({ row }) => (
          <div className="flex items-center gap-3">
            <Thumb
              url={row.original.thumbnail}
              alt={row.original.product_name ?? row.original.sku}
            />
            <div className="min-w-0">
              <p
                className="truncate font-medium"
                title={row.original.product_name ?? ""}
              >
                {row.original.product_name ?? "—"}
              </p>
              <p className="text-xs text-muted-foreground">
                {row.original.sku}
              </p>
              {row.original.variation_values.length > 0 && (
                <div className="mt-1 flex flex-wrap gap-1">
                  {row.original.variation_values.map((v, idx) => (
                    <Badge
                      key={idx}
                      variant="secondary"
                      className="text-2xs font-normal"
                    >
                      {v.value}
                    </Badge>
                  ))}
                </div>
              )}
            </div>
          </div>
        ),
      },
      {
        accessorKey: "available",
        header: () => <div className="text-right">Tersedia</div>,
        cell: ({ row }) => (
          <div className="text-right tabular-nums font-medium">
            {row.original.available}
          </div>
        ),
      },
    ];

    if (kind === "tidak-laku") {
      baseCols.push({
        accessorKey: "last_sold",
        header: () => <div className="text-right">Terjual Terakhir</div>,
        cell: ({ row }) => (
          <div className="text-right text-muted-foreground">
            {row.original.last_sold ? (
              formatDate(row.original.last_sold)
            ) : (
              <span className="text-warning">
                Belum pernah
              </span>
            )}
          </div>
        ),
      });
      baseCols.push({
        accessorKey: "days_idle",
        header: () => <div className="text-right">Idle (hari)</div>,
        cell: ({ row }) => (
          <div className="text-right tabular-nums">
            {row.original.days_idle ?? "—"}
          </div>
        ),
      });
    } else if (kind === "paling-laku") {
      baseCols.push({
        accessorKey: "qty_sold",
        header: () => <div className="text-right">Terjual</div>,
        cell: ({ row }) => (
          <div className="text-right tabular-nums font-semibold text-success">
            {row.original.qty_sold}
          </div>
        ),
      });
      baseCols.push({
        accessorKey: "avg_per_day",
        header: () => <div className="text-right">Rata-rata/hari</div>,
        cell: ({ row }) => (
          <div className="text-right tabular-nums">
            {row.original.avg_per_day ?? "—"}
          </div>
        ),
      });
    } else {
      baseCols.push({
        accessorKey: "avg_per_day",
        header: () => <div className="text-right">Rata-rata/hari</div>,
        cell: ({ row }) => (
          <div className="text-right tabular-nums">
            {row.original.avg_per_day ?? "—"}
          </div>
        ),
      });
      baseCols.push({
        accessorKey: "days_to_out",
        header: () => <div className="text-right">Estimasi Hari</div>,
        cell: ({ row }) => (
          <div className="text-right tabular-nums font-semibold text-destructive">
            {row.original.days_to_out ?? "—"}
          </div>
        ),
      });
      baseCols.push({
        accessorKey: "estimated_date",
        header: () => <div className="text-right">Perkiraan Habis</div>,
        cell: ({ row }) => (
          <div className="text-right text-muted-foreground">
            {formatDate(row.original.estimated_date)}
          </div>
        ),
      });
    }

    return baseCols;
  }, [kind]);

  return (
    <DataTable
      columns={columns}
      data={rows}
      isLoading={isLoading}
      hideToolbar
      manualPagination
      pagination={{
        pageIndex: meta.current_page - 1,
        pageSize: meta.per_page,
      }}
      rowCount={meta.total}
      onPaginationChange={(p) => {
        onPageChange(p.pageIndex + 1);
        onPerPageChange(p.pageSize);
      }}
      tableContainerClassName="border-0 bg-transparent backdrop-blur-none [&_[data-slot=table-header]]:bg-transparent"
      emptyState={
        <EmptyState icon={PackageOpenIcon} title={emptyText} className="py-20" />
      }
    />
  );
}

