        accessorKey: "qty_to_restock",
        header: () => <div className="text-right">Perlu Restock</div>,
        cell: ({ row }) => (
          <div className="text-right tabular-nums font-semibold text-warning">
            {row.original.qty_to_restock}
          </div>
        ),
      });
    }

    return baseCols;
  }, [locationLabel, showRestock]);

  return (
    <DataTable
      columns={columns}
      data={rows}
      isLoading={isLoading}
      hideToolbar
      manualPagination
      pagination={{
        pageIndex: meta.current_page - 1,
        pageSize: meta.per_page,
      }}
      rowCount={meta.total}
      onPaginationChange={(p) => {
        onPageChange(p.pageIndex + 1);
        onPerPageChange(p.pageSize);
      }}
      tableContainerClassName="border-0 bg-transparent backdrop-blur-none [&_[data-slot=table-header]]:bg-transparent"
      emptyState={
        <EmptyState icon={PackageOpenIcon} className="py-20" title={emptyText} />
      }
    />
  );
}

"use client";

import { useState, useMemo } from "react";
import { RefreshCwIcon, CheckIcon } from "lucide-react";

import { formatDateTime } from "@/lib/format";
import { Badge } from "@/components/ui/badge";
import { Checkbox } from "@/components/ui/checkbox";
import { EmptyState } from "@/components/ui/empty-state";
import type { ColumnDef } from "@tanstack/react-table";
import { DataTable } from "@/components/ui/data-table/data-table";
import { ConfirmDialog } from "@/components/ui/confirm-dialog";
import {
  useRetrySync,
  useRetryBulkSync,
} from "@/hooks/monitor-stok/use-monitor-stok";
import type { MonitorSyncFailedRow } from "@/types/monitor-stok/monitor";

interface PageMeta {
  current_page: number;
  last_page: number;
  per_page: number;
  total: number;
}

interface MonitorSyncFailedTableProps {
  rows: MonitorSyncFailedRow[];
  meta: PageMeta;
  isLoading: boolean;
  isFetching: boolean;
  onPageChange: (page: number) => void;
  onPerPageChange: (size: number) => void;
}

function Thumb({ url, alt }: { url: string | null; alt: string }) {
  return (
    <div
      className="h-9 w-9 shrink-0 rounded-xl border border-border/40 bg-muted/40 bg-cover bg-center"
      role="img"
      aria-label={alt}
      style={url ? { backgroundImage: `url(${url})` } : undefined}
    />
  );
}

function StatusBadge({ status }: { status: string }) {
  return (
    <Badge variant="destructive" className="text-2xs font-medium">
      {status === "failed" ? "Gagal" : status}
    </Badge>
  );
}

export function MonitorSyncFailedTable({
  rows,
  meta,
  isLoading,
  isFetching,
  onPageChange,
  onPerPageChange,
}: MonitorSyncFailedTableProps) {
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [retryId, setRetryId] = useState<string | null>(null);
  const [showBulk, setShowBulk] = useState(false);

  const retry = useRetrySync();
  const retryBulk = useRetryBulkSync();

  const toggleSelect = (id: string) => {
    setSelected((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  };

  const toggleAll = () => {
    if (selected.size === rows.length) setSelected(new Set());
    else setSelected(new Set(rows.map((r) => r.id)));
  };

  const handleRetry = () => {
    if (!retryId) return;
    retry.mutate(retryId, { onSettled: () => setRetryId(null) });
  };

  const handleBulk = () => {
    retryBulk.mutate([...selected], {
      onSettled: () => {
        setShowBulk(false);
        setSelected(new Set());
      },
    });
  };

  const columns = useMemo<ColumnDef<MonitorSyncFailedRow>[]>(
    () => [
      {
        id: "select",
        header: ({ table }) => (
          <Checkbox
            checked={selected.size === rows.length && rows.length > 0}
            onCheckedChange={toggleAll}
            aria-label="Pilih semua"
          />
        ),
        cell: ({ row }) => (
          <Checkbox
            checked={selected.has(row.original.id)}
            onCheckedChange={() => toggleSelect(row.original.id)}
            aria-label={`Pilih ${row.original.product_name}`}
          />
        ),
        enableSorting: false,
        enableHiding: false,
      },
      {
        accessorKey: "product_name",
        header: "Produk",
        cell: ({ row }) => (
          <div className="flex items-center gap-3">
            <Thumb
              url={row.original.thumbnail}
              alt={row.original.product_name ?? row.original.sku ?? "—"}
            />
            <div className="min-w-0">
              <p
                className="truncate font-medium"
                title={row.original.product_name ?? ""}
              >
                {row.original.product_name ?? "—"}
              </p>
              <p className="text-xs text-muted-foreground">
                {row.original.sku ?? "—"}
              </p>
            </div>
          </div>
        ),
      },
      {
        id: "channel_shop",
        header: "Channel / Toko",
        cell: ({ row }) => (
          <div className="flex flex-col gap-0.5">
            <span className="text-xs font-medium">
              {row.original.channel_name ?? "—"}
            </span>
            <span className="text-xs text-muted-foreground">
              {row.original.shop_name ?? "—"}
            </span>
          </div>
        ),
      },
      {
        accessorKey: "sync_status",
        header: "Status",
        cell: ({ row }) => <StatusBadge status={row.original.sync_status} />,
      },
      {
        accessorKey: "error_message",
        header: "Error",
        cell: ({ row }) => (
          <div className="max-w-[200px]">
            <p
              className="truncate text-xs text-destructive"
              title={row.original.error_message ?? ""}
            >
              {row.original.error_message ?? "—"}
            </p>
          </div>
        ),
      },
      {
        accessorKey: "last_synced_at",
        header: "Terakhir Sync",
        cell: ({ row }) => (
          <div className="text-xs text-muted-foreground">
            {formatDateTime(row.original.last_synced_at)}
          </div>
        ),
      },
      {
        id: "actions",
        header: () => null,
        cell: ({ row }) => (
          <div className="flex justify-end">
            <button
              type="button"
              onClick={() => setRetryId(row.original.id)}
              disabled={retry.isPending}
              className="inline-flex items-center gap-1 rounded-md border border-border/60 px-2.5 py-1 text-xs font-medium text-foreground transition-colors hover:bg-muted disabled:opacity-50"
            >
              <RefreshCwIcon className="size-3" /> Retry
            </button>
          </div>
        ),
      },
    ],
    [rows, selected, retry.isPending],
  );

  return (
    <div className="flex flex-col gap-3">
      {selected.size > 0 && (
        <div className="flex items-center gap-3 rounded-lg bg-muted/60 px-4 py-2">
          <span className="text-sm text-muted-foreground">
            {selected.size} dipilih
          </span>
          <button
            type="button"
            onClick={() => setShowBulk(true)}
            className="inline-flex items-center gap-1.5 rounded-md bg-primary px-3 py-1.5 text-sm font-medium text-primary-foreground transition-colors hover:bg-primary/90"
          >
            <RefreshCwIcon className="size-3.5" /> Retry Semua
          </button>
          <button
            type="button"
            onClick={() => setSelected(new Set())}
            className="text-sm text-muted-foreground hover:text-foreground"
          >
            Batal
          </button>
        </div>
      )}

      <DataTable
        columns={columns}
        data={rows}
        isLoading={isLoading}
        hideToolbar
        manualPagination
        pagination={{
          pageIndex: meta.current_page - 1,
          pageSize: meta.per_page,
        }}
        rowCount={meta.total}
        onPaginationChange={(p) => {
          onPageChange(p.pageIndex + 1);
          onPerPageChange(p.pageSize);
        }}
        tableContainerClassName="border-0 bg-transparent backdrop-blur-none [&_[data-slot=table-header]]:bg-transparent"
        emptyState={
          <EmptyState
            icon={CheckIcon}
            className="py-20"
            title="Tidak ada mapping gagal sync."
          />
        }
      />

      <ConfirmDialog
        open={retryId !== null}
        onOpenChange={(o) => {
          if (!o) setRetryId(null);
        }}
        title="Retry Sinkronisasi"
        description="Mapping ini akan dijadwalkan ulang untuk sinkronisasi ke channel. Lanjutkan?"
        confirmLabel="Retry"
        onConfirm={handleRetry}
        loading={retry.isPending}
      />

      <ConfirmDialog
        open={showBulk}
        onOpenChange={setShowBulk}
        title="Retry Semua yang Dipilih"
        description={`${selected.size} mapping akan dijadwalkan ulang untuk sinkronisasi. Lanjutkan?`}
        confirmLabel="Retry Semua"
        onConfirm={handleBulk}
        loading={retryBulk.isPending}
      />
    </div>
  );
}

"use client";

import * as React from "react";
import {
  useRouter,
  useSearchParams,
  usePathname,
} from "next/navigation";
import { BellIcon, CheckCheckIcon, Loader2Icon } from "lucide-react";

import { Button } from "@/components/ui/button";
import { EmptyState } from "@/components/ui/empty-state";
import { LiquidGlass } from "@/components/ui/liquid-glass";
import { SimplePagination } from "@/components/ui/simple-pagination";
import { Skeleton } from "@/components/ui/skeleton";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { PageTitle } from "@/components/dashboard/page-title";
import { NotifikasiItem } from "@/components/dashboard/notifikasi/notifikasi-item";
import {
  useMarkAllNotificationsRead,
  useNotifications,
  useUnreadNotificationCount,
} from "@/hooks/notification/use-notifications";
import {
  DOMAIN_LABEL,
  getNotificationMeta,
  listDomains,
  type NotificationDomain,
} from "@/lib/notification";

type TabKey = "all" | "unread";
type DomainKey = NotificationDomain | "all";

const PAGE_SIZE_OPTIONS = [10, 20, 50];
const DEFAULT_PAGE_SIZE = 20;

function ItemSkeleton() {
  return (
    <div className="flex items-start gap-3 rounded-xl px-3 py-3">
      <Skeleton className="size-9 rounded-xl" />
      <div className="flex-1 space-y-2">
        <Skeleton className="h-4 w-3/5" />
        <Skeleton className="h-3 w-4/5" />
        <Skeleton className="h-3 w-24" />
      </div>
    </div>
  );
}

function parseTab(v: string | null): TabKey {
  return v === "unread" ? "unread" : "all";
}

function parseDomain(v: string | null): DomainKey {
  if (!v) return "all";
  const domains = listDomains();
  return (domains as string[]).includes(v) ? (v as DomainKey) : "all";
}

function parsePositive(v: string | null, fallback: number): number {
  const n = Number(v);
  return Number.isFinite(n) && n > 0 ? Math.floor(n) : fallback;
}

export function NotifikasiView() {
  const router = useRouter();
  const pathname = usePathname();
  const searchParams = useSearchParams();

  const tab = parseTab(searchParams.get("tab"));
  const domain = parseDomain(searchParams.get("domain"));
  const page = parsePositive(searchParams.get("page"), 1);
  const perPage = parsePositive(
    searchParams.get("per_page"),
    DEFAULT_PAGE_SIZE,
  );

  const setParams = React.useCallback(
    (next: Partial<Record<string, string | number | undefined>>) => {
      const params = new URLSearchParams(searchParams.toString());
      Object.entries(next).forEach(([k, v]) => {
        if (v === undefined || v === "" || v === "all") {
          params.delete(k);
        } else {
          params.set(k, String(v));
        }
      });
      const qs = params.toString();
      router.replace(qs ? `${pathname}?${qs}` : pathname, { scroll: false });
    },
    [router, pathname, searchParams],
  );

  const setTab = (v: TabKey) => setParams({ tab: v, page: undefined });
  const setDomain = (v: DomainKey) =>
    setParams({ domain: v, page: undefined });
  const setPage = (v: number) => setParams({ page: v });
  const setPerPage = (v: number) =>
    setParams({ per_page: v, page: undefined });

  const { data: unreadCount = 0 } = useUnreadNotificationCount();
  const { data, isLoading, isFetching } = useNotifications({
    per_page: perPage,
    page,
    ...(tab === "unread" ? { is_read: false } : {}),
  });
  const markAll = useMarkAllNotificationsRead();

  const rawItems = data?.items ?? [];
  const meta = data?.meta;
  const total = meta?.total ?? 0;
  const lastPage = meta?.last_page ?? 0;

  const items = React.useMemo(() => {
    if (domain === "all") return rawItems;
    return rawItems.filter(
      (n) => getNotificationMeta(n.type).domain === domain,
    );
  }, [rawItems, domain]);

  const disableMarkAll = markAll.isPending || unreadCount === 0;

  return (
    <div className="space-y-4">
      <PageTitle
        title="Notifikasi"
        description="Pemberitahuan aktivitas dari sistem."
      />

      <Tabs
        value={tab}
        onValueChange={(v) => setTab(v as TabKey)}
        className="flex-none"
      >
        <div className="flex flex-wrap items-center justify-between gap-3">
          <TabsList variant="glass">
            <TabsTrigger value="all">Semua</TabsTrigger>
            <TabsTrigger value="unread">
              Belum dibaca
              {unreadCount > 0 && (
                <span className="ml-1.5 rounded-full bg-primary/10 px-1.5 text-2xs font-semibold text-primary">
                  {unreadCount > 99 ? "99+" : unreadCount}
                </span>
              )}
            </TabsTrigger>
          </TabsList>

          <Button
            type="button"
            variant="ghost"
            size="sm"
            className="rounded-full"
            onClick={() => markAll.mutate()}
            disabled={disableMarkAll}
          >
            {markAll.isPending ? (
              <Loader2Icon className="animate-spin" />
            ) : (
              <CheckCheckIcon />
            )}
            Tandai semua dibaca
          </Button>
        </div>
      </Tabs>

      <LiquidGlass
        radius={24}
        intensity="default"
        className="bg-white/40 dark:bg-white/[0.06]"
      >
        <div className="flex flex-col gap-4 p-4 sm:p-5">
          <Tabs
            value={domain}
            onValueChange={(v) => setDomain(v as DomainKey)}
            className="border-b border-border/60"
          >
            <TabsList variant="line" className="-mb-px overflow-x-auto">
              <TabsTrigger value="all">Semua domain</TabsTrigger>
              {listDomains().map((d) => (
                <TabsTrigger key={d} value={d}>
                  {DOMAIN_LABEL[d]}
                </TabsTrigger>
              ))}
            </TabsList>
          </Tabs>

          <div className="min-h-64">
            {isLoading ? (
              <div className="divide-y divide-border/60">
                {Array.from({ length: 5 }).map((_, i) => (
                  <ItemSkeleton key={i} />
                ))}
              </div>
            ) : items.length === 0 ? (
              <EmptyState
                icon={BellIcon}
                title={
                  tab === "unread"
                    ? "Semua notifikasi sudah dibaca"
                    : domain === "all"
                      ? "Belum ada notifikasi"
                      : `Belum ada notifikasi ${DOMAIN_LABEL[domain as NotificationDomain].toLowerCase()}`
                }
                description={
                  tab === "unread"
                    ? "Notifikasi baru akan muncul di sini."
                    : "Pemberitahuan aktivitas akan muncul di sini."
                }
              />
            ) : (
              <ul className="divide-y divide-border/60">
                {items.map((n) => (
                  <li key={n.id}>
                    <NotifikasiItem notification={n} />
                  </li>
                ))}
              </ul>
            )}
          </div>

          {(items.length > 0 || (meta && lastPage > 0)) && (
            <SimplePagination
              page={page}
              lastPage={lastPage}
              onPageChange={setPage}
              perPage={perPage}
              onPerPageChange={setPerPage}
              pageSizeOptions={PAGE_SIZE_OPTIONS}
              isFetching={isFetching}
              total={total}
              label="notifikasi"
            />
          )}
        </div>
      </LiquidGlass>
    </div>
  );
}

