"use client";

import { useState } from "react";
import { Download, Loader2 } from "lucide-react";

import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { OrderService } from "@/services/pesanan/order.service";

export function ExportCancelDialog() {
  const [open, setOpen] = useState(false);
  const [dateFrom, setDateFrom] = useState("");
  const [dateTo, setDateTo] = useState("");
  const [postPackOnly, setPostPackOnly] = useState(true);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const onSubmit = async () => {
    setLoading(true);
    setError(null);
    try {
      await OrderService.exportCancelled({
        date_from: dateFrom || undefined,
        date_to: dateTo || undefined,
        post_pack_only: postPackOnly,
      });
      setOpen(false);
    } catch (e) {
      setError(
        e instanceof Error ? e.message : "Gagal mengunduh data pesanan cancel.",
      );
    } finally {
      setLoading(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <Button variant="outline" size="sm" className="gap-2">
          <Download className="size-4" />
          Unduh Data Cancel
        </Button>
      </DialogTrigger>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>Unduh Data Pesanan Cancel</DialogTitle>
          <DialogDescription>
            Rekap pesanan batal per tanggal untuk mencocokkan paket fisik.
            Kosongkan tanggal untuk mengambil semua data.
          </DialogDescription>
        </DialogHeader>

        <div className="grid gap-4 py-2">
          <div className="grid grid-cols-2 gap-3">
            <div className="grid gap-1.5">
              <label htmlFor="date-from" className="text-sm font-medium">
                Dari tanggal
              </label>
              <Input
                id="date-from"
                type="date"
                value={dateFrom}
                onChange={(e) => setDateFrom(e.target.value)}
              />
            </div>
            <div className="grid gap-1.5">
              <label htmlFor="date-to" className="text-sm font-medium">
                Sampai tanggal
              </label>
              <Input
                id="date-to"
                type="date"
                value={dateTo}
                onChange={(e) => setDateTo(e.target.value)}
              />
            </div>
          </div>

          <label className="flex items-center gap-2 text-sm">
            <Checkbox
              checked={postPackOnly}
              onCheckedChange={(v) => setPostPackOnly(v === true)}
            />
            <span>Hanya pesanan yang batal setelah packing</span>
          </label>

          {error && (
            <p className="text-sm text-destructive" role="alert">
              {error}
            </p>
          )}
        </div>

        <DialogFooter>
          <Button
            variant="ghost"
            onClick={() => setOpen(false)}
            disabled={loading}
          >
            Batal
          </Button>
          <Button onClick={onSubmit} disabled={loading} className="gap-2">
            {loading && <Loader2 className="size-4 animate-spin" />}
            Unduh XLSX
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useState } from "react";
import { format } from "date-fns";
import { Download, Loader2 } from "lucide-react";

import { Button } from "@/components/ui/button";
import { DatePicker } from "@/components/ui/date-picker";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { OrderService } from "@/services/pesanan/order.service";
import type { OrderTab } from "@/types/pesanan/order";

interface Props {
  tab?: OrderTab;
}

export function ExportOrdersDialog({ tab }: Props) {
  const [open, setOpen] = useState(false);
  const [dateFrom, setDateFrom] = useState<Date | undefined>();
  const [dateTo, setDateTo] = useState<Date | undefined>();
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const onSubmit = async () => {
    setLoading(true);
    setError(null);
    try {
      await OrderService.exportOrders({
        tab: tab && tab !== "all" ? tab : undefined,
        date_from: dateFrom ? format(dateFrom, "yyyy-MM-dd") : undefined,
        date_to: dateTo ? format(dateTo, "yyyy-MM-dd") : undefined,
      });
      setOpen(false);
    } catch (e) {
      setError(
        e instanceof Error ? e.message : "Gagal mengunduh data pesanan.",
      );
    } finally {
      setLoading(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <Button variant="outline" size="sm" className="gap-2">
          <Download className="size-4" />
          Export
        </Button>
      </DialogTrigger>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>Export Pesanan</DialogTitle>
          <DialogDescription>
            Unduh data pesanan ke file Excel. Kosongkan tanggal untuk mengambil
            semua data.
          </DialogDescription>
        </DialogHeader>

        <div className="grid gap-4 py-2">
          <div className="grid grid-cols-2 gap-3">
            <div className="grid gap-1.5">
              <label className="text-sm font-medium">Dari tanggal</label>
              <DatePicker
                value={dateFrom}
                onChange={setDateFrom}
                placeholder="Pilih tanggal"
              />
            </div>
            <div className="grid gap-1.5">
              <label className="text-sm font-medium">Sampai tanggal</label>
              <DatePicker
                value={dateTo}
                onChange={setDateTo}
                placeholder="Pilih tanggal"
              />
            </div>
          </div>

          {error && (
            <p className="text-sm text-destructive" role="alert">
              {error}
            </p>
          )}
        </div>

        <DialogFooter>
          <Button
            variant="ghost"
            onClick={() => setOpen(false)}
            disabled={loading}
          >
            Batal
          </Button>
          <Button onClick={onSubmit} disabled={loading} className="gap-2">
            {loading && <Loader2 className="size-4 animate-spin" />}
            Unduh XLSX
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

