          </div>
        }
      />

      <StatusStepper status={order.status} history={order.status_history} />

      {order.is_canceled && order.cancel_reason && (
        <LiquidGlass
          radius={16}
          intensity="subtle"
          className="border-destructive/20 bg-destructive/[0.06] px-5 py-3"
