            </LiquidGlass>

            {}
            <LiquidGlass
              radius={16}
              intensity="subtle"
              className="bg-white/30 dark:bg-white/[0.04] p-5"
            >
              <SectionTitle className="mb-4">Pengiriman</SectionTitle>
              <div className="space-y-3">
                <InfoRow icon={TruckIcon} label="Kurir">
                  <span>{order.shipping?.provider || "—"}</span>
                </InfoRow>
                {order.shipping?.tracking_number && (
                  <InfoRow icon={PackageIcon} label="No. Resi">
                    <CopyableText
                      text={order.shipping.tracking_number}
                      label="Salin No. Resi"
                      mono
                    />
                  </InfoRow>
                )}
                {order.received_date && (
                  <InfoRow icon={CalendarIcon} label="Diterima">
                    <span>{formatDateLong(order.received_date)}</span>
                  </InfoRow>
                )}
              </div>
            </LiquidGlass>
          </div>

          <CourierPickupCard
            order={order}
            onEdit={() => setPickupOpen(true)}
          />
        </div>

        {}
        <div className="flex flex-col gap-4">
          {}
          <LiquidGlass
            radius={16}
            intensity="subtle"
            className="bg-white/30 dark:bg-white/[0.04] p-5 sticky top-4"
          >
            <FinancialSummary order={order} />

            {}
            <div className="mt-4 border-t border-border/40 pt-4">
              <div className="flex items-center justify-between">
                <span className="text-sm text-muted-foreground">
                  Status Bayar
                </span>
                <StatusBadge 
                  domain="order-payment" 
                  status={order.is_paid ? "PAID" : "UNPAID"} 
                />
              </div>
              {order.is_paid && order.payment_method_name && (
                <p className="mt-1.5 text-xs text-muted-foreground">
                  via {order.payment_method_name}
                  {order.paid_time && ` - ${formatDateTime(order.paid_time)}`}
                </p>
              )}
            </div>
          </LiquidGlass>

          {}
          {(order.buyer_message || order.seller_note) && (
            <LiquidGlass
              radius={16}
              intensity="subtle"
              className="bg-white/30 dark:bg-white/[0.04] p-5"
            >
              <SectionTitle className="mb-3">Catatan</SectionTitle>
              <div className="space-y-3">
                {order.buyer_message && (
                  <div>
                    <p className="text-2xs font-medium uppercase tracking-wider text-muted-foreground/70 mb-1">
                      Pesan Pembeli
                    </p>
                    <p className="text-sm leading-relaxed rounded-lg bg-muted/40 px-3 py-2">
                      {order.buyer_message}
                    </p>
                  </div>
                )}
                {order.seller_note && (
                  <div>
                    <p className="text-2xs font-medium uppercase tracking-wider text-muted-foreground/70 mb-1">
                      Catatan Penjual
                    </p>
                    <p className="text-sm leading-relaxed rounded-lg bg-muted/40 px-3 py-2">
                      {order.seller_note}
                    </p>
                  </div>
                )}
              </div>
            </LiquidGlass>
          )}

          {}
          <LiquidGlass
            radius={16}
            intensity="subtle"
            className="bg-white/30 dark:bg-white/[0.04] px-5 py-4"
          >
            <div className="space-y-1 text-xs text-muted-foreground">
              <p>
                Dibuat: {formatDateTime(order.created_at)}
              </p>
              <p>
                Diperbarui: {formatDateTime(order.updated_at)}
              </p>
            </div>
          </LiquidGlass>
        </div>
      </div>

      <ContactBuyerDialog
        open={contactOpen}
        onOpenChange={setContactOpen}
        orderId={order.id}
        orderNo={order.salesorder_no}
        defaultChannel={order.contact_channel ?? undefined}
        defaultDecision={order.customer_decision ?? undefined}
        defaultNote={order.contact_note ?? undefined}
      />

      <CourierPickupDialog
        open={pickupOpen}
        onOpenChange={setPickupOpen}
        orderId={order.id}
        orderNo={order.salesorder_no}
        pickup={order.courier_pickup}
      />

      {editingItem && (
        <EditOrderItemDialog
          open={!!editingItem}
          onOpenChange={(o) => !o && setEditingItem(null)}
          orderId={order.id}
          item={editingItem}
        />
      )}

      <ConfirmDialog
        open={!!deletingItemId}
        onOpenChange={(o) => !o && setDeletingItemId(null)}
        title="Hapus item pesanan?"
        description="Perubahan hanya berlaku di sistem internal, tidak dikirim ke marketplace."
        confirmLabel="Ya, Hapus"
        variant="destructive"
        loading={deleteItem.isPending}
        onConfirm={() => {
          if (!deletingItemId) return;
          deleteItem.mutate(
            { orderId: order.id, itemId: deletingItemId },
            { onSuccess: () => setDeletingItemId(null) },
          );
        }}
      />
    </div>
  );
}

function ContactSummary({
  order,
  onEdit,
}: {
  order: Order;
  onEdit: () => void;
}) {
  return (
    <LiquidGlass
      radius={16}
      intensity="subtle"
      className="bg-white/30 dark:bg-white/[0.04] p-5"
    >
      <div className="flex items-start justify-between gap-3">
        <div className="flex-1">
          <SectionTitle>Kontak & Keputusan Pembeli</SectionTitle>
          <p className="text-xs text-muted-foreground mt-0.5">
            Catatan komunikasi dengan pembeli untuk pesanan stok kosong.
          </p>
        </div>
        <Button
          variant="outline"
          size="sm"
          className="gap-1.5"
          onClick={onEdit}
        >
          <MessageCircleIcon className="size-3.5" />
          Ubah
        </Button>
      </div>

      <div className="mt-4 grid gap-4 sm:grid-cols-2">
        <InfoRow icon={CheckIcon} label="Status">
          {order.contacted_at ? (
            <span className="inline-flex items-center gap-1.5">
              <span className="inline-block size-2 rounded-full bg-success" />
              Sudah dihubungi · {formatDateTime(order.contacted_at)}
            </span>
          ) : (
            <span className="inline-flex items-center gap-1.5 text-warning">
              <ClockIcon className="size-3.5" />
              Belum dihubungi
            </span>
          )}
        </InfoRow>
        {order.contact_channel && (
          <InfoRow icon={MessageSquareIcon} label="Channel">
            {CONTACT_CHANNEL_LABELS[order.contact_channel]}
          </InfoRow>
        )}
        {order.customer_decision && (
          <InfoRow icon={UserIcon} label="Keputusan">
            {CUSTOMER_DECISION_LABELS[order.customer_decision]}
            {order.decision_at && (
              <span className="ml-1 text-muted-foreground">
                · {formatDateTime(order.decision_at)}
              </span>
            )}
          </InfoRow>
        )}
        {order.contact_note && (
          <InfoRow icon={MessageSquareIcon} label="Catatan">
            <span className="whitespace-pre-line">{order.contact_note}</span>
          </InfoRow>
        )}
      </div>
    </LiquidGlass>
  );
}

"use client";

import { useState, useMemo, useCallback } from "react";
import Link from "next/link";
import { ImportIcon, PlusIcon } from "lucide-react";

import { Button } from "@/components/ui/button";

import { Checkbox } from "@/components/ui/checkbox";
import { LiquidGlass } from "@/components/ui/liquid-glass";
import { useOrders } from "@/hooks/pesanan/use-orders";
import { useListState } from "@/hooks/use-list-state";
import { useUrlTab } from "@/hooks/use-url-tab";
import type {
  OrderTab,
  OrderListParams,
  SubFilter,
} from "@/types/pesanan/order";
import {
  SUB_PILL_CONFIG,
  TABS_WITH_ACTIONS,
  TAB_CONFIG,
} from "@/types/pesanan/order";

import { OrderStatusTabs, OrderSubStatusPills } from "./order-status-tabs";
import { OrderFilters, EMPTY_FILTERS, type FilterState } from "./order-filters";
import { OrderCardList } from "./order-card-list";
import { BulkActionBar } from "./bulk-action-bar";
import { ExportCancelDialog } from "./export-cancel-dialog";
import { ExportOrdersDialog } from "./export-orders-dialog";

const TAB_KEYS = TAB_CONFIG.map((t) => t.key as OrderTab);

export function PesananView() {
  const [tab, setTabUrl] = useUrlTab<OrderTab>("tab", "all", {
    validValues: TAB_KEYS,
    clearKeys: ["sub"],
  });
  const subKeys = useMemo(
    () => (SUB_PILL_CONFIG[tab] ?? []).map((p) => p.key),
    [tab],
  );
  const [subValue, setSubUrl] = useUrlTab("sub", "", { validValues: subKeys });
  const subFilter: SubFilter = (subValue || null) as SubFilter;

  const listSearch = useListState<{ _: string }>(
    { _: "" },
    { perPage: 12, debounceMs: 350 },
  );
  const [filters, setFilters] = useState<FilterState>(EMPTY_FILTERS);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  const clearSelection = useCallback(() => setSelectedIds(new Set()), []);

  const handleTabChange = useCallback(
    (t: OrderTab) => {
      setTabUrl(t);
      listSearch.resetPage();
      clearSelection();
    },
    [setTabUrl, listSearch, clearSelection],
  );

  const handleSubFilterChange = useCallback(
    (s: SubFilter) => {
      setSubUrl(s ?? "");
      listSearch.resetPage();
      clearSelection();
    },
    [setSubUrl, listSearch, clearSelection],
  );

  const handleFilterChange = useCallback(
    (f: FilterState) => {
      setFilters(f);
      listSearch.resetPage();
    },
    [listSearch],
  );

  const params = useMemo<OrderListParams>(
    () => ({
      tab,
      sub: subFilter || undefined,
      q: listSearch.debouncedSearch || undefined,
      channel: filters.channel || undefined,
      store_id: filters.store_id || undefined,
      location_id: filters.location_id || undefined,
      content_type:
        (filters.content_type as OrderListParams["content_type"]) || undefined,
      date_from: filters.date_from || undefined,
      date_to: filters.date_to || undefined,
      shipping_provider: filters.shipping_provider || undefined,
      payment: (filters.payment as OrderListParams["payment"]) || undefined,
      label_printed:
        (filters.label_printed as OrderListParams["label_printed"]) ||
        undefined,
      contact_status:
        (filters.contact_status as OrderListParams["contact_status"]) ||
        undefined,
      decision:
        (filters.decision as OrderListParams["decision"]) || undefined,
      status: filters.status.length > 0 ? filters.status : undefined,
      page: listSearch.page,
      per_page: listSearch.perPage,
    }),
    [tab, subFilter, listSearch.debouncedSearch, listSearch.page, listSearch.perPage, filters],
  );

  const { data, isLoading, isFetching } = useOrders(params);

  const orders = data?.data ?? [];
  const meta = data?.meta ?? {
    current_page: 1,
    last_page: 1,
    per_page: listSearch.perPage,
    total: 0,
  };

  const selectable = TABS_WITH_ACTIONS.has(tab);
  const allSelected =
    selectable &&
    orders.length > 0 &&
    orders.every((o) => selectedIds.has(o.id));
  const someSelected = selectable && orders.some((o) => selectedIds.has(o.id));

  const toggleAll = useCallback(() => {
    if (allSelected) {
      setSelectedIds(new Set());
    } else {
      setSelectedIds(new Set(orders.map((o) => o.id)));
    }
  }, [allSelected, orders]);

  const selectAllCheckbox = selectable ? (
    <div className="flex items-center gap-2">
      <Checkbox
        checked={allSelected ? true : someSelected ? "indeterminate" : false}
        onCheckedChange={toggleAll}
      />
      <span className="text-sm text-muted-foreground">
        {allSelected ? "Batalkan" : "Pilih semua"}
      </span>
    </div>
  ) : null;

  const tabLabel = TAB_CONFIG.find((t) => t.key === tab)?.label ?? "";
  const hasSubPills = !!SUB_PILL_CONFIG[tab];

  return (
    <div className="flex flex-col gap-4">
      <OrderStatusTabs active={tab} onChange={handleTabChange} />

      <LiquidGlass
        radius={24}
        intensity="default"
        className="bg-white/40 dark:bg-white/[0.06]"
      >
        <div className="flex flex-wrap items-center justify-between gap-3 border-b border-border/60 px-5 py-4 sm:px-6 sm:py-5">
          <div className="min-w-0">
            <h2 className="text-base font-medium">{tabLabel}</h2>
            {hasSubPills && (
              <div className="mt-3">
                <OrderSubStatusPills
                  active={tab}
                  subFilter={subFilter}
                  onSubFilterChange={handleSubFilterChange}
                />
              </div>
            )}
          </div>
          <div className="flex items-center gap-2">
            {tab === "cancellation" && <ExportCancelDialog />}
            <ExportOrdersDialog tab={tab} />
          </div>
        </div>

        <OrderFilters
          query={listSearch.search}
          onQueryChange={listSearch.setSearch}
          filters={filters}
          onChange={handleFilterChange}
          leading={selectAllCheckbox}
          tab={tab}
          trailing={
            <div className="flex items-center gap-2">
              <Button asChild variant="outline" size="sm" className="h-9 rounded-full gap-1.5">
                <Link href="/dashboard/pesanan/import">
                  <ImportIcon className="size-4" />
                  Import
                </Link>
              </Button>
              <Button asChild variant="primary" size="sm" className="h-9 rounded-full gap-1.5">
                <Link href="/dashboard/pesanan/tambah">
                  <PlusIcon className="size-4" />
                  Buat Pesanan
                </Link>
              </Button>
            </div>
          }
        />

        <div className="px-4 py-4 sm:px-5">
          <OrderCardList
            orders={orders}
            tab={tab}
            subFilter={subFilter}
            selectedIds={selectedIds}
            onSelectionChange={setSelectedIds}
            isLoading={isLoading}
            page={meta.current_page}
            lastPage={meta.last_page}
            total={meta.total}
            perPage={meta.per_page}
            onPageChange={listSearch.setPage}
            onPerPageChange={(s) => {
              listSearch.setPerPage(s);
              listSearch.resetPage();
            }}
            isFetching={isFetching}
          />
        </div>
      </LiquidGlass>

      <BulkActionBar
        tab={tab}
        subFilter={subFilter}
        count={selectedIds.size}
        onClear={clearSelection}
        selectedIds={Array.from(selectedIds)}
      />
    </div>
  );
}

