      if (hasDriver) {
        await update.mutateAsync({
          shipmentId,
          data,
          idCardPhoto: photo ?? undefined,
        });
        toast.success("Data driver diperbarui.");
      } else {
        await record.mutateAsync({
          shipmentId,
          data,
          idCardPhoto: photo ?? undefined,
        });
        toast.success("Data driver berhasil dicatat.");
      }
      setEditing(false);
    } catch (err) {
      apiError(err, "Gagal menyimpan data driver.");
