"use client";

import * as React from "react";

import { cn } from "@/lib/utils";
import { Skeleton } from "@/components/ui/skeleton";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";

export interface PillTabItem<T extends string = string> {
  key: T;
  label: React.ReactNode;
  icon?: React.ComponentType<{ className?: string }>;

  count?: number | null;

  countLoading?: boolean;
}

export function PillTab<T extends string>({
  item,
  active,
  variant = "solid",
  onSelect,
}: {
  item: PillTabItem<T>;
  active: boolean;
  variant?: "solid" | "soft";
  onSelect: (key: T) => void;
}) {
  const Icon = item.icon;
  return (
    <TabsTrigger
      value={item.key}
      className={cn(
        "inline-flex h-auto items-center gap-1.5 rounded-full font-medium transition-colors after:hidden!",
        variant === "solid" ? "px-3 py-1.5 text-sm" : "px-2.5 py-1 text-xs",
        active
          ? variant === "solid"
            ? "bg-foreground! text-background! shadow-sm!"
            : "bg-foreground/10! text-foreground!"
          : variant === "solid"
            ? "bg-muted/60 text-muted-foreground hover:bg-muted hover:text-foreground"
            : "text-muted-foreground hover:bg-muted/60 hover:text-foreground",
      )}
    >
      {Icon && <Icon className="size-4" />}
      {item.label}
      {item.countLoading ? (
        <Skeleton className="h-4 w-6 rounded-full" />
      ) : item.count != null ? (
        <span
          className={cn(
            "rounded-full px-1.5 text-xs tabular-nums",
            active && variant === "solid"
              ? "bg-background/20 text-background"
              : "bg-background text-muted-foreground",
          )}
        >
          {item.count}
        </span>
      ) : null}
    </TabsTrigger>
  );
}

export function PillTabs<T extends string>({
  items,
  active,
  onSelect,
  variant = "solid",
  className,
}: {
  items: PillTabItem<T>[];
  active: T | null;
  onSelect: (key: T) => void;
  variant?: "solid" | "soft";
  className?: string;
}) {
  return (
    <Tabs value={active || ""} onValueChange={(val) => onSelect(val as T)}>
      <TabsList className={cn("h-auto w-full flex-wrap justify-start gap-1 bg-transparent p-0", className)}>
        {items.map((item) => (
          <PillTab
            key={item.key}
            item={item}
            active={active === item.key}
            variant={variant}
            onSelect={onSelect}
          />
        ))}
      </TabsList>
    </Tabs>
  );
}

"use client";

import * as React from "react";
import { usePathname } from "next/navigation";

import { useSidebar } from "@/components/ui/sidebar";
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetDescription,
} from "@/components/ui/sheet";
import { SidebarRailNav } from "./sidebar-rail-nav";
import { SidebarPanel } from "./sidebar-panel";
import DashboardNavigation from "./nav-main";
import { findGroupIdForPath, isLeafGroup } from "./nav-data";
import { useVisibleNav } from "./use-visible-nav";

const useIsomorphicLayoutEffect =
  typeof window !== "undefined" ? React.useLayoutEffect : React.useEffect;

export function DashboardSidebar() {
  const { open, setOpen, toggleSidebar, isMobile, openMobile, setOpenMobile } =
    useSidebar();
  const pathname = usePathname();
  const { groups } = useVisibleNav();
  const containerRef = React.useRef<HTMLDivElement>(null);
  const [panelPos, setPanelPos] = React.useState({ top: 72, maxHeight: 0 });

  const [activeGroupId, setActiveGroupId] = React.useState(() =>
    findGroupIdForPath(pathname, groups),
  );

  const [prevPath, setPrevPath] = React.useState(pathname);
  if (pathname !== prevPath) {
    setPrevPath(pathname);
    setActiveGroupId(findGroupIdForPath(pathname, groups));
  }

  const activeGroup =
    groups.find((g) => g.id === activeGroupId) ?? groups[0];

  const panelOpen = open && !isLeafGroup(activeGroup);

  useIsomorphicLayoutEffect(() => {
    if (!panelOpen) return;
    const container = containerRef.current;
    if (!container) return;

    const measure = () => {
      const activeEl = container.querySelector<HTMLElement>(
        '[data-rail-active="true"]',
      );
      if (!activeEl) return;
      const cRect = container.getBoundingClientRect();
      const aRect = activeEl.getBoundingClientRect();
      const margin = 12;
      const minRoom = 140;
      const iconTop = aRect.top - cRect.top;
      const maxTop = Math.max(
        margin,
        window.innerHeight - cRect.top - minRoom - margin,
      );
      const top = Math.max(margin, Math.min(iconTop, maxTop));
      const maxHeight = window.innerHeight - cRect.top - top - margin;
      setPanelPos({ top, maxHeight });
    };

    measure();
    window.addEventListener("resize", measure);
    return () => window.removeEventListener("resize", measure);
  }, [panelOpen, activeGroupId]);

  const handleSelect = React.useCallback(
    (id: string) => {
      const group = groups.find((g) => g.id === id);
      const hasPanel = group && !isLeafGroup(group);

      if (!hasPanel) {
        setActiveGroupId(id);
        return;
      }

      if (id === activeGroupId) {
        toggleSidebar();
      } else {
        setActiveGroupId(id);
        if (!open) toggleSidebar();
      }
    },
    [activeGroupId, open, panelOpen, toggleSidebar, groups],
  );

  if (isMobile) {
    return (
      <Sheet open={openMobile} onOpenChange={setOpenMobile}>
        <SheetContent side="left" className="w-[300px] bg-sidebar p-0">
          <SheetHeader className="sr-only">
            <SheetTitle>Menu navigasi</SheetTitle>
            <SheetDescription>Daftar menu dashboard</SheetDescription>
          </SheetHeader>
          <div className="flex h-full flex-col overflow-y-auto px-2 py-4">
            {groups.map((group) => (
              <div key={group.id} className="py-2">
                {group.zone !== "top" && (
                  <div className="px-3 pb-1 text-xs font-semibold uppercase tracking-wider text-muted-foreground">
                    {group.title}
                  </div>
                )}
                <DashboardNavigation routes={group.items} />
              </div>
            ))}
          </div>
        </SheetContent>
      </Sheet>
    );
  }

  return (
    <div
      ref={containerRef}
      className="relative z-10 hidden h-dvh shrink-0 md:flex md:p-3 md:pr-0"
    >
      {panelOpen && (
        <button
          type="button"
          aria-label="Tutup panel navigasi"
          tabIndex={-1}
          onClick={() => setOpen(false)}
          className="fixed inset-0 z-40 cursor-default"
        />
      )}

      <div className="relative z-50">
        <SidebarRailNav
          activeGroupId={activeGroupId}
          onSelect={handleSelect}
          onTogglePanel={toggleSidebar}
        />
      </div>

      <SidebarPanel
        group={activeGroup}
        open={panelOpen}
        top={panelPos.top}
        maxHeight={panelPos.maxHeight}
      />
    </div>
  );
}

