export function SidebarRailNav({
  activeGroupId,
  onSelect,
  onTogglePanel,
}: {
  activeGroupId: string;
  onSelect: (id: string) => void;
  onTogglePanel: () => void;
}) {
  const pathname = usePathname();
  const logout = useLogout();
  const me = useMe();
  const { groups: visibleGroups, settings: visibleSettings } = useVisibleNav();

  const handleLogout = () => logout.mutate();
  const initials = getInitials(me.data?.name ?? "");
  const displayName = me.data?.name ?? "Akun";

  return (
    <aside
      aria-label="Navigasi utama"
      className="sidebar-glass glass-elevation liquid-glass-subtle relative flex h-full w-[68px] flex-col items-center rounded-2xl py-3"
    >
      <Link
        href="/dashboard"
        aria-label="Beranda"
        className="mb-1 grid size-10 place-items-center"
      >
        <Logo className="size-7 text-primary" />
      </Link>

      <nav className="no-scrollbar flex w-full flex-1 flex-col items-center gap-1 overflow-y-auto py-1">
        {ZONES.map((zone, zi) => {
          const groups = visibleGroups.filter((g) => g.zone === zone);
          if (groups.length === 0) return null;
          return (
            <React.Fragment key={zone}>
              {zi > 0 && <RailDivider />}
              {groups.map((group) => (
                <RailItem
                  key={group.id}
                  group={group}
                  active={activeGroupId === group.id}
                  onSelect={onSelect}
                />
              ))}
            </React.Fragment>
          );
        })}
      </nav>

      <div className="flex w-full flex-col items-center gap-1 pt-1">
        <RailDivider />
        <NotificationsPopover />
        {visibleSettings.map((route) => {
          const isActive =
            pathname === route.link ||
            pathname.startsWith(route.link + "/") ||
            route.subs?.some(
              (s) => pathname === s.link || pathname.startsWith(s.link + "/"),
            );
          return <RailLink key={route.id} route={route} active={isActive} />;
        })}
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <button
              type="button"
              aria-label={displayName}
              className="mt-1 rounded-full outline-none focus-visible:ring-3 focus-visible:ring-ring/30"
            >
              <Avatar className="size-9">
                <AvatarImage src={me.data?.avatar_url ?? ""} alt={displayName} />
                <AvatarFallback className="bg-primary/10 text-primary font-medium">
                  {initials || "?"}
                </AvatarFallback>
              </Avatar>
            </button>
          </DropdownMenuTrigger>
          <DropdownMenuContent side="right" align="end" className="w-52">
            <DropdownMenuLabel>Akun</DropdownMenuLabel>
            <DropdownMenuItem asChild>
              <Link href="/dashboard/profil-saya">
                <UserCog className="size-4 text-muted-foreground" />
                Profil Saya
              </Link>
            </DropdownMenuItem>
            <DropdownMenuSeparator />
            <DropdownMenuItem variant="destructive" onClick={handleLogout}>
              <LogOutIcon className="size-4" />
              Keluar
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>
      </div>
    </aside>
  );
}

"use client";

import * as React from "react";

import { usePermissions } from "@/hooks/auth/use-permissions";
import {
  dashboardGroups,
  settingsRoutes,
  filterNavGroups,
  filterSettingsRoutes,
} from "./nav-data";

/**
 * Nav yang sudah difilter sesuai hak akses pengguna. Dipakai bersama oleh
 * rail & panel sidebar agar konsisten. Owner melihat semua (usePermissions).
 */
export function useVisibleNav() {
  const { canAny, isOwner, permissions } = usePermissions();

  const has = React.useCallback(
    (perm?: string | string[]) =>
      !perm || canAny(Array.isArray(perm) ? perm : [perm]),
    [canAny],
  );

  const groups = React.useMemo(
    () => filterNavGroups(dashboardGroups, has),
    [has, isOwner, permissions],
  );
  const settings = React.useMemo(
    () => filterSettingsRoutes(settingsRoutes, has),
    [has, isOwner, permissions],
  );

  return { groups, settings };
}

