                <AlertCircleIcon className="mt-0.5 size-5 shrink-0" />
                <div>
                  <div className="mb-1 font-semibold">
                    Terdapat kesalahan pada produk:
                  </div>
                  <ul className="list-disc pl-5 space-y-1">
                    {itemErrors.map((msg, i) => (
