"use client";
import { EmptyState } from "@/components/ui/empty-state";

import { useState, useMemo } from "react";
import { useListState } from "@/hooks/use-list-state";
import Link from "next/link";
import {
  PlusIcon,
  ClipboardListIcon,
  Trash2Icon,
  Loader2Icon,
} from "lucide-react";

import { Button } from "@/components/ui/button";
import { Combobox } from "@/components/ui/combobox";
import { LiquidGlass } from "@/components/ui/liquid-glass";
import { ConfirmDialog } from "@/components/ui/confirm-dialog";

import { FilterToolbar } from "@/components/dashboard/master-produk/filter-toolbar";
import { DataTable } from "@/components/ui/data-table/data-table";
import { DateRangePicker } from "@/components/ui/date-picker";
import type { ColumnDef } from "@tanstack/react-table";

import {
  usePurchaseOrders,
  useDeletePurchaseOrder,
  useBulkDeletePurchaseOrder,
} from "@/hooks/transaksi-pembelian/use-purchase-orders";
import { useLocations } from "@/hooks/manajemen-rak/use-locations";
import type {
  PurchaseOrder,
  PurchaseOrderListParams,
} from "@/types/transaksi-pembelian/purchase-order";
import { formatDate, formatCurrency } from "@/lib/format";

interface FilterState {
  location_id: string;
  date_from: string;
  date_to: string;
}

const EMPTY_FILTERS: FilterState = {
  location_id: "",
  date_from: "",
  date_to: "",
};

export function PesananListView() {
  const list = useListState<FilterState>(EMPTY_FILTERS, {
    perPage: 20,
    debounceMs: 300,
    namespace: "po",
  });
  const {
    search,
    setSearch,
    debouncedSearch,
    page,
    perPage,
    filters,
    setFilters,
    pagination,
    onPaginationChange,
  } = list;

  const [deleteTarget, setDeleteTarget] = useState<PurchaseOrder | null>(null);
  const [bulkDeleteTarget, setBulkDeleteTarget] = useState<
    PurchaseOrder[] | null
  >(null);
  const deleteMut = useDeletePurchaseOrder();
  const bulkDeleteMut = useBulkDeletePurchaseOrder();

  function handleDelete() {
    if (!deleteTarget) return;
    deleteMut.mutate(deleteTarget.id, {
      onSuccess: () => setDeleteTarget(null),
    });
  }

  function handleBulkDelete(table: { toggleAllPageRowsSelected: () => void }) {
    if (!bulkDeleteTarget) return;
    const ids = bulkDeleteTarget.map((p) => p.id);
    bulkDeleteMut.mutate(ids, {
      onSuccess: () => {
        setBulkDeleteTarget(null);
        table.toggleAllPageRowsSelected(false);
      },
    });
  }

  const params = useMemo<PurchaseOrderListParams>(() => {
    const p: PurchaseOrderListParams = {
      search: debouncedSearch || undefined,
      page,
      per_page: perPage,
      "filter[location_id]": filters.location_id || undefined,
    };

    if (filters.date_from) p["filter[date_from]"] = filters.date_from;
    if (filters.date_to) p["filter[date_to]"] = filters.date_to;

    return p;
  }, [debouncedSearch, page, perPage, filters]);

  const { data, isLoading, isFetching } = usePurchaseOrders(params);
  const { data: locData } = useLocations({ perPage: 100 });

  const items = data?.items ?? [];
  const meta = data?.meta ?? {
    current_page: 1,
    last_page: 1,
    per_page: perPage,
    total: 0,
  };
  const activeCount = [filters.location_id, filters.date_from].filter(
    Boolean,
  ).length;

  const locationOptions = useMemo(
    () => [
      { value: "", label: "Semua Lokasi" },
      ...(locData?.items ?? [])
        .filter((l) => l.isWarehouse && l.locationType !== "TRANSIT")
        .map((l) => ({ value: l.id, label: l.locationName })),
    ],
    [locData],
  );

  const hasActiveFilter = Boolean(filters.location_id || filters.date_from);

  const columns = useMemo<ColumnDef<PurchaseOrder>[]>(
    () => [
      {
        accessorKey: "po_number",
        header: "No. Pesanan",
        cell: ({ row }) => (
          <Link
            href={`/dashboard/transaksi-pembelian/pesanan/${row.original.id}`}
            className="font-medium hover:text-primary hover:underline"
          >
            {row.original.po_number}
          </Link>
        ),
      },
      {
        id: "pemasok",
        header: "Pemasok",
        cell: ({ row }) => <span>{row.original.contact?.name ?? "—"}</span>,
      },
      {
        id: "lokasi",
        header: "Lokasi",
        cell: ({ row }) => (
          <span>{row.original.location?.location_name ?? "—"}</span>
        ),
      },
      {
        accessorKey: "order_date",
        header: "Tgl. Pesanan",
        cell: ({ row }) => <span>{formatDate(row.original.order_date)}</span>,
      },
      {
        accessorKey: "total_amount",
        header: () => <div className="text-right">Nilai</div>,
        cell: ({ row }) => (
          <div className="text-right font-medium tabular-nums">
            {formatCurrency(row.original.total_amount)}
          </div>
        ),
      },
      {
        accessorKey: "notes",
        header: "Keterangan",
        cell: ({ row }) => (
          <div className="max-w-[160px] truncate">
            {row.original.notes || "—"}
          </div>
        ),
      },
      {
        id: "actions",
        header: "",
        cell: ({ row }) => {
          if (
            row.original.status === "OPEN" ||
            row.original.status === "DRAFT"
          ) {
            return (
              <div className="flex justify-end">
                <Button
                  variant="ghost"
                  size="icon-sm"
                  onClick={() => setDeleteTarget(row.original)}
                  className="text-destructive hover:bg-destructive/10 hover:text-destructive"
                >
                  <Trash2Icon className="size-3.5" />
                </Button>
              </div>
            );
          }
          return null;
        },
      },
    ],
    [],
  );

  return (
    <div className="flex flex-col gap-4">
      <LiquidGlass
        radius={24}
        intensity="default"
        className="bg-white/40 dark:bg-white/[0.06]"
      >
        <FilterToolbar
          search={search}
          onSearchChange={setSearch}
          searchPlaceholder="Cari no. pesanan, pemasok..."
          align="end"
          onReset={
            hasActiveFilter ? () => setFilters(EMPTY_FILTERS) : undefined
          }
          hasFilter={hasActiveFilter}
          activeCount={activeCount}
          gridCols={2}
          trailing={
            <Button variant="primary" asChild>
              <Link href="/dashboard/transaksi-pembelian/pesanan/tambah">
                <PlusIcon className="size-4" />
                Buat Pesanan
              </Link>
            </Button>
          }
        >
          <Combobox
            options={locationOptions}
            value={filters.location_id}
            onChange={(v) => setFilters({ ...filters, location_id: v ?? "" })}
            placeholder="Lokasi"
            searchPlaceholder="Cari lokasi"
            className="h-9 bg-background"
          />
          <DateRangePicker
            value={{
              from: filters.date_from ? new Date(filters.date_from) : undefined,
              to: filters.date_to ? new Date(filters.date_to) : undefined,
            }}
            onChange={(range) => {
              const toStr = (d?: Date) =>
                d ? d.toISOString().slice(0, 10) : "";
              setFilters({
                ...filters,
                date_from: toStr(range?.from),
                date_to: toStr(range?.to),
              });
            }}
            placeholder="Tanggal Pesanan"
            className="h-9 bg-background"
          />
        </FilterToolbar>

        {isFetching && !isLoading && (
          <div className="flex justify-center py-2">
            <Loader2Icon className="size-4 animate-spin text-primary" />
          </div>
        )}

        <div className="px-5 py-5 sm:px-6">
          <DataTable
            columns={columns}
            data={items}
            isLoading={isLoading}
            enableRowSelection
            bulkActions={(selected, table) => (
              <Button
                variant="destructive"
                size="sm"
                onClick={() => setBulkDeleteTarget(selected)}
                className="gap-2"
              >
                <Trash2Icon className="size-4" />
                Hapus ({selected.length})
              </Button>
            )}
            hideToolbar
            manualPagination
            pagination={pagination}
            rowCount={meta.total}
            onPaginationChange={onPaginationChange}
            tableContainerClassName="border-0 bg-transparent backdrop-blur-none [&_[data-slot=table-header]]:bg-transparent"
            emptyState={
              <EmptyState
                icon={ClipboardListIcon}
                title="Belum ada pesanan pembelian"
                description="Buat pesanan baru untuk mulai memesan barang dari pemasok."
              />
            }
          />
        </div>
      </LiquidGlass>

      <ConfirmDialog
        open={!!deleteTarget}
        onOpenChange={(v) => !v && setDeleteTarget(null)}
        title="Hapus Pesanan"
        description={`Apakah Anda yakin ingin menghapus pesanan "${deleteTarget?.po_number}"? Tindakan ini tidak dapat dibatalkan.`}
        confirmLabel="Hapus"
        variant="destructive"
        loading={deleteMut.isPending}
        onConfirm={handleDelete}
      />

      <ConfirmDialog
        open={!!bulkDeleteTarget}
        onOpenChange={(v) => !v && setBulkDeleteTarget(null)}
        title="Hapus Pesanan (Bulk)"
        description={`Apakah Anda yakin ingin menghapus ${bulkDeleteTarget?.length} pesanan yang dipilih? Tindakan ini tidak dapat dibatalkan.`}
        confirmLabel="Hapus"
        variant="destructive"
        loading={bulkDeleteMut.isPending}
        onConfirm={() =>
          handleBulkDelete({ toggleAllPageRowsSelected: () => {} })
        }
      />
    </div>
  );
}

"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import {
  Loader2Icon,
  PackageSearchIcon,
  PlusIcon,
  ScanBarcodeIcon,
  Trash2Icon,
} from "lucide-react";

import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Combobox } from "@/components/ui/combobox";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { LiquidGlass } from "@/components/ui/liquid-glass";
import { PageTitle } from "@/components/dashboard/page-title";
import { FormFooter } from "@/components/dashboard/shared/form-footer";
import { UserSelect } from "@/components/dashboard/shared/user-select";
import { useLocations } from "@/hooks/manajemen-rak/use-locations";
import { useCreateStockAdjustment } from "@/hooks/transaksi-stok/use-stock-adjustments";
import {
  ProductPickerDialog,
  type PickedProduct,
} from "@/components/dashboard/transaksi-pembelian/product-picker-dialog";
import { InventoryStockService } from "@/services/persediaan/inventory.service";
import { cn } from "@/lib/utils";
import { playScanFeedback } from "@/lib/scan-feedback";

const LIST_HREF = "/dashboard/transaksi-stok?tab=penyesuaian";

interface LineBin {
  id: string;
  code: string;
  onHand: number;
  avgCost: number;
}

interface LineDraft {
  itemId: string;
  sku: string;
  name: string;
  variantLabel: string;
  thumbnail: string | null;
  binId: string;
  binCode: string;
  binOnHand: number;
  binAvgCost: number;
  delta: string;
  unitCost: string;
  notes: string;
  availableBins: LineBin[];
}

function todayStr(): string {
  return new Date().toISOString().slice(0, 10);
}

export function BuatPenyesuaianView() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const [locationId, setLocationId] = useState(
    () => searchParams.get("location_id") ?? "",
  );
  const [transactionDate, setTransactionDate] = useState(todayStr);
  const [adjustmentNo, setAdjustmentNo] = useState("[auto]");
  const [notes, setNotes] = useState("");
  const [createdBy, setCreatedBy] = useState("");
  const [lines, setLines] = useState<LineDraft[]>([]);
  const [pickerOpen, setPickerOpen] = useState(false);
  const [pickerSearch, setPickerSearch] = useState<string | undefined>(
    undefined,
  );
  const [scanCode, setScanCode] = useState("");
  const [scanning, setScanning] = useState(false);
  const [scanFlash, setScanFlash] = useState<"ok" | "err" | null>(null);
  const scanRef = useRef<HTMLInputElement>(null);

  const { data: locData } = useLocations({ perPage: 100 });
  const createMut = useCreateStockAdjustment();

  const locationOptions = useMemo(
    () =>
      (locData?.items ?? []).map((l) => ({ value: l.id, label: l.locationName })),
    [locData],
  );

  useEffect(() => {
    if (locationId) scanRef.current?.focus();
  }, [locationId]);

  const prefillAppliedRef = useRef(false);

  useEffect(() => {
    if (prefillAppliedRef.current) return;
    const itemsParam = searchParams.get("items");
    const locParam = searchParams.get("location_id");
    if (!itemsParam || !locParam) return;
    prefillAppliedRef.current = true;

    let entries: { sku: string; qty: number; binId: string }[] = [];
    try {
      entries = JSON.parse(itemsParam);
    } catch {
      return;
    }
    if (!Array.isArray(entries) || entries.length === 0) return;

    (async () => {
      const results = await Promise.all(
        entries.map((e) =>
          InventoryStockService.bySku(e.sku, locParam).catch(() => null),
        ),
      );

      let addedAny = false;

      setLines((prev) => {
        const existing = new Set(prev.map((l) => l.itemId));
        const fresh: LineDraft[] = [];

        results.forEach((res, i) => {
          const variant = res?.data;
          if (!variant || existing.has(variant.id)) return;
          const entry = entries[i];
          const bin =
            variant.available_bins.find((b) => b.id === entry.binId) ??
            variant.primary_bin ??
            null;

          fresh.push({
            itemId: variant.id,
            sku: variant.sku,
            name: variant.product_name ?? variant.sku,
            variantLabel: variant.variant_label,
            thumbnail: variant.thumbnail_url,
            binId: bin?.id ?? "",
            binCode: bin?.code ?? "",
            binOnHand: bin?.on_hand ?? 0,
            binAvgCost: bin?.avg_cost ?? variant.avg_cost ?? 0,
            delta: String(-entry.qty),
            unitCost: bin?.avg_cost != null ? String(bin.avg_cost) : "",
            notes: "Selisih penempatan (stok fiktif)",
            availableBins: variant.available_bins.map((b) => ({
              id: b.id,
              code: b.code,
              onHand: b.on_hand,
              avgCost: b.avg_cost,
            })),
          });
        });

        addedAny = fresh.length > 0;
        return [...prev, ...fresh];
      });

      if (addedAny) {
        setNotes((prev) => prev || "Selisih penempatan (stok fiktif)");
      }
    })();
  }, [searchParams]);

  const addLines = (
    products: (PickedProduct & {
      binId?: string;
      binCode?: string;
      binOnHand?: number;
      binAvgCost?: number;
      variantLabel?: string;
      thumbnail?: string | null;
      availableBins?: LineBin[];
    })[],
  ) => {
    setLines((prev) => {
      const existing = new Set(prev.map((l) => l.itemId));
      const fresh = products
        .filter((p) => !existing.has(p.itemId))
        .map((p) => ({
          itemId: p.itemId,
          sku: p.sku,
          name: p.name,
          variantLabel: p.variantLabel ?? "",
          thumbnail: p.thumbnail ?? null,
          binId: p.binId ?? "",
          binCode: p.binCode ?? "",
          binOnHand: p.binOnHand ?? 0,
          binAvgCost: p.binAvgCost ?? 0,
          delta: "",
          unitCost: p.binAvgCost != null ? String(p.binAvgCost) : "",
          notes: "",
          availableBins: p.availableBins ?? [],
        }));
      return [...prev, ...fresh];
    });
    setPickerOpen(false);
    setPickerSearch(undefined);
    setTimeout(() => scanRef.current?.focus(), 250);
  };

  const flash = (state: "ok" | "err") => {
    setScanFlash(state);
    playScanFeedback(state === "ok" ? "ok" : "error");
    setTimeout(() => setScanFlash(null), 350);
  };

  const updateLine = (itemId: string, patch: Partial<LineDraft>) =>
    setLines((prev) =>
      prev.map((l) => (l.itemId === itemId ? { ...l, ...patch } : l)),
    );
  const removeLine = (itemId: string) =>
    setLines((prev) => prev.filter((l) => l.itemId !== itemId));

  const handleScan = async () => {
    const q = scanCode.trim();
    if (!q || scanning) return;

    setScanning(true);
    try {
      const res = await InventoryStockService.bySku(q, locationId);
      const variant = res.data;

      if (lines.some((l) => l.itemId === variant.id)) {
        flash("err");
        return;
      }
      addLines([
        {
          itemId: variant.id,
          sku: variant.sku,
          name: variant.product_name ?? variant.sku,
          variantLabel: variant.variant_label,
          thumbnail: variant.thumbnail_url,
          binId: variant.primary_bin?.id ?? "",
          binCode: variant.primary_bin?.code ?? "",
          binOnHand: variant.primary_bin?.on_hand ?? 0,
          binAvgCost: variant.primary_bin?.avg_cost ?? variant.avg_cost ?? 0,
          availableBins: (variant.available_bins ?? []).map((b) => ({
            id: b.id,
            code: b.code,
            onHand: b.on_hand,
            avgCost: b.avg_cost,
          })),
          sellPrice: null,
        },
      ]);
      flash("ok");
    } catch (err) {
      const status = (err as { status?: number })?.status;
      if (status === 404) {
        setPickerSearch(q);
        setPickerOpen(true);
      } else {
        flash("err");
      }
    } finally {
      setScanning(false);
      setScanCode("");
    }
  };

  const validLines = lines.filter((l) => {
    const d = Number(l.delta);
    return l.delta !== "" && !Number.isNaN(d) && d !== 0;
  });
  const canSubmit =
    !!locationId &&
    !!transactionDate &&
    !!createdBy.trim() &&
    validLines.length > 0;

  const handleSubmit = () => {
    if (!canSubmit) return;
    createMut.mutate(
      {
        transaction_date: transactionDate,
        location_id: locationId,
        adjustment_no:
          adjustmentNo.trim() === "" || adjustmentNo.trim() === "[auto]"
            ? undefined
            : adjustmentNo.trim(),
        notes: notes.trim() || undefined,
        created_by: createdBy.trim(),
        items: validLines.map((l) => {
          const cost = Number(l.unitCost);
          return {
            item_id: l.itemId,
            bin_id: l.binId || undefined,
            actual_qty: l.binOnHand + Number(l.delta),
            unit_cost: Number.isFinite(cost) && cost > 0 ? cost : undefined,
            notes: l.notes.trim() || undefined,
          };
        }),
      },
      { onSuccess: () => router.push(LIST_HREF) },
    );
  };

  return (
    <div className="flex flex-col gap-5">
      <PageTitle
        title="Buat Koreksi Stok"
        backHref={LIST_HREF}
        breadcrumb={[
          { label: "Persediaan" },
          { label: "Transaksi Stok", href: LIST_HREF },
          { label: "Buat Koreksi Stok" },
        ]}
      />

      {}
      <LiquidGlass
        radius={16}
        intensity="subtle"
        className="bg-white/40 dark:bg-white/[0.06]"
      >
        <div className="flex flex-col gap-4 px-5 py-5">
          <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3">
            <div className="flex flex-col gap-1.5">
              <Label className="text-sm font-medium">No. Penyesuaian</Label>
              <Input
                value={adjustmentNo}
                onChange={(e) => setAdjustmentNo(e.target.value)}
                onFocus={(e) => {
                  if (e.target.value === "[auto]") {
                    setAdjustmentNo("");
                  }
                }}
                onBlur={(e) => {
                  if (e.target.value.trim() === "") {
                    setAdjustmentNo("[auto]");
                  }
                }}
              />
            </div>
            <div className="flex flex-col gap-1.5">
              <Label className="text-sm font-medium">
                Tanggal <span className="text-destructive">*</span>
              </Label>
              <Input
                type="date"
                value={transactionDate}
                onChange={(e) => setTransactionDate(e.target.value)}
              />
            </div>
            <div className="flex flex-col gap-1.5">
              <Label className="text-sm font-medium">
                Lokasi <span className="text-destructive">*</span>
              </Label>
              <Combobox
                options={locationOptions}
                value={locationId}
                onChange={(v) => {
                  setLocationId(v ?? "");
                  setLines((p) => p.map((l) => ({ ...l, binId: "" })));
                }}
                placeholder="Pilih lokasi…"
                searchPlaceholder="Cari lokasi…"
              />
            </div>
          </div>
          <div className="flex flex-col gap-1.5">
            <Label className="text-sm font-medium">Keterangan</Label>
            <Textarea
              value={notes}
              onChange={(e) => setNotes(e.target.value)}
              placeholder="Alasan koreksi (opsional)"
              rows={3}
            />
          </div>
        </div>
      </LiquidGlass>

      {}
      <div className="sr-only" aria-hidden="true">
        <UserSelect
          value={createdBy}
          onChange={setCreatedBy}
          defaultToSelf
          placeholder="Petugas"
        />
      </div>

      {}
      <LiquidGlass
        radius={16}
        intensity="subtle"
        className="bg-white/40 dark:bg-white/[0.06]"
      >
        <div className="flex flex-col gap-4 px-5 py-5">
          <Label className="text-sm font-medium">
            Item Koreksi Stok <span className="text-destructive">*</span>
          </Label>

          {}
          <div className="flex flex-col gap-1.5">
            <div className="relative">
              {scanning ? (
                <Loader2Icon className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 animate-spin text-primary" />
              ) : (
                <ScanBarcodeIcon
                  className={cn(
                    "pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 transition-colors",
                    scanFlash === "ok"
                      ? "text-success"
                      : scanFlash === "err"
                        ? "text-destructive"
                        : "text-muted-foreground",
                  )}
                />
              )}
              <Input
                ref={scanRef}
                value={scanCode}
                onChange={(e) => setScanCode(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === "Enter") {
                    e.preventDefault();
                    handleScan();
                  }
                }}
                placeholder={
                  locationId
                    ? "Scan / ketik SKU lalu Enter…"
                    : "Pilih lokasi dulu untuk mulai scan…"
                }
                disabled={!locationId || scanning}
                className={cn(
                  "h-10 pl-9 text-base transition-colors",
                  scanFlash === "ok" &&
                    "border-success ring-2 ring-success/30",
                  scanFlash === "err" &&
                    "border-destructive ring-2 ring-destructive/30",
                )}
                autoComplete="off"
              />
            </div>
            <p className="text-xs text-muted-foreground">
              SKU exact match langsung tambah + rak utama auto-terisi. Rak bisa
              di-scan lewat kolom Rak.
            </p>
          </div>

          <Table containerClassName="rounded-lg border border-border">
            <TableHeader className="bg-muted/40 text-xs uppercase tracking-wider">
              <TableRow>
                <TableHead className="px-3 py-2.5 text-muted-foreground">
                  Produk
                </TableHead>
                <TableHead className="px-3 py-2.5 text-muted-foreground">
                  Kode Rak
                </TableHead>
                <TableHead className="px-3 py-2.5 text-right text-muted-foreground">
                  +/-
                </TableHead>
                <TableHead className="px-3 py-2.5 text-right text-muted-foreground">
                  On Hand
                </TableHead>
                <TableHead className="px-3 py-2.5 text-right text-muted-foreground">
                  Qty Akhir
                </TableHead>
                <TableHead className="px-3 py-2.5 text-right text-muted-foreground">
                  Harga Pokok
                </TableHead>
                <TableHead className="px-3 py-2.5 text-muted-foreground">
                  Keterangan
                </TableHead>
                <TableHead className="px-3 py-2.5" />
              </TableRow>
            </TableHeader>
            <TableBody className="divide-y divide-border">
              {lines.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={8} className="px-3 py-12 text-center">
                    <div className="flex flex-col items-center gap-2 text-muted-foreground">
                      <PackageSearchIcon className="size-7 opacity-40" />
                      <p className="text-sm">
                        Belum ada item. Scan SKU atau klik Tambah Item.
                      </p>
                    </div>
                  </TableCell>
                </TableRow>
              ) : (
                lines.map((l) => {
                  const deltaNum =
                    l.delta === "" || Number.isNaN(Number(l.delta))
                      ? 0
                      : Number(l.delta);
                  const qtyAkhir = l.binOnHand + deltaNum;
                  const willGoNegative = qtyAkhir < 0;
                  const binOptsForLine = l.availableBins.map((b) => ({
                    value: b.id,
                    label: `${b.code} · ${b.onHand} stok`,
                  }));
                  return (
                    <TableRow key={l.itemId} className="bg-background/50">
                      {}
                      <TableCell className="px-3 py-2.5">
                        <div className="flex max-w-[260px] items-center gap-3">
                          {l.thumbnail ? (
                            <img
                              src={l.thumbnail}
                              alt={l.name}
                              className="h-11 w-11 shrink-0 rounded-xl border border-border object-cover"
                            />
                          ) : (
                            <div className="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl bg-muted">
                              <PackageSearchIcon className="size-5 text-muted-foreground/40" />
                            </div>
                          )}
                          <div className="min-w-0">
                            <p className="truncate text-sm font-medium">
                              {l.name}
                            </p>
                            {l.variantLabel && (
                              <p className="truncate text-xs text-muted-foreground">
                                {l.variantLabel}
                              </p>
                            )}
                            <p className="truncate font-mono text-2xs text-muted-foreground">
                              {l.sku}
                            </p>
                          </div>
                        </div>
                      </TableCell>
                      {}
                      <TableCell className="px-3 py-2.5">
                        <Combobox
                          options={binOptsForLine}
                          value={l.binId}
                          onChange={(v) => {
                            const picked = l.availableBins.find(
                              (b) => b.id === v,
                            );
                            updateLine(l.itemId, {
                              binId: v ?? "",
                              binCode: picked?.code ?? "",
                              binOnHand: picked?.onHand ?? 0,
                              binAvgCost: picked?.avgCost ?? 0,
                              unitCost:
                                picked?.avgCost != null
                                  ? String(picked.avgCost)
                                  : l.unitCost,
                            });
                          }}
                          placeholder="Scan / pilih rak"
                          searchPlaceholder="Scan / cari rak…"
                          emptyText="Tidak ada rak dengan stok"
                          className="h-9 min-w-[160px]"
                        />
                      </TableCell>
                      {}
                      <TableCell className="px-3 py-2.5 text-right align-top">
                        <Input
                          type="number"
                          value={l.delta}
                          onChange={(e) =>
                            updateLine(l.itemId, { delta: e.target.value })
                          }
                          placeholder="0"
                          className={cn(
                            "h-9 w-20 text-right",
                            willGoNegative &&
                              "border-amber-500 ring-1 ring-amber-500/40",
                          )}
                        />
                        {willGoNegative && (
                          <p className="text-amber-600 text-xs mt-0.5">
                            Melebihi data sistem (tersedia: {l.binOnHand}) — akan tercatat minus
                          </p>
                        )}
                      </TableCell>
                      {}
                      <TableCell className="px-3 py-2.5 text-right font-mono tabular-nums text-muted-foreground align-top">
                        {l.binOnHand}
                      </TableCell>
                      {}
                      <TableCell
                        className={cn(
                          "px-3 py-2.5 text-right font-mono font-semibold tabular-nums align-top",
                          willGoNegative ? "text-amber-600" : "text-foreground",
                        )}
                      >
                        {qtyAkhir}
                      </TableCell>
                      {}
                      <TableCell className="px-3 py-2.5 text-right">
                        <Input
                          type="number"
                          min={0}
                          value={l.unitCost}
                          onChange={(e) =>
                            updateLine(l.itemId, { unitCost: e.target.value })
                          }
                          placeholder="0"
                          className="h-9 w-28 text-right"
                        />
                      </TableCell>
                      {}
                      <TableCell className="px-3 py-2.5">
                        <Input
                          value={l.notes}
                          onChange={(e) =>
                            updateLine(l.itemId, { notes: e.target.value })
                          }
                          placeholder="Alasan"
                          className="h-9 min-w-[140px]"
                        />
                      </TableCell>
                      {}
                      <TableCell className="px-3 py-2.5 text-right">
                        <Button
                          variant="ghost"
                          size="icon-sm"
                          onClick={() => removeLine(l.itemId)}
                          aria-label="Hapus"
                          className="text-destructive"
                        >
                          <Trash2Icon className="size-4" />
                        </Button>
                      </TableCell>
                    </TableRow>
                  );
                })
              )}
            </TableBody>
          </Table>

          {}
          <div className="flex items-center justify-between">
            <Button
              variant="outline"
              size="sm"
              onClick={() => setPickerOpen(true)}
              className="gap-1.5"
            >
              <PlusIcon className="size-4" /> Tambah Item
            </Button>
            {lines.length > 0 && (
              <p className="text-xs text-muted-foreground">
                Qty Akhir = On Hand + <span className="font-mono">+/-</span>.
                Selisih dihitung otomatis saat disimpan.
              </p>
            )}
          </div>
        </div>
      </LiquidGlass>

      <FormFooter>
        <Button variant="outline" onClick={() => router.push(LIST_HREF)}>
          Batal
        </Button>
        <Button
          onClick={handleSubmit}
          disabled={!canSubmit || createMut.isPending}
        >
          {createMut.isPending && (
            <Loader2Icon className="mr-2 size-4 animate-spin" />
          )}
          Simpan
        </Button>
      </FormFooter>

      <ProductPickerDialog
        open={pickerOpen}
        onOpenChange={(v) => {
          setPickerOpen(v);
          if (!v) setPickerSearch(undefined);
        }}
        onPick={addLines}
        excludeIds={lines.map((l) => l.itemId)}
        initialSearch={pickerSearch}
      />
    </div>
  );
}

"use client";

import { useState, useMemo, useCallback } from "react";
import Link from "next/link";
import { ShieldIcon, XCircleIcon } from "lucide-react";

import { Button } from "@/components/ui/button";
import { Combobox } from "@/components/ui/combobox";
import type { ColumnDef } from "@tanstack/react-table";
import { ConfirmDialog } from "@/components/ui/confirm-dialog";
import { ResourceListView } from "@/components/dashboard/shared/resource-list-view";
import { StatusBadge } from "@/components/dashboard/shared/status-badge";
import { getStatusMeta } from "@/lib/status";
import { useListState } from "@/hooks/use-list-state";
import {
  useReservedStocks,
  useCancelReservedStock,
} from "@/hooks/transaksi-stok/use-reserved-stocks";
import { useLocations } from "@/hooks/manajemen-rak/use-locations";
import { exportCsv } from "@/lib/export-csv";
import type {
  ReservedStock,
  ReservedStockListParams,
} from "@/types/transaksi-stok/reserved-stock";
import { formatDate } from "@/lib/format";

interface FilterState {
  status: string;
  location_id: string;
}

const EMPTY_FILTERS: FilterState = { status: "", location_id: "" };

const STATUS_OPTIONS = [
  { value: "", label: "Semua Status" },
  { value: "ACTIVE", label: "Aktif" },
  { value: "CANCELLED", label: "Dibatalkan" },
];

export function CadangTab() {
  const list = useListState<FilterState>(EMPTY_FILTERS, {
    urlSync: true,
    namespace: "cad",
  });
  const [cancelTarget, setCancelTarget] = useState<ReservedStock | null>(null);

  const params = useMemo<ReservedStockListParams>(
    () => ({
      search: list.debouncedSearch || undefined,
      page: list.page,
      per_page: list.perPage,
      "filter[status]": list.filters.status || undefined,
      "filter[location_id]": list.filters.location_id || undefined,
    }),
    [list.debouncedSearch, list.page, list.perPage, list.filters],
  );

  const { data, isLoading, isFetching } = useReservedStocks(params);
  const { data: locData } = useLocations({ perPage: 100 });
  const cancelMut = useCancelReservedStock();

  const items = data?.items ?? [];
  const total = data?.meta?.total ?? 0;

  const locationOptions = useMemo(
    () => [
      { value: "", label: "Semua Lokasi" },
      ...(locData?.items ?? []).map((l) => ({
        value: l.id,
        label: l.locationName,
      })),
    ],
    [locData],
  );

  const columns = useMemo<ColumnDef<ReservedStock>[]>(
    () => [
      {
        accessorKey: "reserved_stock_no",
        header: "No. Reservasi Stok",
        cell: ({ row }) => (
          <span className="font-medium">
            <Link
              href={`/dashboard/transaksi-stok/cadang/${row.original.id}`}
              className="hover:text-primary hover:underline"
            >
              {row.original.reserved_stock_no}
            </Link>
          </span>
        ),
      },
      {
        id: "location",
        header: "Lokasi",
        cell: ({ row }) => (
          <span className="text-foreground">
            {row.original.location?.location_name ?? "—"}
          </span>
        ),
      },
      {
        accessorKey: "start_date",
        header: "Tgl. Mulai",
        cell: ({ row }) => (
          <span className="text-foreground">
            {formatDate(row.original.start_date)}
          </span>
        ),
      },
      {
        accessorKey: "end_date",
        header: "Tgl. Selesai",
        cell: ({ row }) => (
          <span className="text-foreground">
            {formatDate(row.original.end_date)}
          </span>
        ),
      },
      {
        accessorKey: "status",
        header: "Status",
        cell: ({ row }) => (
          <StatusBadge
            domain="stock-reserve"
            status={row.original.status}
            className="text-2xs leading-tight"
          />
        ),
      },
      {
        accessorKey: "created_by",
        header: "Dibuat Oleh",
        cell: ({ row }) => (
          <span className="text-foreground">{row.original.created_by}</span>
        ),
      },
      {
        id: "actions",
        header: () => <div className="text-right">Aksi</div>,
        cell: ({ row }) => {
          const item = row.original;
          if (item.status === "ACTIVE") {
            return (
              <div
                className="flex items-center justify-end"
                onClick={(e) => e.stopPropagation()}
              >
                <Button
                  variant="ghost"
                  size="icon-sm"
                  onClick={() => setCancelTarget(item)}
                  aria-label="Batalkan"
                  className="text-destructive hover:text-destructive"
                >
                  <XCircleIcon className="size-3.5" />
                </Button>
              </div>
            );
          }
          return null;
        },
      },
    ],
    [],
  );

  function handleCancel() {
    if (!cancelTarget) return;
    cancelMut.mutate(cancelTarget.id, {
      onSuccess: () => setCancelTarget(null),
    });
  }

  const handleExport = useCallback(() => {
    if (items.length === 0) return;
    exportCsv(
      "reservasi-stok.csv",
      [
        "No. Reservasi Stok",
        "Lokasi",
        "Tgl. Mulai",
        "Tgl. Selesai",
        "Status",
        "Dibuat Oleh",
      ],
      items.map((item: ReservedStock) => [
        item.reserved_stock_no,
        item.location?.location_name ?? "",
        formatDate(item.start_date),
        formatDate(item.end_date),
        getStatusMeta("stock-reserve", item.status).label,
        item.created_by,
      ]),
    );
  }, [items]);

  return (
    <div className="flex flex-col gap-4">
      <ResourceListView
        list={list}
        columns={columns}
        rows={items}
        total={total}
        isLoading={isLoading}
        isFetching={isFetching}
        searchPlaceholder="Cari no. reservasi stok..."
        onExport={handleExport}
        emptyIcon={ShieldIcon}
        emptyTitle="Belum ada reservasi stok"
        emptyDescription="Data reservasi stok akan muncul di sini."
        filterControls={
          <>
            <Combobox
              options={STATUS_OPTIONS}
              value={list.filters.status}
              onChange={(v) =>
                list.setFilters({ ...list.filters, status: v ?? "" })
              }
              placeholder="Status"
              searchPlaceholder="Cari status"
              className="h-9 bg-background"
            />
            <Combobox
              options={locationOptions}
              value={list.filters.location_id}
              onChange={(v) =>
                list.setFilters({ ...list.filters, location_id: v ?? "" })
              }
              placeholder="Lokasi"
              searchPlaceholder="Cari lokasi"
              className="h-9 bg-background"
            />
          </>
        }
      />

      <ConfirmDialog
        open={!!cancelTarget}
        onOpenChange={(v) => !v && setCancelTarget(null)}
        title="Batalkan Reservasi Stok"
        description={`Apakah Anda yakin ingin membatalkan "${cancelTarget?.reserved_stock_no}"? Stok yang direservasi akan dikembalikan.`}
        confirmLabel="Batalkan"
        variant="destructive"
        loading={cancelMut.isPending}
        onConfirm={handleCancel}
      />
    </div>
  );
}

"use client";

import { useCallback, useMemo, useRef, useState } from "react";
import {
  DownloadIcon,
  FileSpreadsheetIcon,
  Loader2Icon,
  UploadCloudIcon,
} from "lucide-react";

import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { Combobox } from "@/components/ui/combobox";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { ScrollArea } from "@/components/ui/scroll-area";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { UserSelect } from "@/components/dashboard/shared/user-select";
import { useLocations } from "@/hooks/manajemen-rak/use-locations";
import {
  usePreviewStockAdjustmentImport,
  useConfirmStockAdjustmentImport,
} from "@/hooks/transaksi-stok/use-stock-adjustment-import";
import { StockAdjustmentImportService } from "@/services/transaksi-stok/stock-adjustment-import.service";
import type {
  ImportPreviewResponse,
  ImportPreviewError,
  ImportPreviewWarning,
} from "@/types/transaksi-stok/stock-adjustment-import";

function todayStr(): string {
  return new Date().toISOString().slice(0, 10);
}

interface ImportPenyesuaianDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

export function ImportPenyesuaianDialog({
  open,
  onOpenChange,
}: ImportPenyesuaianDialogProps) {
  const fileRef = useRef<HTMLInputElement>(null);
  const [file, setFile] = useState<File | null>(null);
  const [locationId, setLocationId] = useState("");
  const [transactionDate, setTransactionDate] = useState(todayStr);
  const [adjustmentNo, setAdjustmentNo] = useState("[auto]");
  const [notes, setNotes] = useState("");
  const [createdBy, setCreatedBy] = useState("");
  const [preview, setPreview] = useState<ImportPreviewResponse | null>(null);

  const { data: locData } = useLocations({ perPage: 100 });
  const previewMut = usePreviewStockAdjustmentImport();
  const confirmMut = useConfirmStockAdjustmentImport();

  const locationOptions = useMemo(
    () =>
      (locData?.items ?? []).map((l) => ({ value: l.id, label: l.locationName })),
    [locData],
  );

  const handleReset = useCallback(() => {
    setFile(null);
    setPreview(null);
    setNotes("");
    setAdjustmentNo("[auto]");
    setTransactionDate(todayStr());
    if (fileRef.current) fileRef.current.value = "";
  }, []);

  const handleClose = useCallback(
    (v: boolean) => {
      if (!v) handleReset();
      onOpenChange(v);
    },
    [onOpenChange, handleReset],
  );

  const handlePickFile = (f: File | null) => {
    setFile(f);
    setPreview(null);
  };

  const handleDropFile = (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    const f = e.dataTransfer.files?.[0];
    if (f) handlePickFile(f);
  };

  const handlePreview = () => {
    if (!file || !locationId) return;
    previewMut.mutate(
      { file, locationId },
      {
        onSuccess: (res) => setPreview(res.data),
      },
    );
  };

  const handleConfirm = () => {
    if (!preview || !createdBy.trim()) return;
    confirmMut.mutate(
      {
        preview_token: preview.token,
        transaction_date: transactionDate,
        created_by: createdBy.trim(),
        notes: notes.trim() || undefined,
        adjustment_no:
          adjustmentNo.trim() === "" || adjustmentNo.trim() === "[auto]"
            ? undefined
            : adjustmentNo.trim(),
      },
      { onSuccess: () => handleClose(false) },
    );
  };

  const canPreview = !!file && !!locationId && !previewMut.isPending;
  const canConfirm =
    !!preview &&
    preview.items.length > 0 &&
    preview.errors.length === 0 &&
    !!createdBy.trim() &&
    !confirmMut.isPending;

  return (
    <Dialog open={open} onOpenChange={handleClose}>
      <DialogContent
        className={cn(
          "flex max-h-[90vh] flex-col gap-0 p-0",
          preview
            ? "w-fit max-w-[95vw] sm:max-w-[95vw]"
            : "w-full sm:max-w-2xl",
        )}
      >
        <DialogHeader className="shrink-0 border-b px-6 py-4">
          <DialogTitle>Import Penyesuaian Stok</DialogTitle>
        </DialogHeader>

        <ScrollArea className="min-h-0 flex-1">
          <div className="flex flex-col gap-4 p-6">
            {}
            <div className="sr-only" aria-hidden="true">
              <UserSelect
                value={createdBy}
                onChange={setCreatedBy}
                defaultToSelf
              />
            </div>

            {!preview && (
              <>
                {}
                <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
                  <div className="flex flex-col gap-1.5">
                    <Label className="text-sm font-medium">
                      Tgl. Transaksi <span className="text-destructive">*</span>
                    </Label>
                    <Input
                      type="date"
                      value={transactionDate}
                      onChange={(e) => setTransactionDate(e.target.value)}
                    />
                  </div>
                  <div className="flex flex-col gap-1.5">
                    <Label className="text-sm font-medium">
                      Lokasi <span className="text-destructive">*</span>
                    </Label>
                    <Combobox
                      options={locationOptions}
                      value={locationId}
                      onChange={(v) => {
                        setLocationId(v ?? "");
                        setPreview(null);
                      }}
                      placeholder="Pilih lokasi…"
                      searchPlaceholder="Cari lokasi…"
                    />
                  </div>
                  <div className="flex flex-col gap-1.5">
                    <Label className="text-sm font-medium">
                      No. Penyesuaian
                    </Label>
                    <Input
                      value={adjustmentNo}
                      onChange={(e) => setAdjustmentNo(e.target.value)}
                      onFocus={(e) => {
                        if (e.target.value === "[auto]") setAdjustmentNo("");
                      }}
                      onBlur={(e) => {
                        if (e.target.value.trim() === "")
                          setAdjustmentNo("[auto]");
                      }}
                    />
                  </div>
                  <div className="flex flex-col gap-1.5">
                    <Label className="text-sm font-medium">Keterangan</Label>
                    <Input
                      value={notes}
                      onChange={(e) => setNotes(e.target.value)}
                      placeholder="Alasan koreksi (opsional)"
                    />
                  </div>
                </div>

                {}
                <div
                  onDragOver={(e) => e.preventDefault()}
                  onDrop={handleDropFile}
                  onClick={() => fileRef.current?.click()}
                  className={cn(
                    "flex cursor-pointer flex-col items-center justify-center gap-2 rounded-lg border border-dashed border-border py-8 text-center transition-colors hover:border-primary/50 hover:bg-primary/[0.03]",
                    !locationId && "opacity-60",
                  )}
                >
                  <UploadCloudIcon className="h-7 w-7 text-muted-foreground/50" />
                  {file ? (
                    <>
                      <p className="text-sm font-medium">{file.name}</p>
                      <p className="text-xs text-muted-foreground">
                        {(file.size / 1024).toFixed(1)} KB — klik untuk ganti
                      </p>
                    </>
                  ) : (
                    <>
                      <p className="text-sm font-medium">
                        Klik atau drag file .xlsx di sini
                      </p>
                      <p className="text-xs text-muted-foreground">
                        {locationId
                          ? "Maksimal 1000 baris"
                          : "Pilih lokasi dulu untuk mulai upload"}
                      </p>
                    </>
                  )}
                  <input
                    ref={fileRef}
                    type="file"
                    accept=".xlsx"
                    className="hidden"
                    disabled={!locationId}
                    onChange={(e) =>
                      handlePickFile(e.target.files?.[0] ?? null)
                    }
                  />
                </div>

                {}
                <div className="rounded-lg border border-border bg-muted/30 px-4 py-3">
                  <p className="mb-1 text-sm font-medium">
                    Isi salah satu <span className="font-mono">delta_qty</span>{" "}
                    atau <span className="font-mono">final_qty</span> per baris.
                  </p>
                  <p className="mb-2 text-xs text-muted-foreground">
                    Untuk mempermudah pengisian data, gunakan template yang
                    telah kami sediakan:
                  </p>
                  <button
                    type="button"
                    onClick={() =>
                      StockAdjustmentImportService.downloadTemplate()
                    }
                    className="inline-flex items-center gap-1.5 text-sm text-primary hover:underline"
                  >
                    <DownloadIcon className="size-4" />
                    Template Import Penyesuaian Stok
                  </button>
                </div>
              </>
            )}

            {preview && <PreviewPanel preview={preview} />}
          </div>
        </ScrollArea>

        <div className="shrink-0 border-t px-6 py-3">
          <div className="flex items-center justify-end gap-2">
            {preview ? (
              <>
                <Button variant="outline" onClick={() => setPreview(null)}>
                  {preview.errors.length > 0
                    ? "Batal & Upload Ulang"
                    : "Kembali"}
                </Button>
                <Button
                  onClick={handleConfirm}
                  disabled={!canConfirm}
                  className="gap-1.5"
                >
                  {confirmMut.isPending && (
                    <Loader2Icon className="size-4 animate-spin" />
                  )}
                  {preview.errors.length > 0
                    ? `Terdapat ${preview.errors.length} error`
                    : `Konfirmasi Import (${preview.items.length} item)`}
                </Button>
              </>
            ) : (
              <div className="flex w-full items-center justify-end gap-2">
                <Button variant="outline" onClick={() => handleClose(false)}>
                  Batal
                </Button>
                <Button
                  onClick={handlePreview}
                  disabled={!canPreview}
                  className="gap-1.5"
                >
                  {previewMut.isPending && (
                    <Loader2Icon className="size-4 animate-spin" />
                  )}
                  <FileSpreadsheetIcon className="size-4" /> Import
                </Button>
              </div>
            )}
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

